INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1,'中华人民共和国劳动合同法','第十条',10,'劳动合同','第二章 劳动合同的订立','建立劳动关系，应当订立书面劳动合同。\n已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。\n用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。','书面劳动合同 一个月 用工','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-14 20:41:08','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2,'中华人民共和国劳动合同法','第十九条',19,'劳动合同','第二章 劳动合同的订立','劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。\n同一用人单位与同一劳动者只能约定一次试用期。\n以完成一定工作任务为期限的劳动合同或者劳动合同期限不满三个月的，不得约定试用期。\n试用期包含在劳动合同期限内。劳动合同仅约定试用期的，试用期不成立，该期限为劳动合同期限。','第十九条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-14 20:41:08','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3,'中华人民共和国劳动合同法','第二十条',20,'劳动合同','第二章 劳动合同的订立','劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。','第二十条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-14 20:41:08','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4,'中华人民共和国劳动合同法','第三十七条',37,'劳动合同','第四章 劳动合同的解除和终止','劳动者提前三十日以书面形式通知用人单位，可以解除劳动合同。劳动者在试用期内提前三日通知用人单位，可以解除劳动合同。','第三十七条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-14 20:41:08','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (5,'中华人民共和国劳动合同法','第三十八条',38,'劳动合同','第四章 劳动合同的解除和终止','用人单位有下列情形之一的，劳动者可以解除劳动合同：\n（一）未按照劳动合同约定提供劳动保护或者劳动条件的；\n（二）未及时足额支付劳动报酬的；\n（三）未依法为劳动者缴纳社会保险费的；\n（四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的；\n（五）因本法第二十六条第一款规定的情形致使劳动合同无效的；\n（六）法律、行政法规规定劳动者可以解除劳动合同的其他情形。\n用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的，或者用人单位违章指挥、强令冒险作业危及劳动者人身安全的，劳动者可以立即解除劳动合同，不需事先告知用人单位。','第三十八条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-14 20:41:08','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (6,'中华人民共和国劳动合同法','第三十九条',39,'劳动合同','第四章 劳动合同的解除和终止','劳动者有下列情形之一的，用人单位可以解除劳动合同：\n（一）在试用期间被证明不符合录用条件的；\n（二）严重违反用人单位的规章制度的；\n（三）严重失职，营私舞弊，给用人单位造成重大损害的；\n（四）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的；\n（五）因本法第二十六条第一款第一项规定的情形致使劳动合同无效的；\n（六）被依法追究刑事责任的。','第三十九条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-14 20:41:08','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (7,'中华人民共和国劳动合同法','第四十七条',47,'劳动合同','第四章 劳动合同的解除和终止','经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。\n劳动者月工资高于用人单位所在直辖市、设区的市级人民政府公布的本地区上年度职工月平均工资三倍的，向其支付经济补偿的标准按职工月平均工资三倍的数额支付，向其支付经济补偿的年限最高不超过十二年。\n本条所称月工资是指劳动者在劳动合同解除或者终止前十二个月的平均工资。','第四十七条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-14 20:41:08','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (8,'中华人民共和国劳动合同法','第八十二条',82,'劳动合同','第七章 法律责任','用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。\n用人单位违反本法规定不与劳动者订立无固定期限劳动合同的，自应当订立无固定期限劳动合同之日起向劳动者每月支付二倍的工资。','二倍工资 未签合同','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-14 20:41:08','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (9,'中华人民共和国劳动合同法','第八十七条',87,'劳动合同','第七章 法律责任','用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。','违法解除 二倍赔偿金 2N','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-14 20:41:08','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (10,'中华人民共和国劳动合同法','第二十三条',23,'劳动合同','第二章 劳动合同的订立','用人单位与劳动者可以在劳动合同中约定保守用人单位的商业秘密和与知识产权相关的保密事项。\n对负有保密义务的劳动者，用人单位可以在劳动合同或者保密协议中与劳动者约定竞业限制条款，并约定在解除或者终止劳动合同后，在竞业限制期限内按月给予劳动者经济补偿。劳动者违反竞业限制约定的，应当按照约定向用人单位支付违约金。','竞业限制 保密 补偿','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-14 20:41:08','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (11,'中华人民共和国劳动合同法','第九条',9,'劳动合同','第二章 劳动合同的订立','用人单位招用劳动者，不得扣押劳动者的居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物。','扣押证件 押金 担保','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-14 20:41:08','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (12,'中华人民共和国劳动法','第四十四条',44,'其他','第四章 工作时间和休息休假','有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬：\n（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬；\n（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬；\n（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。','第四十四条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-14 20:41:08','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (13,'中华人民共和国社会保险法','第五十八条',58,'社会保险','第七章 社会保险费征缴','用人单位应当自用工之日起三十日内为其职工向社会保险经办机构申请办理社会保险登记。未办理社会保险登记的，由社会保险经办机构核定其应当缴纳的社会保险费。\n自愿参加社会保险的无雇工的个体工商户、未在用人单位参加社会保险的非全日制从业人员以及其他灵活就业人员，应当向社会保险经办机构申请办理社会保险登记。\n国家建立全国统一的个人社会保障号码。个人社会保障号码为公民身份号码。','第五十八条','2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-14 20:41:08','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (14,'中华人民共和国劳动争议调解仲裁法','第二十七条',27,'其他','第二节 申请和受理','劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。\n前款规定的仲裁时效，因当事人一方向对方当事人主张权利，或者向有关部门请求权利救济，或者对方当事人同意履行义务而中断。从中断时起，仲裁时效期间重新计算。\n因不可抗力或者有其他正当理由，当事人不能在本条第一款规定的仲裁时效期间申请仲裁的，仲裁时效中止。从中止时效的原因消除之日起，仲裁时效期间继续计算。\n劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。','仲裁时效 一年 拖欠工资','2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-14 20:41:08','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (873,'中华人民共和国劳动法','第一条',1,'其他','第一章 总 则','为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (874,'中华人民共和国劳动法','第二条',2,'其他','第一章 总 则','在中华人民共和国境内的企业、个体经济组织（以下统称用人单位）和与之形成劳动关系的劳动者，适用本法。\n国家机关、事业组织、社会团体和与之建立劳动合同关系的劳动者，依照本法执行。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (875,'中华人民共和国劳动法','第三条',3,'其他','第一章 总 则','劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。\n劳动者应当完成劳动任务，提高职业技能，执行劳动安全卫生规程，遵守劳动纪律和职业道德。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (876,'中华人民共和国劳动法','第四条',4,'其他','第一章 总 则','用人单位应当依法建立和完善规章制度，保障劳动者享有劳动权利和履行劳动义务。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (877,'中华人民共和国劳动法','第五条',5,'其他','第一章 总 则','国家采取各种措施，促进劳动就业，发展职业教育，制定劳动标准，调节社会收入，完善社会保险，协调劳动关系，逐步提高劳动者的生活水平。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (878,'中华人民共和国劳动法','第六条',6,'其他','第一章 总 则','国家提倡劳动者参加社会义务劳动，开展劳动竞赛和合理化建议活动，鼓励和保护劳动者进行科学研究、技术革新和发明创造，表彰和奖励劳动模范和先进工作者。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (879,'中华人民共和国劳动法','第七条',7,'其他','第一章 总 则','劳动者有权依法参加和组织工会。\n工会代表和维护劳动者的合法权益，依法独立自主地开展活动。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (880,'中华人民共和国劳动法','第八条',8,'其他','第一章 总 则','劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (881,'中华人民共和国劳动法','第九条',9,'其他','第一章 总 则','国务院劳动行政部门主管全国劳动工作。\n县级以上地方人民政府劳动行政部门主管本行政区域内的劳动工作。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (882,'中华人民共和国劳动法','第十条',10,'其他','第二章 促进就业','国家通过促进经济和社会发展，创造就业条件，扩大就业机会。\n国家鼓励企业、事业组织、社会团体在法律、行政法规规定的范围内兴办产业或者拓展经营，增加就业。\n国家支持劳动者自愿组织起来就业和从事个体经营实现就业。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (883,'中华人民共和国劳动法','第十一条',11,'其他','第二章 促进就业','地方各级人民政府应当采取措施，发展多种类型的职业介绍机构，提供就业服务。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (884,'中华人民共和国劳动法','第十二条',12,'其他','第二章 促进就业','劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (885,'中华人民共和国劳动法','第十三条',13,'其他','第二章 促进就业','妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (886,'中华人民共和国劳动法','第十四条',14,'其他','第二章 促进就业','残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (887,'中华人民共和国劳动法','第十五条',15,'其他','第二章 促进就业','禁止用人单位招用未满十六周岁的未成年人。\n文艺、体育和特种工艺单位招用未满十六周岁的未成年人，必须遵守国家有关规定，并保障其接受义务教育的权利。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (888,'中华人民共和国劳动法','第十六条',16,'其他','第三章 劳动合同和集体合同','劳动合同是劳动者与用人单位确立劳动关系、明确双方权利和义务的协议。\n建立劳动关系应当订立劳动合同。','第十六条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (889,'中华人民共和国劳动法','第十七条',17,'其他','第三章 劳动合同和集体合同','订立和变更劳动合同，应当遵循平等自愿、协商一致的原则，不得违反法律、行政法规的规定。\n劳动合同依法订立即具有法律约束力，当事人必须履行劳动合同规定的义务。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (890,'中华人民共和国劳动法','第十八条',18,'其他','第三章 劳动合同和集体合同','下列劳动合同无效：\n（一）违反法律、行政法规的劳动合同；\n（二）采取欺诈、威胁等手段订立的劳动合同。\n无效的劳动合同，从订立的时候起，就没有法律约束力。确认劳动合同部分无效的，如果不影响其余部分的效力，其余部分仍然有效。\n劳动合同的无效，由劳动争议仲裁委员会或者人民法院确认。','第十八条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (891,'中华人民共和国劳动法','第十九条',19,'其他','第三章 劳动合同和集体合同','劳动合同应当以书面形式订立，并具备以下条款：\n（一）劳动合同期限；\n（二）工作内容；\n（三）劳动保护和劳动条件；\n（四）劳动报酬；\n（五）劳动纪律；\n（六）劳动合同终止的条件；\n（七）违反劳动合同的责任。\n劳动合同除前款规定的必备条款外，当事人可以协商约定其他内容。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (892,'中华人民共和国劳动法','第二十条',20,'其他','第三章 劳动合同和集体合同','劳动合同的期限分为有固定期限、无固定期限和以完成一定的工作为期限。\n劳动者在同一用人单位连续工作满十年以上，当事人双方同意续延劳动合同的，如果劳动者提出订立无固定期限的劳动合同，应当订立无固定期限的劳动合同。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (893,'中华人民共和国劳动法','第二十一条',21,'其他','第三章 劳动合同和集体合同','劳动合同可以约定试用期。试用期最长不得超过六个月。','第二十一条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (894,'中华人民共和国劳动法','第二十二条',22,'其他','第三章 劳动合同和集体合同','劳动合同当事人可以在劳动合同中约定保守用人单位商业秘密的有关事项。','第二十二条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (895,'中华人民共和国劳动法','第二十三条',23,'其他','第三章 劳动合同和集体合同','劳动合同期满或者当事人约定的劳动合同终止条件出现，劳动合同即行终止。','第二十三条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (896,'中华人民共和国劳动法','第二十四条',24,'其他','第三章 劳动合同和集体合同','经劳动合同当事人协商一致，劳动合同可以解除。','第二十四条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (897,'中华人民共和国劳动法','第二十五条',25,'其他','第三章 劳动合同和集体合同','劳动者有下列情形之一的，用人单位可以解除劳动合同：\n（一）在试用期间被证明不符合录用条件的；\n（二）严重违反劳动纪律或者用人单位规章制度的；\n（三）严重失职，营私舞弊，对用人单位利益造成重大损害的；\n（四）被依法追究刑事责任的。','第二十五条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (898,'中华人民共和国劳动法','第二十六条',26,'其他','第三章 劳动合同和集体合同','有下列情形之一的，用人单位可以解除劳动合同，但是应当提前三十日以书面形式通知劳动者本人：\n（一）劳动者患病或者非因工负伤，医疗期满后，不能从事原工作也不能从事由用人单位另行安排的工作的；\n（二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的；\n（三）劳动合同订立时所依据的客观情况发生重大变化，致使原劳动合同无法履行，经当事人协商不能就变更劳动合同达成协议的。','第二十六条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (899,'中华人民共和国劳动法','第二十七条',27,'其他','第三章 劳动合同和集体合同','用人单位濒临破产进行法定整顿期间或者生产经营状况发生严重困难，确需裁减人员的，应当提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见，经向劳动行政部门报告后，可以裁减人员。\n用人单位依据本条规定裁减人员，在六个月内录用人员的，应当优先录用被裁减的人员。','第二十七条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (900,'中华人民共和国劳动法','第二十八条',28,'其他','第三章 劳动合同和集体合同','用人单位依据本法第二十四条、第二十六条、第二十七条的规定解除劳动合同的，应当依照国家有关规定给予经济补偿。','第二十八条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (901,'中华人民共和国劳动法','第二十九条',29,'其他','第三章 劳动合同和集体合同','劳动者有下列情形之一的，用人单位不得依据本法第二十六条、第二十七条的规定解除劳动合同：\n（一）患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的；\n（二）患病或者负伤，在规定的医疗期内的；\n（三）女职工在孕期、产期、哺乳期内的；\n（四）法律、行政法规规定的其他情形。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (902,'中华人民共和国劳动法','第三十条',30,'其他','第三章 劳动合同和集体合同','用人单位解除劳动合同，工会认为不适当的，有权提出意见。如果用人单位违反法律、法规或者劳动合同，工会有权要求重新处理；劳动者申请仲裁或者提起诉讼的，工会应当依法给予支持和帮助。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (903,'中华人民共和国劳动法','第三十一条',31,'其他','第三章 劳动合同和集体合同','劳动者解除劳动合同，应当提前三十日以书面形式通知用人单位。','第三十一条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (904,'中华人民共和国劳动法','第三十二条',32,'其他','第三章 劳动合同和集体合同','有下列情形之一的，劳动者可以随时通知用人单位解除劳动合同：\n（一）在试用期内的；\n（二）用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动的；\n（三）用人单位未按照劳动合同约定支付劳动报酬或者提供劳动条件的。','第三十二条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (905,'中华人民共和国劳动法','第三十三条',33,'其他','第三章 劳动合同和集体合同','企业职工一方与企业可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项，签订集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。\n集体合同由工会代表职工与企业签订；没有建立工会的企业，由职工推举的代表与企业签订。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (906,'中华人民共和国劳动法','第三十四条',34,'其他','第三章 劳动合同和集体合同','集体合同签订后应当报送劳动行政部门；劳动行政部门自收到集体合同文本之日起十五日内未提出异议的，集体合同即行生效。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (907,'中华人民共和国劳动法','第三十五条',35,'其他','第三章 劳动合同和集体合同','依法签订的集体合同对企业和企业全体职工具有约束力。职工个人与企业订立的劳动合同中劳动条件和劳动报酬等标准不得低于集体合同的规定。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (908,'中华人民共和国劳动法','第三十六条',36,'其他','第四章 工作时间和休息休假','国家实行劳动者每日工作时间不超过八小时、平均每周工作时间不超过四十四小时的工时制度。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (909,'中华人民共和国劳动法','第三十七条',37,'其他','第四章 工作时间和休息休假','对实行计件工作的劳动者，用人单位应当根据本法第三十六条规定的工时制度合理确定其劳动定额和计件报酬标准。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (910,'中华人民共和国劳动法','第三十八条',38,'其他','第四章 工作时间和休息休假','用人单位应当保证劳动者每周至少休息一日。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (911,'中华人民共和国劳动法','第三十九条',39,'其他','第四章 工作时间和休息休假','企业因生产特点不能实行本法第三十六条、第三十八条规定的，经劳动行政部门批准，可以实行其他工作和休息办法。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (912,'中华人民共和国劳动法','第四十条',40,'其他','第四章 工作时间和休息休假','用人单位在下列节日期间应当依法安排劳动者休假：\n（一）元旦；\n（二）春节；\n（三）国际劳动节；\n（四）国庆节；\n（五）法律、法规规定的其他休假节日。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (913,'中华人民共和国劳动法','第四十一条',41,'其他','第四章 工作时间和休息休假','用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过三小时，但是每月不得超过三十六小时。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (914,'中华人民共和国劳动法','第四十二条',42,'其他','第四章 工作时间和休息休假','有下列情形之一的，延长工作时间不受本法第四十一条规定的限制：\n（一）发生自然灾害、事故或者因其他原因，威胁劳动者生命健康和财产安全，需要紧急处理的；\n（二）生产设备、交通运输线路、公共设施发生故障，影响生产和公众利益，必须及时抢修的；\n（三）法律、行政法规规定的其他情形。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (915,'中华人民共和国劳动法','第四十三条',43,'其他','第四章 工作时间和休息休假','用人单位不得违反本法规定延长劳动者的工作时间。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (917,'中华人民共和国劳动法','第四十五条',45,'其他','第四章 工作时间和休息休假','国家实行带薪年休假制度。\n劳动者连续工作一年以上的，享受带薪年休假。具体办法由国务院规定。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (918,'中华人民共和国劳动法','第四十六条',46,'其他','第五章 工 资','工资分配应当遵循按劳分配原则，实行同工同酬。\n工资水平在经济发展的基础上逐步提高。国家对工资总量实行宏观调控。','第四十六条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (919,'中华人民共和国劳动法','第四十七条',47,'其他','第五章 工 资','用人单位根据本单位的生产经营特点和经济效益，依法自主确定本单位的工资分配方式和工资水平。','第四十七条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (920,'中华人民共和国劳动法','第四十八条',48,'其他','第五章 工 资','国家实行最低工资保障制度。最低工资的具体标准由省、自治区、直辖市人民政府规定，报国务院备案。\n用人单位支付劳动者的工资不得低于当地最低工资标准。','第四十八条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (921,'中华人民共和国劳动法','第四十九条',49,'其他','第五章 工 资','确定和调整最低工资标准应当综合参考下列因素：\n（一）劳动者本人及平均赡养人口的最低生活费用；\n（二）社会平均工资水平；\n（三）劳动生产率；\n（四）就业状况；\n（五）地区之间经济发展水平的差异。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (922,'中华人民共和国劳动法','第五十条',50,'其他','第五章 工 资','工资应当以货币形式按月支付给劳动者本人。不得克扣或者无故拖欠劳动者的工资。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (923,'中华人民共和国劳动法','第五十一条',51,'其他','第五章 工 资','劳动者在法定休假日和婚丧假期间以及依法参加社会活动期间，用人单位应当依法支付工资。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (924,'中华人民共和国劳动法','第五十二条',52,'其他','第六章 劳动安全卫生','用人单位必须建立、健全劳动安全卫生制度，严格执行国家劳动安全卫生规程和标准，对劳动者进行劳动安全卫生教育，防止劳动过程中的事故，减少职业危害。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (925,'中华人民共和国劳动法','第五十三条',53,'其他','第六章 劳动安全卫生','劳动安全卫生设施必须符合国家规定的标准。\n新建、改建、扩建工程的劳动安全卫生设施必须与主体工程同时设计、同时施工、同时投入生产和使用。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (926,'中华人民共和国劳动法','第五十四条',54,'其他','第六章 劳动安全卫生','用人单位必须为劳动者提供符合国家规定的劳动安全卫生条件和必要的劳动防护用品，对从事有职业危害作业的劳动者应当定期进行健康检查。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (927,'中华人民共和国劳动法','第五十五条',55,'其他','第六章 劳动安全卫生','从事特种作业的劳动者必须经过专门培训并取得特种作业资格。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (928,'中华人民共和国劳动法','第五十六条',56,'其他','第六章 劳动安全卫生','劳动者在劳动过程中必须严格遵守安全操作规程。\n劳动者对用人单位管理人员违章指挥、强令冒险作业，有权拒绝执行；对危害生命安全和身体健康的行为，有权提出批评、检举和控告。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (929,'中华人民共和国劳动法','第五十七条',57,'其他','第六章 劳动安全卫生','国家建立伤亡事故和职业病统计报告和处理制度。县级以上各级人民政府劳动行政部门、有关部门和用人单位应当依法对劳动者在劳动过程中发生的伤亡事故和劳动者的职业病状况，进行统计、报告和处理。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (930,'中华人民共和国劳动法','第五十八条',58,'其他','第七章 女职工和未成年工特殊保护','国家对女职工和未成年工实行特殊劳动保护。\n未成年工是指年满十六周岁未满十八周岁的劳动者。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (931,'中华人民共和国劳动法','第五十九条',59,'其他','第七章 女职工和未成年工特殊保护','禁止安排女职工从事矿山井下、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (932,'中华人民共和国劳动法','第六十条',60,'其他','第七章 女职工和未成年工特殊保护','不得安排女职工在经期从事高处、低温、冷水作业和国家规定的第三级体力劳动强度的劳动。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (933,'中华人民共和国劳动法','第六十一条',61,'其他','第七章 女职工和未成年工特殊保护','不得安排女职工在怀孕期间从事国家规定的第三级体力劳动强度的劳动和孕期禁忌从事的劳动。对怀孕七个月以上的女职工，不得安排其延长工作时间和夜班劳动。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (934,'中华人民共和国劳动法','第六十二条',62,'其他','第七章 女职工和未成年工特殊保护','女职工生育享受不少于九十天的产假。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (935,'中华人民共和国劳动法','第六十三条',63,'其他','第七章 女职工和未成年工特殊保护','不得安排女职工在哺乳未满一周岁的婴儿期间从事国家规定的第三级体力劳动强度的劳动和哺乳期禁忌从事的其他劳动，不得安排其延长工作时间和夜班劳动。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (936,'中华人民共和国劳动法','第六十四条',64,'其他','第七章 女职工和未成年工特殊保护','不得安排未成年工从事矿山井下、有毒有害、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (937,'中华人民共和国劳动法','第六十五条',65,'其他','第七章 女职工和未成年工特殊保护','用人单位应当对未成年工定期进行健康检查。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (938,'中华人民共和国劳动法','第六十六条',66,'其他','第八章 职业培训','国家通过各种途径，采取各种措施，发展职业培训事业，开发劳动者的职业技能，提高劳动者素质，增强劳动者的就业能力和工作能力。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (939,'中华人民共和国劳动法','第六十七条',67,'其他','第八章 职业培训','各级人民政府应当把发展职业培训纳入社会经济发展的规划，鼓励和支持有条件的企业、事业组织、社会团体和个人进行各种形式的职业培训。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (940,'中华人民共和国劳动法','第六十八条',68,'其他','第八章 职业培训','用人单位应当建立职业培训制度，按照国家规定提取和使用职业培训经费，根据本单位实际，有计划地对劳动者进行职业培训。\n从事技术工种的劳动者，上岗前必须经过培训。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (941,'中华人民共和国劳动法','第六十九条',69,'其他','第八章 职业培训','国家确定职业分类，对规定的职业制定职业技能标准，实行职业资格证书制度，由经备案的考核鉴定机构负责对劳动者实施职业技能考核鉴定。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (942,'中华人民共和国劳动法','第七十条',70,'其他','第九章 社会保险和福利','国家发展社会保险事业，建立社会保险制度，设立社会保险基金，使劳动者在年老、患病、工伤、失业、生育等情况下获得帮助和补偿。','第七十条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (943,'中华人民共和国劳动法','第七十一条',71,'其他','第九章 社会保险和福利','社会保险水平应当与社会经济发展水平和社会承受能力相适应。','第七十一条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (944,'中华人民共和国劳动法','第七十二条',72,'其他','第九章 社会保险和福利','社会保险基金按照保险类型确定资金来源，逐步实行社会统筹。用人单位和劳动者必须依法参加社会保险，缴纳社会保险费。','第七十二条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (945,'中华人民共和国劳动法','第七十三条',73,'其他','第九章 社会保险和福利','劳动者在下列情形下，依法享受社会保险待遇：\n（一）退休；\n（二）患病、负伤；\n（三）因工伤残或者患职业病；\n（四）失业；\n（五）生育。\n劳动者死亡后，其遗属依法享受遗属津贴。\n劳动者享受社会保险待遇的条件和标准由法律、法规规定。\n劳动者享受的社会保险金必须按时足额支付。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (946,'中华人民共和国劳动法','第七十四条',74,'其他','第九章 社会保险和福利','社会保险基金经办机构依照法律规定收支、管理和运营社会保险基金，并负有使社会保险基金保值增值的责任。\n社会保险基金监督机构依照法律规定，对社会保险基金的收支、管理和运营实施监督。\n社会保险基金经办机构和社会保险基金监督机构的设立和职能由法律规定。\n任何组织和个人不得挪用社会保险基金。','第七十四条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (947,'中华人民共和国劳动法','第七十五条',75,'其他','第九章 社会保险和福利','国家鼓励用人单位根据本单位实际情况为劳动者建立补充保险。\n国家提倡劳动者个人进行储蓄性保险。','第七十五条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (948,'中华人民共和国劳动法','第七十六条',76,'其他','第九章 社会保险和福利','国家发展社会福利事业，兴建公共福利设施，为劳动者休息、休养和疗养提供条件。\n用人单位应当创造条件，改善集体福利，提高劳动者的福利待遇。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (949,'中华人民共和国劳动法','第七十七条',77,'其他','第十章 劳动争议','用人单位与劳动者发生劳动争议，当事人可以依法申请调解、仲裁、提起诉讼，也可以协商解决。\n调解原则适用于仲裁和诉讼程序。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (950,'中华人民共和国劳动法','第七十八条',78,'其他','第十章 劳动争议','解决劳动争议，应当根据合法、公正、及时处理的原则，依法维护劳动争议当事人的合法权益。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (951,'中华人民共和国劳动法','第七十九条',79,'其他','第十章 劳动争议','劳动争议发生后，当事人可以向本单位劳动争议调解委员会申请调解；调解不成，当事人一方要求仲裁的，可以向劳动争议仲裁委员会申请仲裁。当事人一方也可以直接向劳动争议仲裁委员会申请仲裁。对仲裁裁决不服的，可以向人民法院提起诉讼。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (952,'中华人民共和国劳动法','第八十条',80,'其他','第十章 劳动争议','在用人单位内，可以设立劳动争议调解委员会。劳动争议调解委员会由职工代表、用人单位代表和工会代表组成。劳动争议调解委员会主任由工会代表担任。\n劳动争议经调解达成协议的，当事人应当履行。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (953,'中华人民共和国劳动法','第八十一条',81,'其他','第十章 劳动争议','劳动争议仲裁委员会由劳动行政部门代表、同级工会代表、用人单位方面的代表组成。劳动争议仲裁委员会主任由劳动行政部门代表担任。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (954,'中华人民共和国劳动法','第八十二条',82,'其他','第十章 劳动争议','提出仲裁要求的一方应当自劳动争议发生之日起六十日内向劳动争议仲裁委员会提出书面申请。仲裁裁决一般应在收到仲裁申请的六十日内作出。对仲裁裁决无异议的，当事人必须履行。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (955,'中华人民共和国劳动法','第八十三条',83,'其他','第十章 劳动争议','劳动争议当事人对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。一方当事人在法定期限内不起诉又不履行仲裁裁决的，另一方当事人可以申请人民法院强制执行。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (956,'中华人民共和国劳动法','第八十四条',84,'其他','第十章 劳动争议','因签订集体合同发生争议，当事人协商解决不成的，当地人民政府劳动行政部门可以组织有关各方协调处理。\n因履行集体合同发生争议，当事人协商解决不成的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (957,'中华人民共和国劳动法','第八十五条',85,'其他','第十一章 监督检查','县级以上各级人民政府劳动行政部门依法对用人单位遵守劳动法律、法规的情况进行监督检查，对违反劳动法律、法规的行为有权制止，并责令改正。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (958,'中华人民共和国劳动法','第八十六条',86,'其他','第十一章 监督检查','县级以上各级人民政府劳动行政部门监督检查人员执行公务，有权进入用人单位了解执行劳动法律、法规的情况，查阅必要的资料，并对劳动场所进行检查。\n县级以上各级人民政府劳动行政部门监督检查人员执行公务，必须出示证件，秉公执法并遵守有关规定。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (959,'中华人民共和国劳动法','第八十七条',87,'其他','第十一章 监督检查','县级以上各级人民政府有关部门在各自职责范围内，对用人单位遵守劳动法律、法规的情况进行监督。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (960,'中华人民共和国劳动法','第八十八条',88,'其他','第十一章 监督检查','各级工会依法维护劳动者的合法权益，对用人单位遵守劳动法律、法规的情况进行监督。\n任何组织和个人对于违反劳动法律、法规的行为有权检举和控告。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (961,'中华人民共和国劳动法','第八十九条',89,'其他','第十二章 法律责任','用人单位制定的劳动规章制度违反法律、法规规定的，由劳动行政部门给予警告，责令改正；对劳动者造成损害的，应当承担赔偿责任。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (962,'中华人民共和国劳动法','第九十条',90,'其他','第十二章 法律责任','用人单位违反本法规定，延长劳动者工作时间的，由劳动行政部门给予警告，责令改正，并可以处以罚款。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (963,'中华人民共和国劳动法','第九十一条',91,'其他','第十二章 法律责任','用人单位有下列侵害劳动者合法权益情形之一的，由劳动行政部门责令支付劳动者的工资报酬、经济补偿，并可以责令支付赔偿金：\n（一）克扣或者无故拖欠劳动者工资的；\n（二）拒不支付劳动者延长工作时间工资报酬的；\n（三）低于当地最低工资标准支付劳动者工资的；\n（四）解除劳动合同后，未依照本法规定给予劳动者经济补偿的。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (964,'中华人民共和国劳动法','第九十二条',92,'其他','第十二章 法律责任','用人单位的劳动安全设施和劳动卫生条件不符合国家规定或者未向劳动者提供必要的劳动防护用品和劳动保护设施的，由劳动行政部门或者有关部门责令改正，可以处以罚款；情节严重的，提请县级以上人民政府决定责令停产整顿；对事故隐患不采取措施，致使发生重大事故，造成劳动者生命和财产损失的，对责任人员依照刑法有关规定追究刑事责任。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (965,'中华人民共和国劳动法','第九十三条',93,'其他','第十二章 法律责任','用人单位强令劳动者违章冒险作业，发生重大伤亡事故，造成严重后果的，对责任人员依法追究刑事责任。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (966,'中华人民共和国劳动法','第九十四条',94,'其他','第十二章 法律责任','用人单位非法招用未满十六周岁的未成年人的，由劳动行政部门责令改正，处以罚款；情节严重的，由市场监督管理部门吊销营业执照。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (967,'中华人民共和国劳动法','第九十五条',95,'其他','第十二章 法律责任','用人单位违反本法对女职工和未成年工的保护规定，侵害其合法权益的，由劳动行政部门责令改正，处以罚款；对女职工或者未成年工造成损害的，应当承担赔偿责任。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (968,'中华人民共和国劳动法','第九十六条',96,'其他','第十二章 法律责任','用人单位有下列行为之一，由公安机关对责任人员处以十五日以下拘留、罚款或者警告；构成犯罪的，对责任人员依法追究刑事责任：\n（一）以暴力、威胁或者非法限制人身自由的手段强迫劳动的；\n（二）侮辱、体罚、殴打、非法搜查和拘禁劳动者的。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (969,'中华人民共和国劳动法','第九十七条',97,'其他','第十二章 法律责任','由于用人单位的原因订立的无效合同，对劳动者造成损害的，应当承担赔偿责任。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (970,'中华人民共和国劳动法','第九十八条',98,'其他','第十二章 法律责任','用人单位违反本法规定的条件解除劳动合同或者故意拖延不订立劳动合同的，由劳动行政部门责令改正；对劳动者造成损害的，应当承担赔偿责任。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (971,'中华人民共和国劳动法','第九十九条',99,'其他','第十二章 法律责任','用人单位招用尚未解除劳动合同的劳动者，对原用人单位造成经济损失的，该用人单位应当依法承担连带赔偿责任。','第九十九条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (972,'中华人民共和国劳动法','第一百条',100,'其他','第十二章 法律责任','用人单位无故不缴纳社会保险费的，由劳动行政部门责令其限期缴纳；逾期不缴的，可以加收滞纳金。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (973,'中华人民共和国劳动法','第一百零一条',101,'其他','第十二章 法律责任','用人单位无理阻挠劳动行政部门、有关部门及其工作人员行使监督检查权，打击报复举报人员的，由劳动行政部门或者有关部门处以罚款；构成犯罪的，对责任人员依法追究刑事责任。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (974,'中华人民共和国劳动法','第一百零二条',102,'其他','第十二章 法律责任','劳动者违反本法规定的条件解除劳动合同或者违反劳动合同中约定的保密事项，对用人单位造成经济损失的，应当依法承担赔偿责任。','第一百零二条','2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (975,'中华人民共和国劳动法','第一百零三条',103,'其他','第十二章 法律责任','劳动行政部门或者有关部门的工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (976,'中华人民共和国劳动法','第一百零四条',104,'其他','第十二章 法律责任','国家工作人员和社会保险基金经办机构的工作人员挪用社会保险基金，构成犯罪的，依法追究刑事责任。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (977,'中华人民共和国劳动法','第一百零五条',105,'其他','第十二章 法律责任','违反本法规定侵害劳动者合法权益，其他法律、行政法规已规定处罚的，依照该法律、行政法规的规定处罚。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (978,'中华人民共和国劳动法','第一百零六条',106,'其他','第十三章 附 则','省、自治区、直辖市人民政府根据本法和本地区的实际情况，规定劳动合同制度的实施步骤，报国务院备案。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (979,'中华人民共和国劳动法','第一百零七条',107,'其他','第十三章 附 则','本法自1995年1月1日起施行。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f20f16ee11737','2026-09-16 20:35:47','2026-09-17 16:49:52');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (980,'中华人民共和国社会保险法','第一条',1,'社会保险','第一章 总 则','为了规范社会保险关系，维护公民参加社会保险和享受社会保险待遇的合法权益，使公民共享发展成果，促进社会和谐稳定，根据宪法，制定本法。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (981,'中华人民共和国社会保险法','第二条',2,'社会保险','第一章 总 则','国家建立基本养老保险、基本医疗保险、工伤保险、失业保险、生育保险等社会保险制度，保障公民在年老、疾病、工伤、失业、生育等情况下依法从国家和社会获得物质帮助的权利。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (982,'中华人民共和国社会保险法','第三条',3,'社会保险','第一章 总 则','社会保险制度坚持广覆盖、保基本、多层次、可持续的方针，社会保险水平应当与经济社会发展水平相适应。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (983,'中华人民共和国社会保险法','第四条',4,'社会保险','第一章 总 则','中华人民共和国境内的用人单位和个人依法缴纳社会保险费，有权查询缴费记录、个人权益记录，要求社会保险经办机构提供社会保险咨询等相关服务。\n个人依法享受社会保险待遇，有权监督本单位为其缴费情况。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (984,'中华人民共和国社会保险法','第五条',5,'社会保险','第一章 总 则','县级以上人民政府将社会保险事业纳入国民经济和社会发展规划。\n国家多渠道筹集社会保险资金。县级以上人民政府对社会保险事业给予必要的经费支持。\n国家通过税收优惠政策支持社会保险事业。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (985,'中华人民共和国社会保险法','第六条',6,'社会保险','第一章 总 则','国家对社会保险基金实行严格监管。\n国务院和省、自治区、直辖市人民政府建立健全社会保险基金监督管理制度，保障社会保险基金安全、有效运行。\n县级以上人民政府采取措施，鼓励和支持社会各方面参与社会保险基金的监督。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (986,'中华人民共和国社会保险法','第七条',7,'社会保险','第一章 总 则','国务院社会保险行政部门负责全国的社会保险管理工作，国务院其他有关部门在各自的职责范围内负责有关的社会保险工作。\n县级以上地方人民政府社会保险行政部门负责本行政区域的社会保险管理工作，县级以上地方人民政府其他有关部门在各自的职责范围内负责有关的社会保险工作。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (987,'中华人民共和国社会保险法','第八条',8,'社会保险','第一章 总 则','社会保险经办机构提供社会保险服务，负责社会保险登记、个人权益记录、社会保险待遇支付等工作。','第八条','2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (988,'中华人民共和国社会保险法','第九条',9,'社会保险','第一章 总 则','工会依法维护职工的合法权益，有权参与社会保险重大事项的研究，参加社会保险监督委员会，对与职工社会保险权益有关的事项进行监督。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (989,'中华人民共和国社会保险法','第十条',10,'社会保险','第二章 基本养老保险','职工应当参加基本养老保险，由用人单位和职工共同缴纳基本养老保险费。\n无雇工的个体工商户、未在用人单位参加基本养老保险的非全日制从业人员以及其他灵活就业人员可以参加基本养老保险，由个人缴纳基本养老保险费。\n公务员和参照公务员法管理的工作人员养老保险的办法由国务院规定。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (990,'中华人民共和国社会保险法','第十一条',11,'社会保险','第二章 基本养老保险','基本养老保险实行社会统筹与个人账户相结合。\n基本养老保险基金由用人单位和个人缴费以及政府补贴等组成。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (991,'中华人民共和国社会保险法','第十二条',12,'社会保险','第二章 基本养老保险','用人单位应当按照国家规定的本单位职工工资总额的比例缴纳基本养老保险费，记入基本养老保险统筹基金。\n职工应当按照国家规定的本人工资的比例缴纳基本养老保险费，记入个人账户。\n无雇工的个体工商户、未在用人单位参加基本养老保险的非全日制从业人员以及其他灵活就业人员参加基本养老保险的，应当按照国家规定缴纳基本养老保险费，分别记入基本养老保险统筹基金和个人账户。','第十二条','2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (992,'中华人民共和国社会保险法','第十三条',13,'社会保险','第二章 基本养老保险','国有企业、事业单位职工参加基本养老保险前，视同缴费年限期间应当缴纳的基本养老保险费由政府承担。\n基本养老保险基金出现支付不足时，政府给予补贴。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (993,'中华人民共和国社会保险法','第十四条',14,'社会保险','第二章 基本养老保险','个人账户不得提前支取，记账利率不得低于银行定期存款利率，免征利息税。个人死亡的，个人账户余额可以继承。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (994,'中华人民共和国社会保险法','第十五条',15,'社会保险','第二章 基本养老保险','基本养老金由统筹养老金和个人账户养老金组成。\n基本养老金根据个人累计缴费年限、缴费工资、当地职工平均工资、个人账户金额、城镇人口平均预期寿命等因素确定。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (995,'中华人民共和国社会保险法','第十六条',16,'社会保险','第二章 基本养老保险','参加基本养老保险的个人，达到法定退休年龄时累计缴费满十五年的，按月领取基本养老金。\n参加基本养老保险的个人，达到法定退休年龄时累计缴费不足十五年的，可以缴费至满十五年，按月领取基本养老金；也可以转入新型农村社会养老保险或者城镇居民社会养老保险，按照国务院规定享受相应的养老保险待遇。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (996,'中华人民共和国社会保险法','第十七条',17,'社会保险','第二章 基本养老保险','参加基本养老保险的个人，因病或者非因工死亡的，其遗属可以领取丧葬补助金和抚恤金；在未达到法定退休年龄时因病或者非因工致残完全丧失劳动能力的，可以领取病残津贴。所需资金从基本养老保险基金中支付。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (997,'中华人民共和国社会保险法','第十八条',18,'社会保险','第二章 基本养老保险','国家建立基本养老金正常调整机制。根据职工平均工资增长、物价上涨情况，适时提高基本养老保险待遇水平。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (998,'中华人民共和国社会保险法','第十九条',19,'社会保险','第二章 基本养老保险','个人跨统筹地区就业的，其基本养老保险关系随本人转移，缴费年限累计计算。个人达到法定退休年龄时，基本养老金分段计算、统一支付。具体办法由国务院规定。','第十九条','2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (999,'中华人民共和国社会保险法','第二十条',20,'社会保险','第二章 基本养老保险','国家建立和完善新型农村社会养老保险制度。\n新型农村社会养老保险实行个人缴费、集体补助和政府补贴相结合。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1000,'中华人民共和国社会保险法','第二十一条',21,'社会保险','第二章 基本养老保险','新型农村社会养老保险待遇由基础养老金和个人账户养老金组成。\n参加新型农村社会养老保险的农村居民，符合国家规定条件的，按月领取新型农村社会养老保险待遇。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1001,'中华人民共和国社会保险法','第二十二条',22,'社会保险','第二章 基本养老保险','国家建立和完善城镇居民社会养老保险制度。\n省、自治区、直辖市人民政府根据实际情况，可以将城镇居民社会养老保险和新型农村社会养老保险合并实施。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1002,'中华人民共和国社会保险法','第二十三条',23,'社会保险','第三章 基本医疗保险','职工应当参加职工基本医疗保险，由用人单位和职工按照国家规定共同缴纳基本医疗保险费。\n无雇工的个体工商户、未在用人单位参加职工基本医疗保险的非全日制从业人员以及其他灵活就业人员可以参加职工基本医疗保险，由个人按照国家规定缴纳基本医疗保险费。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1003,'中华人民共和国社会保险法','第二十四条',24,'社会保险','第三章 基本医疗保险','国家建立和完善新型农村合作医疗制度。\n新型农村合作医疗的管理办法，由国务院规定。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1004,'中华人民共和国社会保险法','第二十五条',25,'社会保险','第三章 基本医疗保险','国家建立和完善城镇居民基本医疗保险制度。\n城镇居民基本医疗保险实行个人缴费和政府补贴相结合。\n享受最低生活保障的人、丧失劳动能力的残疾人、低收入家庭六十周岁以上的老年人和未成年人等所需个人缴费部分，由政府给予补贴。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1005,'中华人民共和国社会保险法','第二十六条',26,'社会保险','第三章 基本医疗保险','职工基本医疗保险、新型农村合作医疗和城镇居民基本医疗保险的待遇标准按照国家规定执行。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1006,'中华人民共和国社会保险法','第二十七条',27,'社会保险','第三章 基本医疗保险','参加职工基本医疗保险的个人，达到法定退休年龄时累计缴费达到国家规定年限的，退休后不再缴纳基本医疗保险费，按照国家规定享受基本医疗保险待遇；未达到国家规定年限的，可以缴费至国家规定年限。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1007,'中华人民共和国社会保险法','第二十八条',28,'社会保险','第三章 基本医疗保险','符合基本医疗保险药品目录、诊疗项目、医疗服务设施标准以及急诊、抢救的医疗费用，按照国家规定从基本医疗保险基金中支付。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1008,'中华人民共和国社会保险法','第二十九条',29,'社会保险','第三章 基本医疗保险','参保人员医疗费用中应当由基本医疗保险基金支付的部分，由社会保险经办机构与医疗机构、药品经营单位直接结算。\n社会保险行政部门和卫生行政部门应当建立异地就医医疗费用结算制度，方便参保人员享受基本医疗保险待遇。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1009,'中华人民共和国社会保险法','第三十条',30,'社会保险','第三章 基本医疗保险','下列医疗费用不纳入基本医疗保险基金支付范围：\n（一）应当从工伤保险基金中支付的；\n（二）应当由第三人负担的；\n（三）应当由公共卫生负担的；\n（四）在境外就医的。\n医疗费用依法应当由第三人负担，第三人不支付或者无法确定第三人的，由基本医疗保险基金先行支付。基本医疗保险基金先行支付后，有权向第三人追偿。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1010,'中华人民共和国社会保险法','第三十一条',31,'社会保险','第三章 基本医疗保险','社会保险经办机构根据管理服务的需要，可以与医疗机构、药品经营单位签订服务协议，规范医疗服务行为。\n医疗机构应当为参保人员提供合理、必要的医疗服务。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1011,'中华人民共和国社会保险法','第三十二条',32,'社会保险','第三章 基本医疗保险','个人跨统筹地区就业的，其基本医疗保险关系随本人转移，缴费年限累计计算。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1012,'中华人民共和国社会保险法','第三十三条',33,'社会保险','第四章 工伤保险','职工应当参加工伤保险，由用人单位缴纳工伤保险费，职工不缴纳工伤保险费。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1013,'中华人民共和国社会保险法','第三十四条',34,'社会保险','第四章 工伤保险','国家根据不同行业的工伤风险程度确定行业的差别费率，并根据使用工伤保险基金、工伤发生率等情况在每个行业内确定费率档次。行业差别费率和行业内费率档次由国务院社会保险行政部门制定，报国务院批准后公布施行。\n社会保险经办机构根据用人单位使用工伤保险基金、工伤发生率和所属行业费率档次等情况，确定用人单位缴费费率。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1014,'中华人民共和国社会保险法','第三十五条',35,'社会保险','第四章 工伤保险','用人单位应当按照本单位职工工资总额，根据社会保险经办机构确定的费率缴纳工伤保险费。','第三十五条','2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1015,'中华人民共和国社会保险法','第三十六条',36,'社会保险','第四章 工伤保险','职工因工作原因受到事故伤害或者患职业病，且经工伤认定的，享受工伤保险待遇；其中，经劳动能力鉴定丧失劳动能力的，享受伤残待遇。\n工伤认定和劳动能力鉴定应当简捷、方便。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1016,'中华人民共和国社会保险法','第三十七条',37,'社会保险','第四章 工伤保险','职工因下列情形之一导致本人在工作中伤亡的，不认定为工伤：\n（一）故意犯罪；\n（二）醉酒或者吸毒；\n（三）自残或者自杀；\n（四）法律、行政法规规定的其他情形。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1017,'中华人民共和国社会保险法','第三十八条',38,'社会保险','第四章 工伤保险','因工伤发生的下列费用，按照国家规定从工伤保险基金中支付：\n（一）治疗工伤的医疗费用和康复费用；\n（二）住院伙食补助费；\n（三）到统筹地区以外就医的交通食宿费；\n（四）安装配置伤残辅助器具所需费用；\n（五）生活不能自理的，经劳动能力鉴定委员会确认的生活护理费；\n（六）一次性伤残补助金和一至四级伤残职工按月领取的伤残津贴；\n（七）终止或者解除劳动合同时，应当享受的一次性医疗补助金；\n（八）因工死亡的，其遗属领取的丧葬补助金、供养亲属抚恤金和因工死亡补助金；\n（九）劳动能力鉴定费。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1018,'中华人民共和国社会保险法','第三十九条',39,'社会保险','第四章 工伤保险','因工伤发生的下列费用，按照国家规定由用人单位支付：\n（一）治疗工伤期间的工资福利；\n（二）五级、六级伤残职工按月领取的伤残津贴；\n（三）终止或者解除劳动合同时，应当享受的一次性伤残就业补助金。','第三十九条','2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1019,'中华人民共和国社会保险法','第四十条',40,'社会保险','第四章 工伤保险','工伤职工符合领取基本养老金条件的，停发伤残津贴，享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，从工伤保险基金中补足差额。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1020,'中华人民共和国社会保险法','第四十一条',41,'社会保险','第四章 工伤保险','职工所在用人单位未依法缴纳工伤保险费，发生工伤事故的，由用人单位支付工伤保险待遇。用人单位不支付的，从工伤保险基金中先行支付。\n从工伤保险基金中先行支付的工伤保险待遇应当由用人单位偿还。用人单位不偿还的，社会保险经办机构可以依照本法第六十三条的规定追偿。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1021,'中华人民共和国社会保险法','第四十二条',42,'社会保险','第四章 工伤保险','由于第三人的原因造成工伤，第三人不支付工伤医疗费用或者无法确定第三人的，由工伤保险基金先行支付。工伤保险基金先行支付后，有权向第三人追偿。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1022,'中华人民共和国社会保险法','第四十三条',43,'社会保险','第四章 工伤保险','工伤职工有下列情形之一的，停止享受工伤保险待遇：\n（一）丧失享受待遇条件的；\n（二）拒不接受劳动能力鉴定的；\n（三）拒绝治疗的。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1023,'中华人民共和国社会保险法','第四十四条',44,'社会保险','第五章 失业保险','职工应当参加失业保险，由用人单位和职工按照国家规定共同缴纳失业保险费。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1024,'中华人民共和国社会保险法','第四十五条',45,'社会保险','第五章 失业保险','失业人员符合下列条件的，从失业保险基金中领取失业保险金：\n（一）失业前用人单位和本人已经缴纳失业保险费满一年的；\n（二）非因本人意愿中断就业的；\n（三）已经进行失业登记，并有求职要求的。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1025,'中华人民共和国社会保险法','第四十六条',46,'社会保险','第五章 失业保险','失业人员失业前用人单位和本人累计缴费满一年不足五年的，领取失业保险金的期限最长为十二个月；累计缴费满五年不足十年的，领取失业保险金的期限最长为十八个月；累计缴费十年以上的，领取失业保险金的期限最长为二十四个月。重新就业后，再次失业的，缴费时间重新计算，领取失业保险金的期限与前次失业应当领取而尚未领取的失业保险金的期限合并计算，最长不超过二十四个月。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1026,'中华人民共和国社会保险法','第四十七条',47,'社会保险','第五章 失业保险','失业保险金的标准，由省、自治区、直辖市人民政府确定，不得低于城市居民最低生活保障标准。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1027,'中华人民共和国社会保险法','第四十八条',48,'社会保险','第五章 失业保险','失业人员在领取失业保险金期间，参加职工基本医疗保险，享受基本医疗保险待遇。\n失业人员应当缴纳的基本医疗保险费从失业保险基金中支付，个人不缴纳基本医疗保险费。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1028,'中华人民共和国社会保险法','第四十九条',49,'社会保险','第五章 失业保险','失业人员在领取失业保险金期间死亡的，参照当地对在职职工死亡的规定，向其遗属发给一次性丧葬补助金和抚恤金。所需资金从失业保险基金中支付。\n个人死亡同时符合领取基本养老保险丧葬补助金、工伤保险丧葬补助金和失业保险丧葬补助金条件的，其遗属只能选择领取其中的一项。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1029,'中华人民共和国社会保险法','第五十条',50,'社会保险','第五章 失业保险','用人单位应当及时为失业人员出具终止或者解除劳动关系的证明，并将失业人员的名单自终止或者解除劳动关系之日起十五日内告知社会保险经办机构。\n失业人员应当持本单位为其出具的终止或者解除劳动关系的证明，及时到指定的公共就业服务机构办理失业登记。\n失业人员凭失业登记证明和个人身份证明，到社会保险经办机构办理领取失业保险金的手续。失业保险金领取期限自办理失业登记之日起计算。','第五十条','2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1030,'中华人民共和国社会保险法','第五十一条',51,'社会保险','第五章 失业保险','失业人员在领取失业保险金期间有下列情形之一的，停止领取失业保险金，并同时停止享受其他失业保险待遇：\n（一）重新就业的；\n（二）应征服兵役的；\n（三）移居境外的；\n（四）享受基本养老保险待遇的；\n（五）无正当理由，拒不接受当地人民政府指定部门或者机构介绍的适当工作或者提供的培训的。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1031,'中华人民共和国社会保险法','第五十二条',52,'社会保险','第五章 失业保险','职工跨统筹地区就业的，其失业保险关系随本人转移，缴费年限累计计算。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1032,'中华人民共和国社会保险法','第五十三条',53,'社会保险','第六章 生育保险','职工应当参加生育保险，由用人单位按照国家规定缴纳生育保险费，职工不缴纳生育保险费。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1033,'中华人民共和国社会保险法','第五十四条',54,'社会保险','第六章 生育保险','用人单位已经缴纳生育保险费的，其职工享受生育保险待遇；职工未就业配偶按照国家规定享受生育医疗费用待遇。所需资金从生育保险基金中支付。\n生育保险待遇包括生育医疗费用和生育津贴。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1034,'中华人民共和国社会保险法','第五十五条',55,'社会保险','第六章 生育保险','生育医疗费用包括下列各项：\n（一）生育的医疗费用；\n（二）计划生育的医疗费用；\n（三）法律、法规规定的其他项目费用。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1035,'中华人民共和国社会保险法','第五十六条',56,'社会保险','第六章 生育保险','职工有下列情形之一的，可以按照国家规定享受生育津贴：\n（一）女职工生育享受产假；\n（二）享受计划生育手术休假；\n（三）法律、法规规定的其他情形。\n生育津贴按照职工所在用人单位上年度职工月平均工资计发。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1036,'中华人民共和国社会保险法','第五十七条',57,'社会保险','第七章 社会保险费征缴','用人单位应当自成立之日起三十日内凭营业执照、登记证书或者单位印章，向当地社会保险经办机构申请办理社会保险登记。社会保险经办机构应当自收到申请之日起十五日内予以审核，发给社会保险登记证件。\n用人单位的社会保险登记事项发生变更或者用人单位依法终止的，应当自变更或者终止之日起三十日内，到社会保险经办机构办理变更或者注销社会保险登记。\n市场监督管理部门、民政部门和机构编制管理机关应当及时向社会保险经办机构通报用人单位的成立、终止情况，公安机关应当及时向社会保险经办机构通报个人的出生、死亡以及户口登记、迁移、注销等情况。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1038,'中华人民共和国社会保险法','第五十九条',59,'社会保险','第七章 社会保险费征缴','县级以上人民政府加强社会保险费的征收工作。\n社会保险费实行统一征收，实施步骤和具体办法由国务院规定。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1039,'中华人民共和国社会保险法','第六十条',60,'社会保险','第七章 社会保险费征缴','用人单位应当自行申报、按时足额缴纳社会保险费，非因不可抗力等法定事由不得缓缴、减免。职工应当缴纳的社会保险费由用人单位代扣代缴，用人单位应当按月将缴纳社会保险费的明细情况告知本人。\n无雇工的个体工商户、未在用人单位参加社会保险的非全日制从业人员以及其他灵活就业人员，可以直接向社会保险费征收机构缴纳社会保险费。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1040,'中华人民共和国社会保险法','第六十一条',61,'社会保险','第七章 社会保险费征缴','社会保险费征收机构应当依法按时足额征收社会保险费，并将缴费情况定期告知用人单位和个人。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1041,'中华人民共和国社会保险法','第六十二条',62,'社会保险','第七章 社会保险费征缴','用人单位未按规定申报应当缴纳的社会保险费数额的，按照该单位上月缴费额的百分之一百一十确定应当缴纳数额；缴费单位补办申报手续后，由社会保险费征收机构按照规定结算。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1042,'中华人民共和国社会保险法','第六十三条',63,'社会保险','第七章 社会保险费征缴','用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令其限期缴纳或者补足。\n用人单位逾期仍未缴纳或者补足社会保险费的，社会保险费征收机构可以向银行和其他金融机构查询其存款账户；并可以申请县级以上有关行政部门作出划拨社会保险费的决定，书面通知其开户银行或者其他金融机构划拨社会保险费。用人单位账户余额少于应当缴纳的社会保险费的，社会保险费征收机构可以要求该用人单位提供担保，签订延期缴费协议。\n用人单位未足额缴纳社会保险费且未提供担保的，社会保险费征收机构可以申请人民法院扣押、查封、拍卖其价值相当于应当缴纳社会保险费的财产，以拍卖所得抵缴社会保险费。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1043,'中华人民共和国社会保险法','第六十四条',64,'社会保险','第八章 社会保险基金','社会保险基金包括基本养老保险基金、基本医疗保险基金、工伤保险基金、失业保险基金和生育保险基金。除基本医疗保险基金与生育保险基金合并建账及核算外，其他各项社会保险基金按照社会保险险种分别建账，分账核算。社会保险基金执行国家统一的会计制度。\n社会保险基金专款专用，任何组织和个人不得侵占或者挪用。\n基本养老保险基金逐步实行全国统筹，其他社会保险基金逐步实行省级统筹，具体时间、步骤由国务院规定。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1044,'中华人民共和国社会保险法','第六十五条',65,'社会保险','第八章 社会保险基金','社会保险基金通过预算实现收支平衡。\n县级以上人民政府在社会保险基金出现支付不足时，给予补贴。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1045,'中华人民共和国社会保险法','第六十六条',66,'社会保险','第八章 社会保险基金','社会保险基金按照统筹层次设立预算。除基本医疗保险基金与生育保险基金预算合并编制外，其他社会保险基金预算按照社会保险项目分别编制。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1046,'中华人民共和国社会保险法','第六十七条',67,'社会保险','第八章 社会保险基金','社会保险基金预算、决算草案的编制、审核和批准，依照法律和国务院规定执行。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1047,'中华人民共和国社会保险法','第六十八条',68,'社会保险','第八章 社会保险基金','社会保险基金存入财政专户，具体管理办法由国务院规定。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1048,'中华人民共和国社会保险法','第六十九条',69,'社会保险','第八章 社会保险基金','社会保险基金在保证安全的前提下，按照国务院规定投资运营实现保值增值。\n社会保险基金不得违规投资运营，不得用于平衡其他政府预算，不得用于兴建、改建办公场所和支付人员经费、运行费用、管理费用，或者违反法律、行政法规规定挪作其他用途。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1049,'中华人民共和国社会保险法','第七十条',70,'社会保险','第八章 社会保险基金','社会保险经办机构应当定期向社会公布参加社会保险情况以及社会保险基金的收入、支出、结余和收益情况。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1050,'中华人民共和国社会保险法','第七十一条',71,'社会保险','第八章 社会保险基金','国家设立全国社会保障基金，由中央财政预算拨款以及国务院批准的其他方式筹集的资金构成，用于社会保障支出的补充、调剂。全国社会保障基金由全国社会保障基金管理运营机构负责管理运营，在保证安全的前提下实现保值增值。\n全国社会保障基金应当定期向社会公布收支、管理和投资运营的情况。国务院财政部门、社会保险行政部门、审计机关对全国社会保障基金的收支、管理和投资运营情况实施监督。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1051,'中华人民共和国社会保险法','第七十二条',72,'社会保险','第九章 社会保险经办','统筹地区设立社会保险经办机构。社会保险经办机构根据工作需要，经所在地的社会保险行政部门和机构编制管理机关批准，可以在本统筹地区设立分支机构和服务网点。\n社会保险经办机构的人员经费和经办社会保险发生的基本运行费用、管理费用，由同级财政按照国家规定予以保障。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1052,'中华人民共和国社会保险法','第七十三条',73,'社会保险','第九章 社会保险经办','社会保险经办机构应当建立健全业务、财务、安全和风险管理制度。\n社会保险经办机构应当按时足额支付社会保险待遇。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1053,'中华人民共和国社会保险法','第七十四条',74,'社会保险','第九章 社会保险经办','社会保险经办机构通过业务经办、统计、调查获取社会保险工作所需的数据，有关单位和个人应当及时、如实提供。\n社会保险经办机构应当及时为用人单位建立档案，完整、准确地记录参加社会保险的人员、缴费等社会保险数据，妥善保管登记、申报的原始凭证和支付结算的会计凭证。\n社会保险经办机构应当及时、完整、准确地记录参加社会保险的个人缴费和用人单位为其缴费，以及享受社会保险待遇等个人权益记录，定期将个人权益记录单免费寄送本人。\n用人单位和个人可以免费向社会保险经办机构查询、核对其缴费和享受社会保险待遇记录，要求社会保险经办机构提供社会保险咨询等相关服务。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1054,'中华人民共和国社会保险法','第七十五条',75,'社会保险','第九章 社会保险经办','全国社会保险信息系统按照国家统一规划，由县级以上人民政府按照分级负责的原则共同建设。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1055,'中华人民共和国社会保险法','第七十六条',76,'社会保险','第十章 社会保险监督','各级人民代表大会常务委员会听取和审议本级人民政府对社会保险基金的收支、管理、投资运营以及监督检查情况的专项工作报告，组织对本法实施情况的执法检查等，依法行使监督职权。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1056,'中华人民共和国社会保险法','第七十七条',77,'社会保险','第十章 社会保险监督','县级以上人民政府社会保险行政部门应当加强对用人单位和个人遵守社会保险法律、法规情况的监督检查。\n社会保险行政部门实施监督检查时，被检查的用人单位和个人应当如实提供与社会保险有关的资料，不得拒绝检查或者谎报、瞒报。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1057,'中华人民共和国社会保险法','第七十八条',78,'社会保险','第十章 社会保险监督','财政部门、审计机关按照各自职责，对社会保险基金的收支、管理和投资运营情况实施监督。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1058,'中华人民共和国社会保险法','第七十九条',79,'社会保险','第十章 社会保险监督','社会保险行政部门对社会保险基金的收支、管理和投资运营情况进行监督检查，发现存在问题的，应当提出整改建议，依法作出处理决定或者向有关行政部门提出处理建议。社会保险基金检查结果应当定期向社会公布。\n社会保险行政部门对社会保险基金实施监督检查，有权采取下列措施：\n（一）查阅、记录、复制与社会保险基金收支、管理和投资运营相关的资料，对可能被转移、隐匿或者灭失的资料予以封存；\n（二）询问与调查事项有关的单位和个人，要求其对与调查事项有关的问题作出说明、提供有关证明材料；\n（三）对隐匿、转移、侵占、挪用社会保险基金的行为予以制止并责令改正。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1059,'中华人民共和国社会保险法','第八十条',80,'社会保险','第十章 社会保险监督','统筹地区人民政府成立由用人单位代表、参保人员代表，以及工会代表、专家等组成的社会保险监督委员会，掌握、分析社会保险基金的收支、管理和投资运营情况，对社会保险工作提出咨询意见和建议，实施社会监督。\n社会保险经办机构应当定期向社会保险监督委员会汇报社会保险基金的收支、管理和投资运营情况。社会保险监督委员会可以聘请会计师事务所对社会保险基金的收支、管理和投资运营情况进行年度审计和专项审计。审计结果应当向社会公开。\n社会保险监督委员会发现社会保险基金收支、管理和投资运营中存在问题的，有权提出改正建议；对社会保险经办机构及其工作人员的违法行为，有权向有关部门提出依法处理建议。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1060,'中华人民共和国社会保险法','第八十一条',81,'社会保险','第十章 社会保险监督','社会保险行政部门和其他有关行政部门、社会保险经办机构、社会保险费征收机构及其工作人员，应当依法为用人单位和个人的信息保密，不得以任何形式泄露。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1061,'中华人民共和国社会保险法','第八十二条',82,'社会保险','第十章 社会保险监督','任何组织或者个人有权对违反社会保险法律、法规的行为进行举报、投诉。\n社会保险行政部门、卫生行政部门、社会保险经办机构、社会保险费征收机构和财政部门、审计机关对属于本部门、本机构职责范围的举报、投诉，应当依法处理；对不属于本部门、本机构职责范围的，应当书面通知并移交有权处理的部门、机构处理。有权处理的部门、机构应当及时处理，不得推诿。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1062,'中华人民共和国社会保险法','第八十三条',83,'社会保险','第十章 社会保险监督','用人单位或者个人认为社会保险费征收机构的行为侵害自己合法权益的，可以依法申请行政复议或者提起行政诉讼。\n用人单位或者个人对社会保险经办机构不依法办理社会保险登记、核定社会保险费、支付社会保险待遇、办理社会保险转移接续手续或者侵害其他社会保险权益的行为，可以依法申请行政复议或者提起行政诉讼。\n个人与所在用人单位发生社会保险争议的，可以依法申请调解、仲裁，提起诉讼。用人单位侵害个人社会保险权益的，个人也可以要求社会保险行政部门或者社会保险费征收机构依法处理。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1063,'中华人民共和国社会保险法','第八十四条',84,'社会保险','第十一章 法律责任','用人单位不办理社会保险登记的，由社会保险行政部门责令限期改正；逾期不改正的，对用人单位处应缴社会保险费数额一倍以上三倍以下的罚款，对其直接负责的主管人员和其他直接责任人员处五百元以上三千元以下的罚款。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1064,'中华人民共和国社会保险法','第八十五条',85,'社会保险','第十一章 法律责任','用人单位拒不出具终止或者解除劳动关系证明的，依照《中华人民共和国劳动合同法》的规定处理。','第八十五条','2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1065,'中华人民共和国社会保险法','第八十六条',86,'社会保险','第十一章 法律责任','用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令限期缴纳或者补足，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，由有关行政部门处欠缴数额一倍以上三倍以下的罚款。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1066,'中华人民共和国社会保险法','第八十七条',87,'社会保险','第十一章 法律责任','社会保险经办机构以及医疗机构、药品经营单位等社会保险服务机构以欺诈、伪造证明材料或者其他手段骗取社会保险基金支出的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款；属于社会保险服务机构的，解除服务协议；直接负责的主管人员和其他直接责任人员有执业资格的，依法吊销其执业资格。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1067,'中华人民共和国社会保险法','第八十八条',88,'社会保险','第十一章 法律责任','以欺诈、伪造证明材料或者其他手段骗取社会保险待遇的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1068,'中华人民共和国社会保险法','第八十九条',89,'社会保险','第十一章 法律责任','社会保险经办机构及其工作人员有下列行为之一的，由社会保险行政部门责令改正；给社会保险基金、用人单位或者个人造成损失的，依法承担赔偿责任；对直接负责的主管人员和其他直接责任人员依法给予处分：\n（一）未履行社会保险法定职责的；\n（二）未将社会保险基金存入财政专户的；\n（三）克扣或者拒不按时支付社会保险待遇的；\n（四）丢失或者篡改缴费记录、享受社会保险待遇记录等社会保险数据、个人权益记录的；\n（五）有违反社会保险法律、法规的其他行为的。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1069,'中华人民共和国社会保险法','第九十条',90,'社会保险','第十一章 法律责任','社会保险费征收机构擅自更改社会保险费缴费基数、费率，导致少收或者多收社会保险费的，由有关行政部门责令其追缴应当缴纳的社会保险费或者退还不应当缴纳的社会保险费；对直接负责的主管人员和其他直接责任人员依法给予处分。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1070,'中华人民共和国社会保险法','第九十一条',91,'社会保险','第十一章 法律责任','违反本法规定，隐匿、转移、侵占、挪用社会保险基金或者违规投资运营的，由社会保险行政部门、财政部门、审计机关责令追回；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员依法给予处分。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1071,'中华人民共和国社会保险法','第九十二条',92,'社会保险','第十一章 法律责任','社会保险行政部门和其他有关行政部门、社会保险经办机构、社会保险费征收机构及其工作人员泄露用人单位和个人信息的，对直接负责的主管人员和其他直接责任人员依法给予处分；给用人单位或者个人造成损失的，应当承担赔偿责任。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1072,'中华人民共和国社会保险法','第九十三条',93,'社会保险','第十一章 法律责任','国家工作人员在社会保险管理、监督工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1073,'中华人民共和国社会保险法','第九十四条',94,'社会保险','第十一章 法律责任','违反本法规定，构成犯罪的，依法追究刑事责任。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1074,'中华人民共和国社会保险法','第九十五条',95,'社会保险','第十二章 附 则','进城务工的农村居民依照本法规定参加社会保险。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1075,'中华人民共和国社会保险法','第九十六条',96,'社会保险','第十二章 附 则','征收农村集体所有的土地，应当足额安排被征地农民的社会保险费，按照国务院规定将被征地农民纳入相应的社会保险制度。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1076,'中华人民共和国社会保险法','第九十七条',97,'社会保险','第十二章 附 则','外国人在中国境内就业的，参照本法规定参加社会保险。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1077,'中华人民共和国社会保险法','第九十八条',98,'社会保险','第十二章 附 则','本法自2011年7月1日起施行。',NULL,'2018-12-29','flk_npc','ff8080816f135f46016f210989b9179a','2026-09-16 20:35:55','2026-09-17 16:49:56');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1078,'中华人民共和国劳动争议调解仲裁法','第一条',1,'其他','第一章 总 则','为了公正及时解决劳动争议，保护当事人合法权益，促进劳动关系和谐稳定，制定本法。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1079,'中华人民共和国劳动争议调解仲裁法','第二条',2,'其他','第一章 总 则','中华人民共和国境内的用人单位与劳动者发生的下列劳动争议，适用本法：\n（一）因确认劳动关系发生的争议；\n（二）因订立、履行、变更、解除和终止劳动合同发生的争议；\n（三）因除名、辞退和辞职、离职发生的争议；\n（四）因工作时间、休息休假、社会保险、福利、培训以及劳动保护发生的争议；\n（五）因劳动报酬、工伤医疗费、经济补偿或者赔偿金等发生的争议；\n（六）法律、法规规定的其他劳动争议。','第二条','2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1080,'中华人民共和国劳动争议调解仲裁法','第三条',3,'其他','第一章 总 则','解决劳动争议，应当根据事实，遵循合法、公正、及时、着重调解的原则，依法保护当事人的合法权益。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1081,'中华人民共和国劳动争议调解仲裁法','第四条',4,'其他','第一章 总 则','发生劳动争议，劳动者可以与用人单位协商，也可以请工会或者第三方共同与用人单位协商，达成和解协议。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1082,'中华人民共和国劳动争议调解仲裁法','第五条',5,'其他','第一章 总 则','发生劳动争议，当事人不愿协商、协商不成或者达成和解协议后不履行的，可以向调解组织申请调解；不愿调解、调解不成或者达成调解协议后不履行的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，除本法另有规定的外，可以向人民法院提起诉讼。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1083,'中华人民共和国劳动争议调解仲裁法','第六条',6,'其他','第一章 总 则','发生劳动争议，当事人对自己提出的主张，有责任提供证据。与争议事项有关的证据属于用人单位掌握管理的，用人单位应当提供；用人单位不提供的，应当承担不利后果。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1084,'中华人民共和国劳动争议调解仲裁法','第七条',7,'其他','第一章 总 则','发生劳动争议的劳动者一方在十人以上，并有共同请求的，可以推举代表参加调解、仲裁或者诉讼活动。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1085,'中华人民共和国劳动争议调解仲裁法','第八条',8,'其他','第一章 总 则','县级以上人民政府劳动行政部门会同工会和企业方面代表建立协调劳动关系三方机制，共同研究解决劳动争议的重大问题。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1086,'中华人民共和国劳动争议调解仲裁法','第九条',9,'其他','第一章 总 则','用人单位违反国家规定，拖欠或者未足额支付劳动报酬，或者拖欠工伤医疗费、经济补偿或者赔偿金的，劳动者可以向劳动行政部门投诉，劳动行政部门应当依法处理。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1087,'中华人民共和国劳动争议调解仲裁法','第十条',10,'其他','第二章 调 解','发生劳动争议，当事人可以到下列调解组织申请调解：\n（一）企业劳动争议调解委员会；\n（二）依法设立的基层人民调解组织；\n（三）在乡镇、街道设立的具有劳动争议调解职能的组织。\n企业劳动争议调解委员会由职工代表和企业代表组成。职工代表由工会成员担任或者由全体职工推举产生，企业代表由企业负责人指定。企业劳动争议调解委员会主任由工会成员或者双方推举的人员担任。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1088,'中华人民共和国劳动争议调解仲裁法','第十一条',11,'其他','第二章 调 解','劳动争议调解组织的调解员应当由公道正派、联系群众、热心调解工作，并具有一定法律知识、政策水平和文化水平的成年公民担任。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1089,'中华人民共和国劳动争议调解仲裁法','第十二条',12,'其他','第二章 调 解','当事人申请劳动争议调解可以书面申请，也可以口头申请。口头申请的，调解组织应当当场记录申请人基本情况、申请调解的争议事项、理由和时间。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1090,'中华人民共和国劳动争议调解仲裁法','第十三条',13,'其他','第二章 调 解','调解劳动争议，应当充分听取双方当事人对事实和理由的陈述，耐心疏导，帮助其达成协议。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1091,'中华人民共和国劳动争议调解仲裁法','第十四条',14,'其他','第二章 调 解','经调解达成协议的，应当制作调解协议书。\n调解协议书由双方当事人签名或者盖章，经调解员签名并加盖调解组织印章后生效，对双方当事人具有约束力，当事人应当履行。\n自劳动争议调解组织收到调解申请之日起十五日内未达成调解协议的，当事人可以依法申请仲裁。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1092,'中华人民共和国劳动争议调解仲裁法','第十五条',15,'其他','第二章 调 解','达成调解协议后，一方当事人在协议约定期限内不履行调解协议的，另一方当事人可以依法申请仲裁。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1093,'中华人民共和国劳动争议调解仲裁法','第十六条',16,'其他','第二章 调 解','因支付拖欠劳动报酬、工伤医疗费、经济补偿或者赔偿金事项达成调解协议，用人单位在协议约定期限内不履行的，劳动者可以持调解协议书依法向人民法院申请支付令。人民法院应当依法发出支付令。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1094,'中华人民共和国劳动争议调解仲裁法','第十七条',17,'其他','第一节 一般规定','劳动争议仲裁委员会按照统筹规划、合理布局和适应实际需要的原则设立。省、自治区人民政府可以决定在市、县设立；直辖市人民政府可以决定在区、县设立。直辖市、设区的市也可以设立一个或者若干个劳动争议仲裁委员会。劳动争议仲裁委员会不按行政区划层层设立。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1095,'中华人民共和国劳动争议调解仲裁法','第十八条',18,'其他','第一节 一般规定','国务院劳动行政部门依照本法有关规定制定仲裁规则。省、自治区、直辖市人民政府劳动行政部门对本行政区域的劳动争议仲裁工作进行指导。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1096,'中华人民共和国劳动争议调解仲裁法','第十九条',19,'其他','第一节 一般规定','劳动争议仲裁委员会由劳动行政部门代表、工会代表和企业方面代表组成。劳动争议仲裁委员会组成人员应当是单数。\n劳动争议仲裁委员会依法履行下列职责：\n（一）聘任、解聘专职或者兼职仲裁员；\n（二）受理劳动争议案件；\n（三）讨论重大或者疑难的劳动争议案件；\n（四）对仲裁活动进行监督。\n劳动争议仲裁委员会下设办事机构，负责办理劳动争议仲裁委员会的日常工作。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1097,'中华人民共和国劳动争议调解仲裁法','第二十条',20,'其他','第一节 一般规定','劳动争议仲裁委员会应当设仲裁员名册。\n仲裁员应当公道正派并符合下列条件之一：\n（一）曾任审判员的；\n（二）从事法律研究、教学工作并具有中级以上职称的；\n（三）具有法律知识、从事人力资源管理或者工会等专业工作满五年的；\n（四）律师执业满三年的。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1098,'中华人民共和国劳动争议调解仲裁法','第二十一条',21,'其他','第一节 一般规定','劳动争议仲裁委员会负责管辖本区域内发生的劳动争议。\n劳动争议由劳动合同履行地或者用人单位所在地的劳动争议仲裁委员会管辖。双方当事人分别向劳动合同履行地和用人单位所在地的劳动争议仲裁委员会申请仲裁的，由劳动合同履行地的劳动争议仲裁委员会管辖。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1099,'中华人民共和国劳动争议调解仲裁法','第二十二条',22,'其他','第一节 一般规定','发生劳动争议的劳动者和用人单位为劳动争议仲裁案件的双方当事人。\n劳务派遣单位或者用工单位与劳动者发生劳动争议的，劳务派遣单位和用工单位为共同当事人。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1100,'中华人民共和国劳动争议调解仲裁法','第二十三条',23,'其他','第一节 一般规定','与劳动争议案件的处理结果有利害关系的第三人，可以申请参加仲裁活动或者由劳动争议仲裁委员会通知其参加仲裁活动。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1101,'中华人民共和国劳动争议调解仲裁法','第二十四条',24,'其他','第一节 一般规定','当事人可以委托代理人参加仲裁活动。委托他人参加仲裁活动，应当向劳动争议仲裁委员会提交有委托人签名或者盖章的委托书，委托书应当载明委托事项和权限。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1102,'中华人民共和国劳动争议调解仲裁法','第二十五条',25,'其他','第一节 一般规定','丧失或者部分丧失民事行为能力的劳动者，由其法定代理人代为参加仲裁活动；无法定代理人的，由劳动争议仲裁委员会为其指定代理人。劳动者死亡的，由其近亲属或者代理人参加仲裁活动。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1103,'中华人民共和国劳动争议调解仲裁法','第二十六条',26,'其他','第一节 一般规定','劳动争议仲裁公开进行，但当事人协议不公开进行或者涉及国家秘密、商业秘密和个人隐私的除外。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1105,'中华人民共和国劳动争议调解仲裁法','第二十八条',28,'其他','第二节 申请和受理','申请人申请仲裁应当提交书面仲裁申请，并按照被申请人人数提交副本。\n仲裁申请书应当载明下列事项：\n（一）劳动者的姓名、性别、年龄、职业、工作单位和住所，用人单位的名称、住所和法定代表人或者主要负责人的姓名、职务；\n（二）仲裁请求和所根据的事实、理由；\n（三）证据和证据来源、证人姓名和住所。\n书写仲裁申请确有困难的，可以口头申请，由劳动争议仲裁委员会记入笔录，并告知对方当事人。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1106,'中华人民共和国劳动争议调解仲裁法','第二十九条',29,'其他','第二节 申请和受理','劳动争议仲裁委员会收到仲裁申请之日起五日内，认为符合受理条件的，应当受理，并通知申请人；认为不符合受理条件的，应当书面通知申请人不予受理，并说明理由。对劳动争议仲裁委员会不予受理或者逾期未作出决定的，申请人可以就该劳动争议事项向人民法院提起诉讼。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1107,'中华人民共和国劳动争议调解仲裁法','第三十条',30,'其他','第二节 申请和受理','劳动争议仲裁委员会受理仲裁申请后，应当在五日内将仲裁申请书副本送达被申请人。\n被申请人收到仲裁申请书副本后，应当在十日内向劳动争议仲裁委员会提交答辩书。劳动争议仲裁委员会收到答辩书后，应当在五日内将答辩书副本送达申请人。被申请人未提交答辩书的，不影响仲裁程序的进行。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1108,'中华人民共和国劳动争议调解仲裁法','第三十一条',31,'其他','第三节 开庭和裁决','劳动争议仲裁委员会裁决劳动争议案件实行仲裁庭制。仲裁庭由三名仲裁员组成，设首席仲裁员。简单劳动争议案件可以由一名仲裁员独任仲裁。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1109,'中华人民共和国劳动争议调解仲裁法','第三十二条',32,'其他','第三节 开庭和裁决','劳动争议仲裁委员会应当在受理仲裁申请之日起五日内将仲裁庭的组成情况书面通知当事人。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1110,'中华人民共和国劳动争议调解仲裁法','第三十三条',33,'其他','第三节 开庭和裁决','仲裁员有下列情形之一，应当回避，当事人也有权以口头或者书面方式提出回避申请：\n（一）是本案当事人或者当事人、代理人的近亲属的；\n（二）与本案有利害关系的；\n（三）与本案当事人、代理人有其他关系，可能影响公正裁决的；\n（四）私自会见当事人、代理人，或者接受当事人、代理人的请客送礼的。\n劳动争议仲裁委员会对回避申请应当及时作出决定，并以口头或者书面方式通知当事人。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1111,'中华人民共和国劳动争议调解仲裁法','第三十四条',34,'其他','第三节 开庭和裁决','仲裁员有本法第三十三条第四项规定情形，或者有索贿受贿、徇私舞弊、枉法裁决行为的，应当依法承担法律责任。劳动争议仲裁委员会应当将其解聘。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1112,'中华人民共和国劳动争议调解仲裁法','第三十五条',35,'其他','第三节 开庭和裁决','仲裁庭应当在开庭五日前，将开庭日期、地点书面通知双方当事人。当事人有正当理由的，可以在开庭三日前请求延期开庭。是否延期，由劳动争议仲裁委员会决定。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1113,'中华人民共和国劳动争议调解仲裁法','第三十六条',36,'其他','第三节 开庭和裁决','申请人收到书面通知，无正当理由拒不到庭或者未经仲裁庭同意中途退庭的，可以视为撤回仲裁申请。\n被申请人收到书面通知，无正当理由拒不到庭或者未经仲裁庭同意中途退庭的，可以缺席裁决。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1114,'中华人民共和国劳动争议调解仲裁法','第三十七条',37,'其他','第三节 开庭和裁决','仲裁庭对专门性问题认为需要鉴定的，可以交由当事人约定的鉴定机构鉴定；当事人没有约定或者无法达成约定的，由仲裁庭指定的鉴定机构鉴定。\n根据当事人的请求或者仲裁庭的要求，鉴定机构应当派鉴定人参加开庭。当事人经仲裁庭许可，可以向鉴定人提问。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1115,'中华人民共和国劳动争议调解仲裁法','第三十八条',38,'其他','第三节 开庭和裁决','当事人在仲裁过程中有权进行质证和辩论。质证和辩论终结时，首席仲裁员或者独任仲裁员应当征询当事人的最后意见。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1116,'中华人民共和国劳动争议调解仲裁法','第三十九条',39,'其他','第三节 开庭和裁决','当事人提供的证据经查证属实的，仲裁庭应当将其作为认定事实的根据。\n劳动者无法提供由用人单位掌握管理的与仲裁请求有关的证据，仲裁庭可以要求用人单位在指定期限内提供。用人单位在指定期限内不提供的，应当承担不利后果。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1117,'中华人民共和国劳动争议调解仲裁法','第四十条',40,'其他','第三节 开庭和裁决','仲裁庭应当将开庭情况记入笔录。当事人和其他仲裁参加人认为对自己陈述的记录有遗漏或者差错的，有权申请补正。如果不予补正，应当记录该申请。\n笔录由仲裁员、记录人员、当事人和其他仲裁参加人签名或者盖章。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1118,'中华人民共和国劳动争议调解仲裁法','第四十一条',41,'其他','第三节 开庭和裁决','当事人申请劳动争议仲裁后，可以自行和解。达成和解协议的，可以撤回仲裁申请。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1119,'中华人民共和国劳动争议调解仲裁法','第四十二条',42,'其他','第三节 开庭和裁决','仲裁庭在作出裁决前，应当先行调解。\n调解达成协议的，仲裁庭应当制作调解书。\n调解书应当写明仲裁请求和当事人协议的结果。调解书由仲裁员签名，加盖劳动争议仲裁委员会印章，送达双方当事人。调解书经双方当事人签收后，发生法律效力。\n调解不成或者调解书送达前，一方当事人反悔的，仲裁庭应当及时作出裁决。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1120,'中华人民共和国劳动争议调解仲裁法','第四十三条',43,'其他','第三节 开庭和裁决','仲裁庭裁决劳动争议案件，应当自劳动争议仲裁委员会受理仲裁申请之日起四十五日内结束。案情复杂需要延期的，经劳动争议仲裁委员会主任批准，可以延期并书面通知当事人，但是延长期限不得超过十五日。逾期未作出仲裁裁决的，当事人可以就该劳动争议事项向人民法院提起诉讼。\n仲裁庭裁决劳动争议案件时，其中一部分事实已经清楚，可以就该部分先行裁决。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1121,'中华人民共和国劳动争议调解仲裁法','第四十四条',44,'其他','第三节 开庭和裁决','仲裁庭对追索劳动报酬、工伤医疗费、经济补偿或者赔偿金的案件，根据当事人的申请，可以裁决先予执行，移送人民法院执行。\n仲裁庭裁决先予执行的，应当符合下列条件：\n（一）当事人之间权利义务关系明确；\n（二）不先予执行将严重影响申请人的生活。\n劳动者申请先予执行的，可以不提供担保。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1122,'中华人民共和国劳动争议调解仲裁法','第四十五条',45,'其他','第三节 开庭和裁决','裁决应当按照多数仲裁员的意见作出，少数仲裁员的不同意见应当记入笔录。仲裁庭不能形成多数意见时，裁决应当按照首席仲裁员的意见作出。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1123,'中华人民共和国劳动争议调解仲裁法','第四十六条',46,'其他','第三节 开庭和裁决','裁决书应当载明仲裁请求、争议事实、裁决理由、裁决结果和裁决日期。裁决书由仲裁员签名，加盖劳动争议仲裁委员会印章。对裁决持不同意见的仲裁员，可以签名，也可以不签名。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1124,'中华人民共和国劳动争议调解仲裁法','第四十七条',47,'其他','第三节 开庭和裁决','下列劳动争议，除本法另有规定的外，仲裁裁决为终局裁决，裁决书自作出之日起发生法律效力：\n（一）追索劳动报酬、工伤医疗费、经济补偿或者赔偿金，不超过当地月最低工资标准十二个月金额的争议；\n（二）因执行国家的劳动标准在工作时间、休息休假、社会保险等方面发生的争议。','第四十七条','2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1125,'中华人民共和国劳动争议调解仲裁法','第四十八条',48,'其他','第三节 开庭和裁决','劳动者对本法第四十七条规定的仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1126,'中华人民共和国劳动争议调解仲裁法','第四十九条',49,'其他','第三节 开庭和裁决','用人单位有证据证明本法第四十七条规定的仲裁裁决有下列情形之一，可以自收到仲裁裁决书之日起三十日内向劳动争议仲裁委员会所在地的中级人民法院申请撤销裁决：\n（一）适用法律、法规确有错误的；\n（二）劳动争议仲裁委员会无管辖权的；\n（三）违反法定程序的；\n（四）裁决所根据的证据是伪造的；\n（五）对方当事人隐瞒了足以影响公正裁决的证据的；\n（六）仲裁员在仲裁该案时有索贿受贿、徇私舞弊、枉法裁决行为的。\n人民法院经组成合议庭审查核实裁决有前款规定情形之一的，应当裁定撤销。\n仲裁裁决被人民法院裁定撤销的，当事人可以自收到裁定书之日起十五日内就该劳动争议事项向人民法院提起诉讼。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1127,'中华人民共和国劳动争议调解仲裁法','第五十条',50,'其他','第三节 开庭和裁决','当事人对本法第四十七条规定以外的其他劳动争议案件的仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼；期满不起诉的，裁决书发生法律效力。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1128,'中华人民共和国劳动争议调解仲裁法','第五十一条',51,'其他','第三节 开庭和裁决','当事人对发生法律效力的调解书、裁决书，应当依照规定的期限履行。一方当事人逾期不履行的，另一方当事人可以依照民事诉讼法的有关规定向人民法院申请执行。受理申请的人民法院应当依法执行。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1129,'中华人民共和国劳动争议调解仲裁法','第五十二条',52,'其他','第四章 附 则','事业单位实行聘用制的工作人员与本单位发生劳动争议的，依照本法执行；法律、行政法规或者国务院另有规定的，依照其规定。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1130,'中华人民共和国劳动争议调解仲裁法','第五十三条',53,'其他','第四章 附 则','劳动争议仲裁不收费。劳动争议仲裁委员会的经费由财政予以保障。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1131,'中华人民共和国劳动争议调解仲裁法','第五十四条',54,'其他','第四章 附 则','本法自2008年5月1日起施行。',NULL,'2008-05-01','flk_npc','2c909fdd678bf17901678bf64f28039d','2026-09-16 20:36:01','2026-09-17 16:49:59');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1132,'中华人民共和国就业促进法','第一条',1,'其他','第一章 总 则','为了促进就业，促进经济发展与扩大就业相协调，促进社会和谐稳定，制定本法。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1133,'中华人民共和国就业促进法','第二条',2,'其他','第一章 总 则','国家把扩大就业放在经济社会发展的突出位置，实施积极的就业政策，坚持劳动者自主择业、市场调节就业、政府促进就业的方针，多渠道扩大就业。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1134,'中华人民共和国就业促进法','第三条',3,'其他','第一章 总 则','劳动者依法享有平等就业和自主择业的权利。\n劳动者就业，不因民族、种族、性别、宗教信仰等不同而受歧视。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1135,'中华人民共和国就业促进法','第四条',4,'其他','第一章 总 则','县级以上人民政府把扩大就业作为经济和社会发展的重要目标，纳入国民经济和社会发展规划，并制定促进就业的中长期规划和年度工作计划。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1136,'中华人民共和国就业促进法','第五条',5,'其他','第一章 总 则','县级以上人民政府通过发展经济和调整产业结构、规范人力资源市场、完善就业服务、加强职业教育和培训、提供就业援助等措施，创造就业条件，扩大就业。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1137,'中华人民共和国就业促进法','第六条',6,'其他','第一章 总 则','国务院建立全国促进就业工作协调机制，研究就业工作中的重大问题，协调推动全国的促进就业工作。国务院劳动行政部门具体负责全国的促进就业工作。\n省、自治区、直辖市人民政府根据促进就业工作的需要，建立促进就业工作协调机制，协调解决本行政区域就业工作中的重大问题。\n县级以上人民政府有关部门按照各自的职责分工，共同做好促进就业工作。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1138,'中华人民共和国就业促进法','第七条',7,'其他','第一章 总 则','国家倡导劳动者树立正确的择业观念，提高就业能力和创业能力；鼓励劳动者自主创业、自谋职业。\n各级人民政府和有关部门应当简化程序，提高效率，为劳动者自主创业、自谋职业提供便利。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1139,'中华人民共和国就业促进法','第八条',8,'其他','第一章 总 则','用人单位依法享有自主用人的权利。\n用人单位应当依照本法以及其他法律、法规的规定，保障劳动者的合法权益。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1140,'中华人民共和国就业促进法','第九条',9,'其他','第一章 总 则','工会、共产主义青年团、妇女联合会、残疾人联合会以及其他社会组织，协助人民政府开展促进就业工作，依法维护劳动者的劳动权利。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1141,'中华人民共和国就业促进法','第十条',10,'其他','第一章 总 则','各级人民政府和有关部门对在促进就业工作中作出显著成绩的单位和个人，给予表彰和奖励。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1142,'中华人民共和国就业促进法','第十一条',11,'其他','第二章 政策支持','县级以上人民政府应当把扩大就业作为重要职责，统筹协调产业政策与就业政策。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1143,'中华人民共和国就业促进法','第十二条',12,'其他','第二章 政策支持','国家鼓励各类企业在法律、法规规定的范围内，通过兴办产业或者拓展经营，增加就业岗位。\n国家鼓励发展劳动密集型产业、服务业，扶持中小企业，多渠道、多方式增加就业岗位。\n国家鼓励、支持、引导非公有制经济发展，扩大就业，增加就业岗位。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1144,'中华人民共和国就业促进法','第十三条',13,'其他','第二章 政策支持','国家发展国内外贸易和国际经济合作，拓宽就业渠道。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1145,'中华人民共和国就业促进法','第十四条',14,'其他','第二章 政策支持','县级以上人民政府在安排政府投资和确定重大建设项目时，应当发挥投资和重大建设项目带动就业的作用，增加就业岗位。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1146,'中华人民共和国就业促进法','第十五条',15,'其他','第二章 政策支持','国家实行有利于促进就业的财政政策，加大资金投入，改善就业环境，扩大就业。\n县级以上人民政府应当根据就业状况和就业工作目标，在财政预算中安排就业专项资金用于促进就业工作。\n就业专项资金用于职业介绍、职业培训、公益性岗位、职业技能鉴定、特定就业政策和社会保险等的补贴，小额贷款担保基金和微利项目的小额担保贷款贴息，以及扶持公共就业服务等。就业专项资金的使用管理办法由国务院财政部门和劳动行政部门规定。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1147,'中华人民共和国就业促进法','第十六条',16,'其他','第二章 政策支持','国家建立健全失业保险制度，依法确保失业人员的基本生活，并促进其实现就业。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1148,'中华人民共和国就业促进法','第十七条',17,'其他','第二章 政策支持','国家鼓励企业增加就业岗位，扶持失业人员和残疾人就业，对下列企业、人员依法给予税收优惠：\n（一）吸纳符合国家规定条件的失业人员达到规定要求的企业；\n（二）失业人员创办的中小企业；\n（三）安置残疾人员达到规定比例或者集中使用残疾人的企业；\n（四）从事个体经营的符合国家规定条件的失业人员；\n（五）从事个体经营的残疾人；\n（六）国务院规定给予税收优惠的其他企业、人员。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1149,'中华人民共和国就业促进法','第十八条',18,'其他','第二章 政策支持','对本法第十七条第四项、第五项规定的人员，有关部门应当在经营场地等方面给予照顾，免除行政事业性收费。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1150,'中华人民共和国就业促进法','第十九条',19,'其他','第二章 政策支持','国家实行有利于促进就业的金融政策，增加中小企业的融资渠道；鼓励金融机构改进金融服务，加大对中小企业的信贷支持，并对自主创业人员在一定期限内给予小额信贷等扶持。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1151,'中华人民共和国就业促进法','第二十条',20,'其他','第二章 政策支持','国家实行城乡统筹的就业政策，建立健全城乡劳动者平等就业的制度，引导农业富余劳动力有序转移就业。\n县级以上地方人民政府推进小城镇建设和加快县域经济发展，引导农业富余劳动力就地就近转移就业；在制定小城镇规划时，将本地区农业富余劳动力转移就业作为重要内容。\n县级以上地方人民政府引导农业富余劳动力有序向城市异地转移就业；劳动力输出地和输入地人民政府应当互相配合，改善农村劳动者进城就业的环境和条件。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1152,'中华人民共和国就业促进法','第二十一条',21,'其他','第二章 政策支持','国家支持区域经济发展，鼓励区域协作，统筹协调不同地区就业的均衡增长。\n国家支持民族地区发展经济，扩大就业。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1153,'中华人民共和国就业促进法','第二十二条',22,'其他','第二章 政策支持','各级人民政府统筹做好城镇新增劳动力就业、农业富余劳动力转移就业和失业人员就业工作。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1154,'中华人民共和国就业促进法','第二十三条',23,'其他','第二章 政策支持','各级人民政府采取措施，逐步完善和实施与非全日制用工等灵活就业相适应的劳动和社会保险政策，为灵活就业人员提供帮助和服务。','第二十三条','2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1155,'中华人民共和国就业促进法','第二十四条',24,'其他','第二章 政策支持','地方各级人民政府和有关部门应当加强对失业人员从事个体经营的指导，提供政策咨询、就业培训和开业指导等服务。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1156,'中华人民共和国就业促进法','第二十五条',25,'其他','第三章 公平就业','各级人民政府创造公平就业的环境，消除就业歧视，制定政策并采取措施对就业困难人员给予扶持和援助。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1157,'中华人民共和国就业促进法','第二十六条',26,'其他','第三章 公平就业','用人单位招用人员、职业中介机构从事职业中介活动，应当向劳动者提供平等的就业机会和公平的就业条件，不得实施就业歧视。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1158,'中华人民共和国就业促进法','第二十七条',27,'其他','第三章 公平就业','国家保障妇女享有与男子平等的劳动权利。\n用人单位招用人员，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。\n用人单位录用女职工，不得在劳动合同中规定限制女职工结婚、生育的内容。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1159,'中华人民共和国就业促进法','第二十八条',28,'其他','第三章 公平就业','各民族劳动者享有平等的劳动权利。\n用人单位招用人员，应当依法对少数民族劳动者给予适当照顾。','第二十八条','2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1160,'中华人民共和国就业促进法','第二十九条',29,'其他','第三章 公平就业','国家保障残疾人的劳动权利。\n各级人民政府应当对残疾人就业统筹规划，为残疾人创造就业条件。\n用人单位招用人员，不得歧视残疾人。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1161,'中华人民共和国就业促进法','第三十条',30,'其他','第三章 公平就业','用人单位招用人员，不得以是传染病病原携带者为由拒绝录用。但是，经医学鉴定传染病病原携带者在治愈前或者排除传染嫌疑前，不得从事法律、行政法规和国务院卫生行政部门规定禁止从事的易使传染病扩散的工作。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1162,'中华人民共和国就业促进法','第三十一条',31,'其他','第三章 公平就业','农村劳动者进城就业享有与城镇劳动者平等的劳动权利，不得对农村劳动者进城就业设置歧视性限制。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1163,'中华人民共和国就业促进法','第三十二条',32,'其他','第四章 就业服务和管理','县级以上人民政府培育和完善统一开放、竞争有序的人力资源市场，为劳动者就业提供服务。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1164,'中华人民共和国就业促进法','第三十三条',33,'其他','第四章 就业服务和管理','县级以上人民政府鼓励社会各方面依法开展就业服务活动，加强对公共就业服务和职业中介服务的指导和监督，逐步完善覆盖城乡的就业服务体系。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1165,'中华人民共和国就业促进法','第三十四条',34,'其他','第四章 就业服务和管理','县级以上人民政府加强人力资源市场信息网络及相关设施建设，建立健全人力资源市场信息服务体系，完善市场信息发布制度。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1166,'中华人民共和国就业促进法','第三十五条',35,'其他','第四章 就业服务和管理','县级以上人民政府建立健全公共就业服务体系，设立公共就业服务机构，为劳动者免费提供下列服务：\n（一）就业政策法规咨询；\n（二）职业供求信息、市场工资指导价位信息和职业培训信息发布；\n（三）职业指导和职业介绍；\n（四）对就业困难人员实施就业援助；\n（五）办理就业登记、失业登记等事务；\n（六）其他公共就业服务。\n公共就业服务机构应当不断提高服务的质量和效率，不得从事经营性活动。\n公共就业服务经费纳入同级财政预算。','第三十五条','2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1167,'中华人民共和国就业促进法','第三十六条',36,'其他','第四章 就业服务和管理','县级以上地方人民政府对职业中介机构提供公益性就业服务的，按照规定给予补贴。\n国家鼓励社会各界为公益性就业服务提供捐赠、资助。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1168,'中华人民共和国就业促进法','第三十七条',37,'其他','第四章 就业服务和管理','地方各级人民政府和有关部门不得举办或者与他人联合举办经营性的职业中介机构。\n地方各级人民政府和有关部门、公共就业服务机构举办的招聘会，不得向劳动者收取费用。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1169,'中华人民共和国就业促进法','第三十八条',38,'其他','第四章 就业服务和管理','县级以上人民政府和有关部门加强对职业中介机构的管理，鼓励其提高服务质量，发挥其在促进就业中的作用。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1170,'中华人民共和国就业促进法','第三十九条',39,'其他','第四章 就业服务和管理','从事职业中介活动，应当遵循合法、诚实信用、公平、公开的原则。\n用人单位通过职业中介机构招用人员，应当如实向职业中介机构提供岗位需求信息。\n禁止任何组织或者个人利用职业中介活动侵害劳动者的合法权益。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1171,'中华人民共和国就业促进法','第四十条',40,'其他','第四章 就业服务和管理','设立职业中介机构应当具备下列条件：\n（一）有明确的章程和管理制度；\n（二）有开展业务必备的固定场所、办公设施和一定数额的开办资金；\n（三）有一定数量具备相应职业资格的专职工作人员；\n（四）法律、法规规定的其他条件。\n设立职业中介机构应当在工商行政管理部门办理登记后，向劳动行政部门申请行政许可。\n未经依法许可和登记的机构，不得从事职业中介活动。\n国家对外商投资职业中介机构和向劳动者提供境外就业服务的职业中介机构另有规定的，依照其规定。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1172,'中华人民共和国就业促进法','第四十一条',41,'其他','第四章 就业服务和管理','职业中介机构不得有下列行为：\n（一）提供虚假就业信息；\n（二）为无合法证照的用人单位提供职业中介服务；\n（三）伪造、涂改、转让职业中介许可证；\n（四）扣押劳动者的居民身份证和其他证件，或者向劳动者收取押金；\n（五）其他违反法律、法规规定的行为。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1173,'中华人民共和国就业促进法','第四十二条',42,'其他','第四章 就业服务和管理','县级以上人民政府建立失业预警制度，对可能出现的较大规模的失业，实施预防、调节和控制。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1174,'中华人民共和国就业促进法','第四十三条',43,'其他','第四章 就业服务和管理','国家建立劳动力调查统计制度和就业登记、失业登记制度，开展劳动力资源和就业、失业状况调查统计，并公布调查统计结果。\n统计部门和劳动行政部门进行劳动力调查统计和就业、失业登记时，用人单位和个人应当如实提供调查统计和登记所需要的情况。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1175,'中华人民共和国就业促进法','第四十四条',44,'其他','第五章 职业教育和培训','国家依法发展职业教育，鼓励开展职业培训，促进劳动者提高职业技能，增强就业能力和创业能力。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1176,'中华人民共和国就业促进法','第四十五条',45,'其他','第五章 职业教育和培训','县级以上人民政府根据经济社会发展和市场需求，制定并实施职业能力开发计划。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1177,'中华人民共和国就业促进法','第四十六条',46,'其他','第五章 职业教育和培训','县级以上人民政府加强统筹协调，鼓励和支持各类职业院校、职业技能培训机构和用人单位依法开展就业前培训、在职培训、再就业培训和创业培训；鼓励劳动者参加各种形式的培训。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1178,'中华人民共和国就业促进法','第四十七条',47,'其他','第五章 职业教育和培训','县级以上地方人民政府和有关部门根据市场需求和产业发展方向，鼓励、指导企业加强职业教育和培训。\n职业院校、职业技能培训机构与企业应当密切联系，实行产教结合，为经济建设服务，培养实用人才和熟练劳动者。\n企业应当按照国家有关规定提取职工教育经费，对劳动者进行职业技能培训和继续教育培训。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1179,'中华人民共和国就业促进法','第四十八条',48,'其他','第五章 职业教育和培训','国家采取措施建立健全劳动预备制度，县级以上地方人民政府对有就业要求的初高中毕业生实行一定期限的职业教育和培训，使其取得相应的职业资格或者掌握一定的职业技能。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1180,'中华人民共和国就业促进法','第四十九条',49,'其他','第五章 职业教育和培训','地方各级人民政府鼓励和支持开展就业培训，帮助失业人员提高职业技能，增强其就业能力和创业能力。失业人员参加就业培训的，按照有关规定享受政府培训补贴。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1181,'中华人民共和国就业促进法','第五十条',50,'其他','第五章 职业教育和培训','地方各级人民政府采取有效措施，组织和引导进城就业的农村劳动者参加技能培训，鼓励各类培训机构为进城就业的农村劳动者提供技能培训，增强其就业能力和创业能力。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1182,'中华人民共和国就业促进法','第五十一条',51,'其他','第五章 职业教育和培训','国家对从事涉及公共安全、人身健康、生命财产安全等特殊工种的劳动者，实行职业资格证书制度，具体办法由国务院规定。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1183,'中华人民共和国就业促进法','第五十二条',52,'其他','第六章 就业援助','各级人民政府建立健全就业援助制度，采取税费减免、贷款贴息、社会保险补贴、岗位补贴等办法，通过公益性岗位安置等途径，对就业困难人员实行优先扶持和重点帮助。\n就业困难人员是指因身体状况、技能水平、家庭因素、失去土地等原因难以实现就业，以及连续失业一定时间仍未能实现就业的人员。就业困难人员的具体范围，由省、自治区、直辖市人民政府根据本行政区域的实际情况规定。','第五十二条','2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1184,'中华人民共和国就业促进法','第五十三条',53,'其他','第六章 就业援助','政府投资开发的公益性岗位，应当优先安排符合岗位要求的就业困难人员。被安排在公益性岗位工作的，按照国家规定给予岗位补贴。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1185,'中华人民共和国就业促进法','第五十四条',54,'其他','第六章 就业援助','地方各级人民政府加强基层就业援助服务工作，对就业困难人员实施重点帮助，提供有针对性的就业服务和公益性岗位援助。\n地方各级人民政府鼓励和支持社会各方面为就业困难人员提供技能培训、岗位信息等服务。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1186,'中华人民共和国就业促进法','第五十五条',55,'其他','第六章 就业援助','各级人民政府采取特别扶助措施，促进残疾人就业。\n用人单位应当按照国家规定安排残疾人就业，具体办法由国务院规定。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1187,'中华人民共和国就业促进法','第五十六条',56,'其他','第六章 就业援助','县级以上地方人民政府采取多种就业形式，拓宽公益性岗位范围，开发就业岗位，确保城市有就业需求的家庭至少有一人实现就业。\n法定劳动年龄内的家庭人员均处于失业状况的城市居民家庭，可以向住所地街道、社区公共就业服务机构申请就业援助。街道、社区公共就业服务机构经确认属实的，应当为该家庭中至少一人提供适当的就业岗位。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1188,'中华人民共和国就业促进法','第五十七条',57,'其他','第六章 就业援助','国家鼓励资源开采型城市和独立工矿区发展与市场需求相适应的产业，引导劳动者转移就业。\n对因资源枯竭或者经济结构调整等原因造成就业困难人员集中的地区，上级人民政府应当给予必要的扶持和帮助。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1189,'中华人民共和国就业促进法','第五十八条',58,'其他','第七章 监督检查','各级人民政府和有关部门应当建立促进就业的目标责任制度。县级以上人民政府按照促进就业目标责任制的要求，对所属的有关部门和下一级人民政府进行考核和监督。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1190,'中华人民共和国就业促进法','第五十九条',59,'其他','第七章 监督检查','审计机关、财政部门应当依法对就业专项资金的管理和使用情况进行监督检查。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1191,'中华人民共和国就业促进法','第六十条',60,'其他','第七章 监督检查','劳动行政部门应当对本法实施情况进行监督检查，建立举报制度，受理对违反本法行为的举报，并及时予以核实、处理。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1192,'中华人民共和国就业促进法','第六十一条',61,'其他','第八章 法律责任','违反本法规定，劳动行政等有关部门及其工作人员滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1193,'中华人民共和国就业促进法','第六十二条',62,'其他','第八章 法律责任','违反本法规定，实施就业歧视的，劳动者可以向人民法院提起诉讼。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1194,'中华人民共和国就业促进法','第六十三条',63,'其他','第八章 法律责任','违反本法规定，地方各级人民政府和有关部门、公共就业服务机构举办经营性的职业中介机构，从事经营性职业中介活动，向劳动者收取费用的，由上级主管机关责令限期改正，将违法收取的费用退还劳动者，并对直接负责的主管人员和其他直接责任人员依法给予处分。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1195,'中华人民共和国就业促进法','第六十四条',64,'其他','第八章 法律责任','违反本法规定，未经许可和登记，擅自从事职业中介活动的，由劳动行政部门或者其他主管部门依法予以关闭；有违法所得的，没收违法所得，并处一万元以上五万元以下的罚款。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1196,'中华人民共和国就业促进法','第六十五条',65,'其他','第八章 法律责任','违反本法规定，职业中介机构提供虚假就业信息，为无合法证照的用人单位提供职业中介服务，伪造、涂改、转让职业中介许可证的，由劳动行政部门或者其他主管部门责令改正；有违法所得的，没收违法所得，并处一万元以上五万元以下的罚款；情节严重的，吊销职业中介许可证。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1197,'中华人民共和国就业促进法','第六十六条',66,'其他','第八章 法律责任','违反本法规定，职业中介机构扣押劳动者居民身份证等证件的，由劳动行政部门责令限期退还劳动者，并依照有关法律规定给予处罚。\n违反本法规定，职业中介机构向劳动者收取押金的，由劳动行政部门责令限期退还劳动者，并以每人五百元以上二千元以下的标准处以罚款。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1198,'中华人民共和国就业促进法','第六十七条',67,'其他','第八章 法律责任','违反本法规定，企业未按照国家规定提取职工教育经费，或者挪用职工教育经费的，由劳动行政部门责令改正，并依法给予处罚。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1199,'中华人民共和国就业促进法','第六十八条',68,'其他','第八章 法律责任','违反本法规定，侵害劳动者合法权益，造成财产损失或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1200,'中华人民共和国就业促进法','第六十九条',69,'其他','第九章 附 则','本法自2008年1月1日起施行。',NULL,'2015-04-24','flk_npc','2c909fdd678bf17901678bf7b34f07df','2026-09-16 20:36:08','2026-09-17 16:50:03');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1201,'中华人民共和国工会法','第一条',1,'其他','第一章 总 则','为保障工会在国家政治、经济和社会生活中的地位，确定工会的权利与义务，发挥工会在社会主义现代化建设事业中的作用，根据宪法，制定本法。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1202,'中华人民共和国工会法','第二条',2,'其他','第一章 总 则','工会是中国共产党领导的职工自愿结合的工人阶级群众组织，是中国共产党联系职工群众的桥梁和纽带。\n中华全国总工会及其各工会组织代表职工的利益，依法维护职工的合法权益。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1203,'中华人民共和国工会法','第三条',3,'其他','第一章 总 则','在中国境内的企业、事业单位、机关、社会组织（以下统称用人单位）中以工资收入为主要生活来源的劳动者，不分民族、种族、性别、职业、宗教信仰、教育程度，都有依法参加和组织工会的权利。任何组织和个人不得阻挠和限制。\n工会适应企业组织形式、职工队伍结构、劳动关系、就业形态等方面的发展变化，依法维护劳动者参加和组织工会的权利。','第三条','2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1204,'中华人民共和国工会法','第四条',4,'其他','第一章 总 则','工会必须遵守和维护宪法，以宪法为根本的活动准则，以经济建设为中心，坚持社会主义道路，坚持人民民主专政，坚持中国共产党的领导，坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想，坚持改革开放，保持和增强政治性、先进性、群众性，依照工会章程独立自主地开展工作。\n工会会员全国代表大会制定或者修改《中国工会章程》，章程不得与宪法和法律相抵触。\n国家保护工会的合法权益不受侵犯。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1205,'中华人民共和国工会法','第五条',5,'其他','第一章 总 则','工会组织和教育职工依照宪法和法律的规定行使民主权利，发挥国家主人翁的作用，通过各种途径和形式，参与管理国家事务、管理经济和文化事业、管理社会事务；协助人民政府开展工作，维护工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家政权。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1206,'中华人民共和国工会法','第六条',6,'其他','第一章 总 则','维护职工合法权益、竭诚服务职工群众是工会的基本职责。工会在维护全国人民总体利益的同时，代表和维护职工的合法权益。\n工会通过平等协商和集体合同制度等，推动健全劳动关系协调机制，维护职工劳动权益，构建和谐劳动关系。\n工会依照法律规定通过职工代表大会或者其他形式，组织职工参与本单位的民主选举、民主协商、民主决策、民主管理和民主监督。\n工会建立联系广泛、服务职工的工会工作体系，密切联系职工，听取和反映职工的意见和要求，关心职工的生活，帮助职工解决困难，全心全意为职工服务。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1207,'中华人民共和国工会法','第七条',7,'其他','第一章 总 则','工会动员和组织职工积极参加经济建设，努力完成生产任务和工作任务。教育职工不断提高思想道德、技术业务和科学文化素质，建设有理想、有道德、有文化、有纪律的职工队伍。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1208,'中华人民共和国工会法','第八条',8,'其他','第一章 总 则','工会推动产业工人队伍建设改革，提高产业工人队伍整体素质，发挥产业工人骨干作用，维护产业工人合法权益，保障产业工人主人翁地位，造就一支有理想守信念、懂技术会创新、敢担当讲奉献的宏大产业工人队伍。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1209,'中华人民共和国工会法','第九条',9,'其他','第一章 总 则','中华全国总工会根据独立、平等、互相尊重、互不干涉内部事务的原则，加强同各国工会组织的友好合作关系。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1210,'中华人民共和国工会法','第十条',10,'其他','第二章 工会组织','工会各级组织按照民主集中制原则建立。\n各级工会委员会由会员大会或者会员代表大会民主选举产生。企业主要负责人的近亲属不得作为本企业基层工会委员会成员的人选。\n各级工会委员会向同级会员大会或者会员代表大会负责并报告工作，接受其监督。\n工会会员大会或者会员代表大会有权撤换或者罢免其所选举的代表或者工会委员会组成人员。\n上级工会组织领导下级工会组织。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1211,'中华人民共和国工会法','第十一条',11,'其他','第二章 工会组织','用人单位有会员二十五人以上的，应当建立基层工会委员会；不足二十五人的，可以单独建立基层工会委员会，也可以由两个以上单位的会员联合建立基层工会委员会，也可以选举组织员一人，组织会员开展活动。女职工人数较多的，可以建立工会女职工委员会，在同级工会领导下开展工作；女职工人数较少的，可以在工会委员会中设女职工委员。\n企业职工较多的乡镇、城市街道，可以建立基层工会的联合会。\n县级以上地方建立地方各级总工会。\n同一行业或者性质相近的几个行业，可以根据需要建立全国的或者地方的产业工会。\n全国建立统一的中华全国总工会。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1212,'中华人民共和国工会法','第十二条',12,'其他','第二章 工会组织','基层工会、地方各级总工会、全国或者地方产业工会组织的建立，必须报上一级工会批准。\n上级工会可以派员帮助和指导企业职工组建工会，任何单位和个人不得阻挠。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1213,'中华人民共和国工会法','第十三条',13,'其他','第二章 工会组织','任何组织和个人不得随意撤销、合并工会组织。\n基层工会所在的用人单位终止或者被撤销，该工会组织相应撤销，并报告上一级工会。\n依前款规定被撤销的工会，其会员的会籍可以继续保留，具体管理办法由中华全国总工会制定。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1214,'中华人民共和国工会法','第十四条',14,'其他','第二章 工会组织','职工二百人以上的企业、事业单位、社会组织的工会，可以设专职工会主席。工会专职工作人员的人数由工会与企业、事业单位、社会组织协商确定。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1215,'中华人民共和国工会法','第十五条',15,'其他','第二章 工会组织','中华全国总工会、地方总工会、产业工会具有社会团体法人资格。\n基层工会组织具备民法典规定的法人条件的，依法取得社会团体法人资格。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1216,'中华人民共和国工会法','第十六条',16,'其他','第二章 工会组织','基层工会委员会每届任期三年或者五年。各级地方总工会委员会和产业工会委员会每届任期五年。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1217,'中华人民共和国工会法','第十七条',17,'其他','第二章 工会组织','基层工会委员会定期召开会员大会或者会员代表大会，讨论决定工会工作的重大问题。经基层工会委员会或者三分之一以上的工会会员提议，可以临时召开会员大会或者会员代表大会。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1218,'中华人民共和国工会法','第十八条',18,'其他','第二章 工会组织','工会主席、副主席任期未满时，不得随意调动其工作。因工作需要调动时，应当征得本级工会委员会和上一级工会的同意。\n罢免工会主席、副主席必须召开会员大会或者会员代表大会讨论，非经会员大会全体会员或者会员代表大会全体代表过半数通过，不得罢免。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1219,'中华人民共和国工会法','第十九条',19,'其他','第二章 工会组织','基层工会专职主席、副主席或者委员自任职之日起，其劳动合同期限自动延长，延长期限相当于其任职期间；非专职主席、副主席或者委员自任职之日起，其尚未履行的劳动合同期限短于任期的，劳动合同期限自动延长至任期期满。但是，任职期间个人严重过失或者达到法定退休年龄的除外。','第十九条','2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1220,'中华人民共和国工会法','第二十条',20,'其他','第三章 工会的权利和义务','企业、事业单位、社会组织违反职工代表大会制度和其他民主管理制度，工会有权要求纠正，保障职工依法行使民主管理的权利。\n法律、法规规定应当提交职工大会或者职工代表大会审议、通过、决定的事项，企业、事业单位、社会组织应当依法办理。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1221,'中华人民共和国工会法','第二十一条',21,'其他','第三章 工会的权利和义务','工会帮助、指导职工与企业、实行企业化管理的事业单位、社会组织签订劳动合同。\n工会代表职工与企业、实行企业化管理的事业单位、社会组织进行平等协商，依法签订集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。\n工会签订集体合同，上级工会应当给予支持和帮助。\n企业、事业单位、社会组织违反集体合同，侵犯职工劳动权益的，工会可以依法要求企业、事业单位、社会组织予以改正并承担责任；因履行集体合同发生争议，经协商解决不成的，工会可以向劳动争议仲裁机构提请仲裁，仲裁机构不予受理或者对仲裁裁决不服的，可以向人民法院提起诉讼。','第二十一条','2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1222,'中华人民共和国工会法','第二十二条',22,'其他','第三章 工会的权利和义务','企业、事业单位、社会组织处分职工，工会认为不适当的，有权提出意见。\n用人单位单方面解除职工劳动合同时，应当事先将理由通知工会，工会认为用人单位违反法律、法规和有关合同，要求重新研究处理时，用人单位应当研究工会的意见，并将处理结果书面通知工会。\n职工认为用人单位侵犯其劳动权益而申请劳动争议仲裁或者向人民法院提起诉讼的，工会应当给予支持和帮助。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1223,'中华人民共和国工会法','第二十三条',23,'其他','第三章 工会的权利和义务','企业、事业单位、社会组织违反劳动法律法规规定，有下列侵犯职工劳动权益情形，工会应当代表职工与企业、事业单位、社会组织交涉，要求企业、事业单位、社会组织采取措施予以改正；企业、事业单位、社会组织应当予以研究处理，并向工会作出答复；企业、事业单位、社会组织拒不改正的，工会可以提请当地人民政府依法作出处理：\n（一）克扣、拖欠职工工资的；\n（二）不提供劳动安全卫生条件的；\n（三）随意延长劳动时间的；\n（四）侵犯女职工和未成年工特殊权益的；\n（五）其他严重侵犯职工劳动权益的。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1224,'中华人民共和国工会法','第二十四条',24,'其他','第三章 工会的权利和义务','工会依照国家规定对新建、扩建企业和技术改造工程中的劳动条件和安全卫生设施与主体工程同时设计、同时施工、同时投产使用进行监督。对工会提出的意见，企业或者主管部门应当认真处理，并将处理结果书面通知工会。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1225,'中华人民共和国工会法','第二十五条',25,'其他','第三章 工会的权利和义务','工会发现企业违章指挥、强令工人冒险作业，或者生产过程中发现明显重大事故隐患和职业危害，有权提出解决的建议，企业应当及时研究答复；发现危及职工生命安全的情况时，工会有权向企业建议组织职工撤离危险现场，企业必须及时作出处理决定。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1226,'中华人民共和国工会法','第二十六条',26,'其他','第三章 工会的权利和义务','工会有权对企业、事业单位、社会组织侵犯职工合法权益的问题进行调查，有关单位应当予以协助。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1227,'中华人民共和国工会法','第二十七条',27,'其他','第三章 工会的权利和义务','职工因工伤亡事故和其他严重危害职工健康问题的调查处理，必须有工会参加。工会应当向有关部门提出处理意见，并有权要求追究直接负责的主管人员和有关责任人员的责任。对工会提出的意见，应当及时研究，给予答复。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1228,'中华人民共和国工会法','第二十八条',28,'其他','第三章 工会的权利和义务','企业、事业单位、社会组织发生停工、怠工事件，工会应当代表职工同企业、事业单位、社会组织或者有关方面协商，反映职工的意见和要求并提出解决意见。对于职工的合理要求，企业、事业单位、社会组织应当予以解决。工会协助企业、事业单位、社会组织做好工作，尽快恢复生产、工作秩序。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1229,'中华人民共和国工会法','第二十九条',29,'其他','第三章 工会的权利和义务','工会参加企业的劳动争议调解工作。\n地方劳动争议仲裁组织应当有同级工会代表参加。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1230,'中华人民共和国工会法','第三十条',30,'其他','第三章 工会的权利和义务','县级以上各级总工会依法为所属工会和职工提供法律援助等法律服务。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1231,'中华人民共和国工会法','第三十一条',31,'其他','第三章 工会的权利和义务','工会协助用人单位办好职工集体福利事业，做好工资、劳动安全卫生和社会保险工作。','第三十一条','2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1232,'中华人民共和国工会法','第三十二条',32,'其他','第三章 工会的权利和义务','工会会同用人单位加强对职工的思想政治引领，教育职工以国家主人翁态度对待劳动，爱护国家和单位的财产；组织职工开展群众性的合理化建议、技术革新、劳动和技能竞赛活动，进行业余文化技术学习和职工培训，参加职业教育和文化体育活动，推进职业安全健康教育和劳动保护工作。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1233,'中华人民共和国工会法','第三十三条',33,'其他','第三章 工会的权利和义务','根据政府委托，工会与有关部门共同做好劳动模范和先进生产（工作）者的评选、表彰、培养和管理工作。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1234,'中华人民共和国工会法','第三十四条',34,'其他','第三章 工会的权利和义务','国家机关在组织起草或者修改直接涉及职工切身利益的法律、法规、规章时，应当听取工会意见。\n县级以上各级人民政府制定国民经济和社会发展计划，对涉及职工利益的重大问题，应当听取同级工会的意见。\n县级以上各级人民政府及其有关部门研究制定劳动就业、工资、劳动安全卫生、社会保险等涉及职工切身利益的政策、措施时，应当吸收同级工会参加研究，听取工会意见。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1235,'中华人民共和国工会法','第三十五条',35,'其他','第三章 工会的权利和义务','县级以上地方各级人民政府可以召开会议或者采取适当方式，向同级工会通报政府的重要的工作部署和与工会工作有关的行政措施，研究解决工会反映的职工群众的意见和要求。\n各级人民政府劳动行政部门应当会同同级工会和企业方面代表，建立劳动关系三方协商机制，共同研究解决劳动关系方面的重大问题。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1236,'中华人民共和国工会法','第三十六条',36,'其他','第四章 基层工会组织','国有企业职工代表大会是企业实行民主管理的基本形式，是职工行使民主管理权力的机构，依照法律规定行使职权。\n国有企业的工会委员会是职工代表大会的工作机构，负责职工代表大会的日常工作，检查、督促职工代表大会决议的执行。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1237,'中华人民共和国工会法','第三十七条',37,'其他','第四章 基层工会组织','集体企业的工会委员会，应当支持和组织职工参加民主管理和民主监督，维护职工选举和罢免管理人员、决定经营管理的重大问题的权力。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1238,'中华人民共和国工会法','第三十八条',38,'其他','第四章 基层工会组织','本法第三十六条、第三十七条规定以外的其他企业、事业单位的工会委员会，依照法律规定组织职工采取与企业、事业单位相适应的形式，参与企业、事业单位民主管理。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1239,'中华人民共和国工会法','第三十九条',39,'其他','第四章 基层工会组织','企业、事业单位、社会组织研究经营管理和发展的重大问题应当听取工会的意见；召开会议讨论有关工资、福利、劳动安全卫生、工作时间、休息休假、女职工保护和社会保险等涉及职工切身利益的问题，必须有工会代表参加。\n企业、事业单位、社会组织应当支持工会依法开展工作，工会应当支持企业、事业单位、社会组织依法行使经营管理权。','第三十九条','2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1240,'中华人民共和国工会法','第四十条',40,'其他','第四章 基层工会组织','公司的董事会、监事会中职工代表的产生，依照公司法有关规定执行。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1241,'中华人民共和国工会法','第四十一条',41,'其他','第四章 基层工会组织','基层工会委员会召开会议或者组织职工活动，应当在生产或者工作时间以外进行，需要占用生产或者工作时间的，应当事先征得企业、事业单位、社会组织的同意。\n基层工会的非专职委员占用生产或者工作时间参加会议或者从事工会工作，每月不超过三个工作日，其工资照发，其他待遇不受影响。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1242,'中华人民共和国工会法','第四十二条',42,'其他','第四章 基层工会组织','用人单位工会委员会的专职工作人员的工资、奖励、补贴，由所在单位支付。社会保险和其他福利待遇等，享受本单位职工同等待遇。','第四十二条','2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1243,'中华人民共和国工会法','第四十三条',43,'其他','第五章 工会的经费和财产','工会经费的来源：\n（一）工会会员缴纳的会费；\n（二）建立工会组织的用人单位按每月全部职工工资总额的百分之二向工会拨缴的经费；\n（三）工会所属的企业、事业单位上缴的收入；\n（四）人民政府的补助；\n（五）其他收入。\n前款第二项规定的企业、事业单位、社会组织拨缴的经费在税前列支。\n工会经费主要用于为职工服务和工会活动。经费使用的具体办法由中华全国总工会制定。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1244,'中华人民共和国工会法','第四十四条',44,'其他','第五章 工会的经费和财产','企业、事业单位、社会组织无正当理由拖延或者拒不拨缴工会经费，基层工会或者上级工会可以向当地人民法院申请支付令；拒不执行支付令的，工会可以依法申请人民法院强制执行。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1245,'中华人民共和国工会法','第四十五条',45,'其他','第五章 工会的经费和财产','工会应当根据经费独立原则，建立预算、决算和经费审查监督制度。\n各级工会建立经费审查委员会。\n各级工会经费收支情况应当由同级工会经费审查委员会审查，并且定期向会员大会或者会员代表大会报告，接受监督。工会会员大会或者会员代表大会有权对经费使用情况提出意见。\n工会经费的使用应当依法接受国家的监督。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1246,'中华人民共和国工会法','第四十六条',46,'其他','第五章 工会的经费和财产','各级人民政府和用人单位应当为工会办公和开展活动，提供必要的设施和活动场所等物质条件。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1247,'中华人民共和国工会法','第四十七条',47,'其他','第五章 工会的经费和财产','工会的财产、经费和国家拨给工会使用的不动产，任何组织和个人不得侵占、挪用和任意调拨。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1248,'中华人民共和国工会法','第四十八条',48,'其他','第五章 工会的经费和财产','工会所属的为职工服务的企业、事业单位，其隶属关系不得随意改变。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1249,'中华人民共和国工会法','第四十九条',49,'其他','第五章 工会的经费和财产','县级以上各级工会的离休、退休人员的待遇，与国家机关工作人员同等对待。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1250,'中华人民共和国工会法','第五十条',50,'其他','第六章 法律责任','工会对违反本法规定侵犯其合法权益的，有权提请人民政府或者有关部门予以处理，或者向人民法院提起诉讼。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1251,'中华人民共和国工会法','第五十一条',51,'其他','第六章 法律责任','违反本法第三条、第十二条规定，阻挠职工依法参加和组织工会或者阻挠上级工会帮助、指导职工筹建工会的，由劳动行政部门责令其改正；拒不改正的，由劳动行政部门提请县级以上人民政府处理；以暴力、威胁等手段阻挠造成严重后果，构成犯罪的，依法追究刑事责任。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1252,'中华人民共和国工会法','第五十二条',52,'其他','第六章 法律责任','违反本法规定，对依法履行职责的工会工作人员无正当理由调动工作岗位，进行打击报复的，由劳动行政部门责令改正、恢复原工作；造成损失的，给予赔偿。\n对依法履行职责的工会工作人员进行侮辱、诽谤或者进行人身伤害，构成犯罪的，依法追究刑事责任；尚未构成犯罪的，由公安机关依照治安管理处罚法的规定处罚。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1253,'中华人民共和国工会法','第五十三条',53,'其他','第六章 法律责任','违反本法规定，有下列情形之一的，由劳动行政部门责令恢复其工作，并补发被解除劳动合同期间应得的报酬，或者责令给予本人年收入二倍的赔偿：\n（一）职工因参加工会活动而被解除劳动合同的；\n（二）工会工作人员因履行本法规定的职责而被解除劳动合同的。','第五十三条','2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1254,'中华人民共和国工会法','第五十四条',54,'其他','第六章 法律责任','违反本法规定，有下列情形之一的，由县级以上人民政府责令改正，依法处理：\n（一）妨碍工会组织职工通过职工代表大会和其他形式依法行使民主权利的；\n（二）非法撤销、合并工会组织的；\n（三）妨碍工会参加职工因工伤亡事故以及其他侵犯职工合法权益问题的调查处理的；\n（四）无正当理由拒绝进行平等协商的。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1255,'中华人民共和国工会法','第五十五条',55,'其他','第六章 法律责任','违反本法第四十七条规定，侵占工会经费和财产拒不返还的，工会可以向人民法院提起诉讼，要求返还，并赔偿损失。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1256,'中华人民共和国工会法','第五十六条',56,'其他','第六章 法律责任','工会工作人员违反本法规定，损害职工或者工会权益的，由同级工会或者上级工会责令改正，或者予以处分；情节严重的，依照《中国工会章程》予以罢免；造成损失的，应当承担赔偿责任；构成犯罪的，依法追究刑事责任。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1257,'中华人民共和国工会法','第五十七条',57,'其他','第七章 附 则','中华全国总工会会同有关国家机关制定机关工会实施本法的具体办法。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1258,'中华人民共和国工会法','第五十八条',58,'其他','第七章 附 则','本法自公布之日起施行。1950年6月29日中央人民政府颁布的《中华人民共和国工会法》同时废止。',NULL,'2022-01-01','flk_npc','ff8081817f072a2e017f0ae1a7f600f0','2026-09-16 20:36:14','2026-09-17 16:50:08');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1259,'工伤保险条例','第五十九条',59,'社会保险','第七章 法律责任','医疗机构、辅助器具配置机构不按服务协议提供服务的，经办机构可以解除服务协议。\n经办机构不按时足额结算费用的，由社会保险行政部门责令改正；医疗机构、辅助器具配置机构可以解除服务协议。','第五十九条','2011-01-01','flk_npc','ff8080816f3cbb3c016f40d5bc0f0659','2026-09-16 20:36:23','2026-09-17 16:48:54');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1260,'工伤保险条例','第三十七条',37,'社会保险','第五章 工伤保险待遇','职工因工致残被鉴定为七级至十级伤残的，享受以下待遇：\n(一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：七级伤残为13个月的本人工资，八级伤残为11个月的本人工资，九级伤残为9个月的本人工资，十级伤残为7个月的本人工资；\n(二)劳动、聘用合同期满终止，或者职工本人提出解除劳动、聘用合同的，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。','第三十七条','2011-01-01','flk_npc','ff8080816f3cbb3c016f40d5bc0f0659','2026-09-16 20:36:23','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1261,'工伤保险条例','第六十四条',64,'社会保险','第八章 附则','本条例所称工资总额，是指用人单位直接支付给本单位全部职工的劳动报酬总额。\n本条例所称本人工资，是指工伤职工因工作遭受事故伤害或者患职业病前12个月平均月缴费工资。本人工资高于统筹地区职工平均工资300%的，按照统筹地区职工平均工资的300%计算；本人工资低于统筹地区职工平均工资60%的，按照统筹地区职工平均工资的60%计算。','第六十四条','2011-01-01','flk_npc','ff8080816f3cbb3c016f40d5bc0f0659','2026-09-16 20:36:23','2026-09-17 16:48:54');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1262,'工伤保险条例','第五条',5,'社会保险','第一章 总则','国务院社会保险行政部门负责全国的工伤保险工作。\n县级以上地方各级人民政府社会保险行政部门负责本行政区域内的工伤保险工作。\n社会保险行政部门按照国务院有关规定设立的社会保险经办机构(以下称经办机构)具体承办工伤保险事务。','第五条','2011-01-01','flk_npc','ff8080816f3cbb3c016f40d5bc0f0659','2026-09-16 20:36:23','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1263,'工伤保险条例','第六条',6,'社会保险','第一章 总则','社会保险行政部门等部门制定工伤保险的政策、标准，应当征求工会组织、用人单位代表的意见。','第六条','2011-01-01','flk_npc','ff8080816f3cbb3c016f40d5bc0f0659','2026-09-16 20:36:23','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1264,'失业保险条例','第二十一条',21,'社会保险','第三章 失业保险待遇','单位招用的农民合同制工人连续工作满1年，本单位并已缴纳失业保险费，劳动合同期满未续订或者提前解除劳动合同的，由社会保险经办机构根据其工作时间长短，对其支付一次性生活补助。补助的办法和标准由省、自治区、直辖市人民政府规定。','第二十一条',NULL,'flk_npc','ff8080816f3cbb3c016f40f8971f0ef3','2026-09-16 20:36:29','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1265,'失业保险条例','第十六条',16,'社会保险','第三章 失业保险待遇','城镇企业事业单位应当及时为失业人员出具终止或者解除劳动关系的证明，告知其按照规定享受失业保险待遇的权利，并将失业人员的名单自终止或者解除劳动关系之日起7日内报社会保险经办机构备案。\n城镇企业事业单位职工失业后，应当持本单位为其出具的终止或者解除劳动关系的证明，及时到指定的社会保险经办机构办理失业登记。失业保险金自办理失业登记之日起计算。\n失业保险金由社会保险经办机构按月发放。社会保险经办机构为失业人员开具领取失业保险金的单证，失业人员凭单证到指定银行领取失业保险金。','第十六条',NULL,'flk_npc','ff8080816f3cbb3c016f40f8971f0ef3','2026-09-16 20:36:29','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1266,'失业保险条例','第六条',6,'社会保险','第二章 失业保险基金','城镇企业事业单位按照本单位工资总额的2%缴纳失业保险费。城镇企业事业单位职工按照本人工资的1%缴纳失业保险费。城镇企业事业单位招用的农民合同制工人本人不缴纳失业保险费。','第六条',NULL,'flk_npc','ff8080816f3cbb3c016f40f8971f0ef3','2026-09-16 20:36:29','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1267,'失业保险条例','第十八条',18,'社会保险','第三章 失业保险待遇','失业保险金的标准，按照低于当地最低工资标准、高于城市居民最低生活保障标准的水平，由省、自治区、直辖市人民政府确定。','第十八条',NULL,'flk_npc','ff8080816f3cbb3c016f40f8971f0ef3','2026-09-16 20:36:29','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1268,'失业保险条例','第四条',4,'社会保险','第一章 总则','失业保险费按照国家有关规定征缴。','第四条',NULL,'flk_npc','ff8080816f3cbb3c016f40f8971f0ef3','2026-09-16 20:36:29','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1269,'失业保险条例','第十二条',12,'社会保险','第二章 失业保险基金','失业保险基金收支的预算、决算，由统筹地区社会保险经办机构编制，经同级劳动保障行政部门复核、同级财政部门审核，报同级人民政府审批。','第十二条',NULL,'flk_npc','ff8080816f3cbb3c016f40f8971f0ef3','2026-09-16 20:36:29','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1270,'失业保险条例','第二十七条',27,'社会保险','第四章 管理和监督','社会保险经办机构所需经费列入预算，由财政拨付。','第二十七条',NULL,'flk_npc','ff8080816f3cbb3c016f40f8971f0ef3','2026-09-16 20:36:29','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1271,'社会保险费征缴暂行条例','第十八条',18,'社会保险','第三章 监督检查','按照省、自治区、直辖市人民政府关于社会保险费征缴机构的规定，劳动保障行政部门或者税务机关依法对单位缴费情况进行检查时，被检查的单位应当提供与缴纳社会保险费有关的用人情况、工资表、财务报表等资料，如实反映情况，不得拒绝检查，不得谎报、瞒报。劳动保障行政部门或者税务机关可以记录、录音、录像、照相和复制有关资料；但是，应当为缴费单位保密。\n劳动保障行政部门、税务机关的工作人员在行使前款所列职权时，应当出示执行公务证件。','第十八条',NULL,'flk_npc','ff8080816f3cbb3c016f40f97d360f29','2026-09-16 20:36:34','2026-09-17 16:48:54');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1272,'社会保险费征缴暂行条例','第四条',4,'社会保险','第一章 总则','缴费单位、缴费个人应当按时足额缴纳社会保险费。\n征缴的社会保险费纳入社会保险基金，专款专用，任何单位和个人不得挪用。','第四条',NULL,'flk_npc','ff8080816f3cbb3c016f40f97d360f29','2026-09-16 20:36:34','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1273,'社会保险费征缴暂行条例','第六条',6,'社会保险','第一章 总则','社会保险费实行三项社会保险费集中、统一征收。社会保险费的征收机构由省、自治区、直辖市人民政府规定，可以由税务机关征收，也可以由劳动保障行政部门按照国务院规定设立的社会保险经办机构(以下简称社会保险经办机构)征收。','第六条',NULL,'flk_npc','ff8080816f3cbb3c016f40f97d360f29','2026-09-16 20:36:34','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1274,'社会保险费征缴暂行条例','第七条',7,'社会保险','第二章 征缴管理','缴费单位必须向当地社会保险经办机构办理社会保险登记，参加社会保险。\n登记事项包括：单位名称、住所、经营地点、单位类型、法定代表人或者负责人、开户银行账号以及国务院劳动保障行政部门规定的其他事项。','第七条',NULL,'flk_npc','ff8080816f3cbb3c016f40f97d360f29','2026-09-16 20:36:34','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1275,'社会保险费征缴暂行条例','第十条',10,'社会保险','第二章 征缴管理','缴费单位必须按月向社会保险经办机构申报应缴纳的社会保险费数额，经社会保险经办机构核定后，在规定的期限内缴纳社会保险费。\n缴费单位不按规定申报应缴纳的社会保险费数额的，由社会保险经办机构暂按该单位上月缴费数额的110%确定应缴数额；没有上月缴费数额的，由社会保险经办机构暂按该单位的经营状况、职工人数等有关情况确定应缴数额。缴费单位补办申报手续并按核定数额缴纳社会保险费后，由社会保险经办机构按照规定结算。','第十条',NULL,'flk_npc','ff8080816f3cbb3c016f40f97d360f29','2026-09-16 20:36:34','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1276,'女职工劳动保护特别规定','第五条',5,'其他',NULL,'用人单位不得因女职工怀孕、生育、哺乳降低其工资、予以辞退、与其解除劳动或者聘用合同。','第五条',NULL,'flk_npc','ff8080816f3cbb3c016f410f1ed51451','2026-09-16 20:36:41','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1277,'女职工劳动保护特别规定','第八条',8,'其他',NULL,'女职工产假期间的生育津贴，对已经参加生育保险的，按照用人单位上年度职工月平均工资的标准由生育保险基金支付；对未参加生育保险的，按照女职工产假前工资的标准由用人单位支付。\n女职工生育或者流产的医疗费用，按照生育保险规定的项目和标准，对已经参加生育保险的，由生育保险基金支付；对未参加生育保险的，由用人单位支付。','第八条',NULL,'flk_npc','ff8080816f3cbb3c016f410f1ed51451','2026-09-16 20:36:41','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1278,'中华人民共和国劳动合同法','第一条',1,'劳动合同','第一章 总 则','为了完善劳动合同制度，明确劳动合同双方当事人的权利和义务，保护劳动者的合法权益，构建和发展和谐稳定的劳动关系，制定本法。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1279,'中华人民共和国劳动合同法','第二条',2,'劳动合同','第一章 总 则','中华人民共和国境内的企业、个体经济组织、民办非企业单位等组织（以下称用人单位）与劳动者建立劳动关系，订立、履行、变更、解除或者终止劳动合同，适用本法。\n国家机关、事业单位、社会团体和与其建立劳动关系的劳动者，订立、履行、变更、解除或者终止劳动合同，依照本法执行。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1280,'中华人民共和国劳动合同法','第三条',3,'劳动合同','第一章 总 则','订立劳动合同，应当遵循合法、公平、平等自愿、协商一致、诚实信用的原则。\n依法订立的劳动合同具有约束力，用人单位与劳动者应当履行劳动合同约定的义务。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1281,'中华人民共和国劳动合同法','第四条',4,'劳动合同','第一章 总 则','用人单位应当依法建立和完善劳动规章制度，保障劳动者享有劳动权利、履行劳动义务。\n用人单位在制定、修改或者决定有关劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利、职工培训、劳动纪律以及劳动定额管理等直接涉及劳动者切身利益的规章制度或者重大事项时，应当经职工代表大会或者全体职工讨论，提出方案和意见，与工会或者职工代表平等协商确定。\n在规章制度和重大事项决定实施过程中，工会或者职工认为不适当的，有权向用人单位提出，通过协商予以修改完善。\n用人单位应当将直接涉及劳动者切身利益的规章制度和重大事项决定公示，或者告知劳动者。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1282,'中华人民共和国劳动合同法','第五条',5,'劳动合同','第一章 总 则','县级以上人民政府劳动行政部门会同工会和企业方面代表，建立健全协调劳动关系三方机制，共同研究解决有关劳动关系的重大问题。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1283,'中华人民共和国劳动合同法','第六条',6,'劳动合同','第一章 总 则','工会应当帮助、指导劳动者与用人单位依法订立和履行劳动合同，并与用人单位建立集体协商机制，维护劳动者的合法权益。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1284,'中华人民共和国劳动合同法','第七条',7,'劳动合同','第二章 劳动合同的订立','用人单位自用工之日起即与劳动者建立劳动关系。用人单位应当建立职工名册备查。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1285,'中华人民共和国劳动合同法','第八条',8,'劳动合同','第二章 劳动合同的订立','用人单位招用劳动者时，应当如实告知劳动者工作内容、工作条件、工作地点、职业危害、安全生产状况、劳动报酬，以及劳动者要求了解的其他情况；用人单位有权了解劳动者与劳动合同直接相关的基本情况，劳动者应当如实说明。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1288,'中华人民共和国劳动合同法','第十一条',11,'劳动合同','第二章 劳动合同的订立','用人单位未在用工的同时订立书面劳动合同，与劳动者约定的劳动报酬不明确的，新招用的劳动者的劳动报酬按照集体合同规定的标准执行；没有集体合同或者集体合同未规定的，实行同工同酬。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1289,'中华人民共和国劳动合同法','第十二条',12,'劳动合同','第二章 劳动合同的订立','劳动合同分为固定期限劳动合同、无固定期限劳动合同和以完成一定工作任务为期限的劳动合同。','第十二条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1290,'中华人民共和国劳动合同法','第十三条',13,'劳动合同','第二章 劳动合同的订立','固定期限劳动合同，是指用人单位与劳动者约定合同终止时间的劳动合同。\n用人单位与劳动者协商一致，可以订立固定期限劳动合同。','第十三条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1291,'中华人民共和国劳动合同法','第十四条',14,'劳动合同','第二章 劳动合同的订立','无固定期限劳动合同，是指用人单位与劳动者约定无确定终止时间的劳动合同。\n用人单位与劳动者协商一致，可以订立无固定期限劳动合同。有下列情形之一，劳动者提出或者同意续订、订立劳动合同的，除劳动者提出订立固定期限劳动合同外，应当订立无固定期限劳动合同：\n（一）劳动者在该用人单位连续工作满十年的；\n（二）用人单位初次实行劳动合同制度或者国有企业改制重新订立劳动合同时，劳动者在该用人单位连续工作满十年且距法定退休年龄不足十年的；\n（三）连续订立二次固定期限劳动合同，且劳动者没有本法第三十九条和第四十条第一项、第二项规定的情形，续订劳动合同的。\n用人单位自用工之日起满一年不与劳动者订立书面劳动合同的，视为用人单位与劳动者已订立无固定期限劳动合同。','第十四条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1292,'中华人民共和国劳动合同法','第十五条',15,'劳动合同','第二章 劳动合同的订立','以完成一定工作任务为期限的劳动合同，是指用人单位与劳动者约定以某项工作的完成为合同期限的劳动合同。\n用人单位与劳动者协商一致，可以订立以完成一定工作任务为期限的劳动合同。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1293,'中华人民共和国劳动合同法','第十六条',16,'劳动合同','第二章 劳动合同的订立','劳动合同由用人单位与劳动者协商一致，并经用人单位与劳动者在劳动合同文本上签字或者盖章生效。\n劳动合同文本由用人单位和劳动者各执一份。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1294,'中华人民共和国劳动合同法','第十七条',17,'劳动合同','第二章 劳动合同的订立','劳动合同应当具备以下条款：\n（一）用人单位的名称、住所和法定代表人或者主要负责人；\n（二）劳动者的姓名、住址和居民身份证或者其他有效身份证件号码；\n（三）劳动合同期限；\n（四）工作内容和工作地点；\n（五）工作时间和休息休假；\n（六）劳动报酬；\n（七）社会保险；\n（八）劳动保护、劳动条件和职业危害防护；\n（九）法律、法规规定应当纳入劳动合同的其他事项。\n劳动合同除前款规定的必备条款外，用人单位与劳动者可以约定试用期、培训、保守秘密、补充保险和福利待遇等其他事项。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1295,'中华人民共和国劳动合同法','第十八条',18,'劳动合同','第二章 劳动合同的订立','劳动合同对劳动报酬和劳动条件等标准约定不明确，引发争议的，用人单位与劳动者可以重新协商；协商不成的，适用集体合同规定；没有集体合同或者集体合同未规定劳动报酬的，实行同工同酬；没有集体合同或者集体合同未规定劳动条件等标准的，适用国家有关规定。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1298,'中华人民共和国劳动合同法','第二十一条',21,'劳动合同','第二章 劳动合同的订立','在试用期中，除劳动者有本法第三十九条和第四十条第一项、第二项规定的情形外，用人单位不得解除劳动合同。用人单位在试用期解除劳动合同的，应当向劳动者说明理由。','第二十一条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1299,'中华人民共和国劳动合同法','第二十二条',22,'劳动合同','第二章 劳动合同的订立','用人单位为劳动者提供专项培训费用，对其进行专业技术培训的，可以与该劳动者订立协议，约定服务期。\n劳动者违反服务期约定的，应当按照约定向用人单位支付违约金。违约金的数额不得超过用人单位提供的培训费用。用人单位要求劳动者支付的违约金不得超过服务期尚未履行部分所应分摊的培训费用。\n用人单位与劳动者约定服务期的，不影响按照正常的工资调整机制提高劳动者在服务期期间的劳动报酬。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1301,'中华人民共和国劳动合同法','第二十四条',24,'劳动合同','第二章 劳动合同的订立','竞业限制的人员限于用人单位的高级管理人员、高级技术人员和其他负有保密义务的人员。竞业限制的范围、地域、期限由用人单位与劳动者约定，竞业限制的约定不得违反法律、法规的规定。\n在解除或者终止劳动合同后，前款规定的人员到与本单位生产或者经营同类产品、从事同类业务的有竞争关系的其他用人单位，或者自己开业生产或者经营同类产品、从事同类业务的竞业限制期限，不得超过二年。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1302,'中华人民共和国劳动合同法','第二十五条',25,'劳动合同','第二章 劳动合同的订立','除本法第二十二条和第二十三条规定的情形外，用人单位不得与劳动者约定由劳动者承担违约金。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1303,'中华人民共和国劳动合同法','第二十六条',26,'劳动合同','第二章 劳动合同的订立','下列劳动合同无效或者部分无效：\n（一）以欺诈、胁迫的手段或者乘人之危，使对方在违背真实意思的情况下订立或者变更劳动合同的；\n（二）用人单位免除自己的法定责任、排除劳动者权利的；\n（三）违反法律、行政法规强制性规定的。\n对劳动合同的无效或者部分无效有争议的，由劳动争议仲裁机构或者人民法院确认。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1304,'中华人民共和国劳动合同法','第二十七条',27,'劳动合同','第二章 劳动合同的订立','劳动合同部分无效，不影响其他部分效力的，其他部分仍然有效。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1305,'中华人民共和国劳动合同法','第二十八条',28,'劳动合同','第二章 劳动合同的订立','劳动合同被确认无效，劳动者已付出劳动的，用人单位应当向劳动者支付劳动报酬。劳动报酬的数额，参照本单位相同或者相近岗位劳动者的劳动报酬确定。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1306,'中华人民共和国劳动合同法','第二十九条',29,'劳动合同','第三章 劳动合同的履行和变更','用人单位与劳动者应当按照劳动合同的约定，全面履行各自的义务。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1307,'中华人民共和国劳动合同法','第三十条',30,'劳动合同','第三章 劳动合同的履行和变更','用人单位应当按照劳动合同约定和国家规定，向劳动者及时足额支付劳动报酬。\n用人单位拖欠或者未足额支付劳动报酬的，劳动者可以依法向当地人民法院申请支付令，人民法院应当依法发出支付令。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1308,'中华人民共和国劳动合同法','第三十一条',31,'劳动合同','第三章 劳动合同的履行和变更','用人单位应当严格执行劳动定额标准，不得强迫或者变相强迫劳动者加班。用人单位安排加班的，应当按照国家有关规定向劳动者支付加班费。','第三十一条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1309,'中华人民共和国劳动合同法','第三十二条',32,'劳动合同','第三章 劳动合同的履行和变更','劳动者拒绝用人单位管理人员违章指挥、强令冒险作业的，不视为违反劳动合同。\n劳动者对危害生命安全和身体健康的劳动条件，有权对用人单位提出批评、检举和控告。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1310,'中华人民共和国劳动合同法','第三十三条',33,'劳动合同','第三章 劳动合同的履行和变更','用人单位变更名称、法定代表人、主要负责人或者投资人等事项，不影响劳动合同的履行。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1311,'中华人民共和国劳动合同法','第三十四条',34,'劳动合同','第三章 劳动合同的履行和变更','用人单位发生合并或者分立等情况，原劳动合同继续有效，劳动合同由承继其权利和义务的用人单位继续履行。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1312,'中华人民共和国劳动合同法','第三十五条',35,'劳动合同','第三章 劳动合同的履行和变更','用人单位与劳动者协商一致，可以变更劳动合同约定的内容。变更劳动合同，应当采用书面形式。\n变更后的劳动合同文本由用人单位和劳动者各执一份。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1313,'中华人民共和国劳动合同法','第三十六条',36,'劳动合同','第四章 劳动合同的解除和终止','用人单位与劳动者协商一致，可以解除劳动合同。','第三十六条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1317,'中华人民共和国劳动合同法','第四十条',40,'劳动合同','第四章 劳动合同的解除和终止','有下列情形之一的，用人单位提前三十日以书面形式通知劳动者本人或者额外支付劳动者一个月工资后，可以解除劳动合同：\n（一）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的；\n（二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的；\n（三）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的。','第四十条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1318,'中华人民共和国劳动合同法','第四十一条',41,'劳动合同','第四章 劳动合同的解除和终止','有下列情形之一，需要裁减人员二十人以上或者裁减不足二十人但占企业职工总数百分之十以上的，用人单位提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见后，裁减人员方案经向劳动行政部门报告，可以裁减人员：\n（一）依照企业破产法规定进行重整的；\n（二）生产经营发生严重困难的；\n（三）企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的；\n（四）其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。\n裁减人员时，应当优先留用下列人员：\n（一）与本单位订立较长期限的固定期限劳动合同的；\n（二）与本单位订立无固定期限劳动合同的；\n（三）家庭无其他就业人员，有需要扶养的老人或者未成年人的。\n用人单位依照本条第一款规定裁减人员，在六个月内重新招用人员的，应当通知被裁减的人员，并在同等条件下优先招用被裁减的人员。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1319,'中华人民共和国劳动合同法','第四十二条',42,'劳动合同','第四章 劳动合同的解除和终止','劳动者有下列情形之一的，用人单位不得依照本法第四十条、第四十一条的规定解除劳动合同：\n（一）从事接触职业病危害作业的劳动者未进行离岗前职业健康检查，或者疑似职业病病人在诊断或者医学观察期间的；\n（二）在本单位患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的；\n（三）患病或者非因工负伤，在规定的医疗期内的；\n（四）女职工在孕期、产期、哺乳期的；\n（五）在本单位连续工作满十五年，且距法定退休年龄不足五年的；\n（六）法律、行政法规规定的其他情形。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1320,'中华人民共和国劳动合同法','第四十三条',43,'劳动合同','第四章 劳动合同的解除和终止','用人单位单方解除劳动合同，应当事先将理由通知工会。用人单位违反法律、行政法规规定或者劳动合同约定的，工会有权要求用人单位纠正。用人单位应当研究工会的意见，并将处理结果书面通知工会。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1321,'中华人民共和国劳动合同法','第四十四条',44,'劳动合同','第四章 劳动合同的解除和终止','有下列情形之一的，劳动合同终止：\n（一）劳动合同期满的；\n（二）劳动者开始依法享受基本养老保险待遇的；\n（三）劳动者死亡，或者被人民法院宣告死亡或者宣告失踪的；\n（四）用人单位被依法宣告破产的；\n（五）用人单位被吊销营业执照、责令关闭、撤销或者用人单位决定提前解散的；\n（六）法律、行政法规规定的其他情形。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1322,'中华人民共和国劳动合同法','第四十五条',45,'劳动合同','第四章 劳动合同的解除和终止','劳动合同期满，有本法第四十二条规定情形之一的，劳动合同应当续延至相应的情形消失时终止。但是，本法第四十二条第二项规定丧失或者部分丧失劳动能力劳动者的劳动合同的终止，按照国家有关工伤保险的规定执行。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1323,'中华人民共和国劳动合同法','第四十六条',46,'劳动合同','第四章 劳动合同的解除和终止','有下列情形之一的，用人单位应当向劳动者支付经济补偿：\n（一）劳动者依照本法第三十八条规定解除劳动合同的；\n（二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的；\n（三）用人单位依照本法第四十条规定解除劳动合同的；\n（四）用人单位依照本法第四十一条第一款规定解除劳动合同的；\n（五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的；\n（六）依照本法第四十四条第四项、第五项规定终止劳动合同的；\n（七）法律、行政法规规定的其他情形。','第四十六条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1325,'中华人民共和国劳动合同法','第四十八条',48,'劳动合同','第四章 劳动合同的解除和终止','用人单位违反本法规定解除或者终止劳动合同，劳动者要求继续履行劳动合同的，用人单位应当继续履行；劳动者不要求继续履行劳动合同或者劳动合同已经不能继续履行的，用人单位应当依照本法第八十七条规定支付赔偿金。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1326,'中华人民共和国劳动合同法','第四十九条',49,'劳动合同','第四章 劳动合同的解除和终止','国家采取措施，建立健全劳动者社会保险关系跨地区转移接续制度。','第四十九条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1327,'中华人民共和国劳动合同法','第五十条',50,'劳动合同','第四章 劳动合同的解除和终止','用人单位应当在解除或者终止劳动合同时出具解除或者终止劳动合同的证明，并在十五日内为劳动者办理档案和社会保险关系转移手续。\n劳动者应当按照双方约定，办理工作交接。用人单位依照本法有关规定应当向劳动者支付经济补偿的，在办结工作交接时支付。\n用人单位对已经解除或者终止的劳动合同的文本，至少保存二年备查。','第五十条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1328,'中华人民共和国劳动合同法','第五十一条',51,'劳动合同','第一节 集体合同','企业职工一方与用人单位通过平等协商，可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项订立集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。\n集体合同由工会代表企业职工一方与用人单位订立；尚未建立工会的用人单位，由上级工会指导劳动者推举的代表与用人单位订立。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1329,'中华人民共和国劳动合同法','第五十二条',52,'劳动合同','第一节 集体合同','企业职工一方与用人单位可以订立劳动安全卫生、女职工权益保护、工资调整机制等专项集体合同。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1330,'中华人民共和国劳动合同法','第五十三条',53,'劳动合同','第一节 集体合同','在县级以下区域内，建筑业、采矿业、餐饮服务业等行业可以由工会与企业方面代表订立行业性集体合同，或者订立区域性集体合同。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1331,'中华人民共和国劳动合同法','第五十四条',54,'劳动合同','第一节 集体合同','集体合同订立后，应当报送劳动行政部门；劳动行政部门自收到集体合同文本之日起十五日内未提出异议的，集体合同即行生效。\n依法订立的集体合同对用人单位和劳动者具有约束力。行业性、区域性集体合同对当地本行业、本区域的用人单位和劳动者具有约束力。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1332,'中华人民共和国劳动合同法','第五十五条',55,'劳动合同','第一节 集体合同','集体合同中劳动报酬和劳动条件等标准不得低于当地人民政府规定的最低标准；用人单位与劳动者订立的劳动合同中劳动报酬和劳动条件等标准不得低于集体合同规定的标准。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1333,'中华人民共和国劳动合同法','第五十六条',56,'劳动合同','第一节 集体合同','用人单位违反集体合同，侵犯职工劳动权益的，工会可以依法要求用人单位承担责任；因履行集体合同发生争议，经协商解决不成的，工会可以依法申请仲裁、提起诉讼。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1334,'中华人民共和国劳动合同法','第五十七条',57,'劳动合同','第二节 劳务派遣','经营劳务派遣业务应当具备下列条件：\n（一）注册资本不得少于人民币二百万元；\n（二）有与开展业务相适应的固定的经营场所和设施；\n（三）有符合法律、行政法规规定的劳务派遣管理制度；\n（四）法律、行政法规规定的其他条件。\n经营劳务派遣业务，应当向劳动行政部门依法申请行政许可；经许可的，依法办理相应的公司登记。未经许可，任何单位和个人不得经营劳务派遣业务。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1335,'中华人民共和国劳动合同法','第五十八条',58,'劳动合同','第二节 劳务派遣','劳务派遣单位是本法所称用人单位，应当履行用人单位对劳动者的义务。劳务派遣单位与被派遣劳动者订立的劳动合同，除应当载明本法第十七条规定的事项外，还应当载明被派遣劳动者的用工单位以及派遣期限、工作岗位等情况。\n劳务派遣单位应当与被派遣劳动者订立二年以上的固定期限劳动合同，按月支付劳动报酬；被派遣劳动者在无工作期间，劳务派遣单位应当按照所在地人民政府规定的最低工资标准，向其按月支付报酬。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1336,'中华人民共和国劳动合同法','第五十九条',59,'劳动合同','第二节 劳务派遣','劳务派遣单位派遣劳动者应当与接受以劳务派遣形式用工的单位（以下称用工单位）订立劳务派遣协议。劳务派遣协议应当约定派遣岗位和人员数量、派遣期限、劳动报酬和社会保险费的数额与支付方式以及违反协议的责任。\n用工单位应当根据工作岗位的实际需要与劳务派遣单位确定派遣期限，不得将连续用工期限分割订立数个短期劳务派遣协议。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1337,'中华人民共和国劳动合同法','第六十条',60,'劳动合同','第二节 劳务派遣','劳务派遣单位应当将劳务派遣协议的内容告知被派遣劳动者。\n劳务派遣单位不得克扣用工单位按照劳务派遣协议支付给被派遣劳动者的劳动报酬。\n劳务派遣单位和用工单位不得向被派遣劳动者收取费用。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1338,'中华人民共和国劳动合同法','第六十一条',61,'劳动合同','第二节 劳务派遣','劳务派遣单位跨地区派遣劳动者的，被派遣劳动者享有的劳动报酬和劳动条件，按照用工单位所在地的标准执行。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1339,'中华人民共和国劳动合同法','第六十二条',62,'劳动合同','第二节 劳务派遣','用工单位应当履行下列义务：\n（一）执行国家劳动标准，提供相应的劳动条件和劳动保护；\n（二）告知被派遣劳动者的工作要求和劳动报酬；\n（三）支付加班费、绩效奖金，提供与工作岗位相关的福利待遇；\n（四）对在岗被派遣劳动者进行工作岗位所必需的培训；\n（五）连续用工的，实行正常的工资调整机制。\n用工单位不得将被派遣劳动者再派遣到其他用人单位。','第六十二条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1340,'中华人民共和国劳动合同法','第六十三条',63,'劳动合同','第二节 劳务派遣','被派遣劳动者享有与用工单位的劳动者同工同酬的权利。用工单位应当按照同工同酬原则，对被派遣劳动者与本单位同类岗位的劳动者实行相同的劳动报酬分配办法。用工单位无同类岗位劳动者的，参照用工单位所在地相同或者相近岗位劳动者的劳动报酬确定。\n劳务派遣单位与被派遣劳动者订立的劳动合同和与用工单位订立的劳务派遣协议，载明或者约定的向被派遣劳动者支付的劳动报酬应当符合前款规定。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1341,'中华人民共和国劳动合同法','第六十四条',64,'劳动合同','第二节 劳务派遣','被派遣劳动者有权在劳务派遣单位或者用工单位依法参加或者组织工会，维护自身的合法权益。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1342,'中华人民共和国劳动合同法','第六十五条',65,'劳动合同','第二节 劳务派遣','被派遣劳动者可以依照本法第三十六条、第三十八条的规定与劳务派遣单位解除劳动合同。\n被派遣劳动者有本法第三十九条和第四十条第一项、第二项规定情形的，用工单位可以将劳动者退回劳务派遣单位，劳务派遣单位依照本法有关规定，可以与劳动者解除劳动合同。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1343,'中华人民共和国劳动合同法','第六十六条',66,'劳动合同','第二节 劳务派遣','劳动合同用工是我国的企业基本用工形式。劳务派遣用工是补充形式，只能在临时性、辅助性或者替代性的工作岗位上实施。\n前款规定的临时性工作岗位是指存续时间不超过六个月的岗位；辅助性工作岗位是指为主营业务岗位提供服务的非主营业务岗位；替代性工作岗位是指用工单位的劳动者因脱产学习、休假等原因无法工作的一定期间内，可以由其他劳动者替代工作的岗位。\n用工单位应当严格控制劳务派遣用工数量，不得超过其用工总量的一定比例，具体比例由国务院劳动行政部门规定。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1344,'中华人民共和国劳动合同法','第六十七条',67,'劳动合同','第二节 劳务派遣','用人单位不得设立劳务派遣单位向本单位或者所属单位派遣劳动者。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1345,'中华人民共和国劳动合同法','第六十八条',68,'劳动合同','第三节 非全日制用工','非全日制用工，是指以小时计酬为主，劳动者在同一用人单位一般平均每日工作时间不超过四小时，每周工作时间累计不超过二十四小时的用工形式。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1346,'中华人民共和国劳动合同法','第六十九条',69,'劳动合同','第三节 非全日制用工','非全日制用工双方当事人可以订立口头协议。\n从事非全日制用工的劳动者可以与一个或者一个以上用人单位订立劳动合同；但是，后订立的劳动合同不得影响先订立的劳动合同的履行。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1347,'中华人民共和国劳动合同法','第七十条',70,'劳动合同','第三节 非全日制用工','非全日制用工双方当事人不得约定试用期。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1348,'中华人民共和国劳动合同法','第七十一条',71,'劳动合同','第三节 非全日制用工','非全日制用工双方当事人任何一方都可以随时通知对方终止用工。终止用工，用人单位不向劳动者支付经济补偿。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1349,'中华人民共和国劳动合同法','第七十二条',72,'劳动合同','第三节 非全日制用工','非全日制用工小时计酬标准不得低于用人单位所在地人民政府规定的最低小时工资标准。\n非全日制用工劳动报酬结算支付周期最长不得超过十五日。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1350,'中华人民共和国劳动合同法','第七十三条',73,'劳动合同','第六章 监督检查','国务院劳动行政部门负责全国劳动合同制度实施的监督管理。\n县级以上地方人民政府劳动行政部门负责本行政区域内劳动合同制度实施的监督管理。\n县级以上各级人民政府劳动行政部门在劳动合同制度实施的监督管理工作中，应当听取工会、企业方面代表以及有关行业主管部门的意见。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1351,'中华人民共和国劳动合同法','第七十四条',74,'劳动合同','第六章 监督检查','县级以上地方人民政府劳动行政部门依法对下列实施劳动合同制度的情况进行监督检查：\n（一）用人单位制定直接涉及劳动者切身利益的规章制度及其执行的情况；\n（二）用人单位与劳动者订立和解除劳动合同的情况；\n（三）劳务派遣单位和用工单位遵守劳务派遣有关规定的情况；\n（四）用人单位遵守国家关于劳动者工作时间和休息休假规定的情况；\n（五）用人单位支付劳动合同约定的劳动报酬和执行最低工资标准的情况；\n（六）用人单位参加各项社会保险和缴纳社会保险费的情况；\n（七）法律、法规规定的其他劳动监察事项。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1352,'中华人民共和国劳动合同法','第七十五条',75,'劳动合同','第六章 监督检查','县级以上地方人民政府劳动行政部门实施监督检查时，有权查阅与劳动合同、集体合同有关的材料，有权对劳动场所进行实地检查，用人单位和劳动者都应当如实提供有关情况和材料。\n劳动行政部门的工作人员进行监督检查，应当出示证件，依法行使职权，文明执法。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1353,'中华人民共和国劳动合同法','第七十六条',76,'劳动合同','第六章 监督检查','县级以上人民政府建设、卫生、安全生产监督管理等有关主管部门在各自职责范围内，对用人单位执行劳动合同制度的情况进行监督管理。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1354,'中华人民共和国劳动合同法','第七十七条',77,'劳动合同','第六章 监督检查','劳动者合法权益受到侵害的，有权要求有关部门依法处理，或者依法申请仲裁、提起诉讼。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1355,'中华人民共和国劳动合同法','第七十八条',78,'劳动合同','第六章 监督检查','工会依法维护劳动者的合法权益，对用人单位履行劳动合同、集体合同的情况进行监督。用人单位违反劳动法律、法规和劳动合同、集体合同的，工会有权提出意见或者要求纠正；劳动者申请仲裁、提起诉讼的，工会依法给予支持和帮助。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1356,'中华人民共和国劳动合同法','第七十九条',79,'劳动合同','第六章 监督检查','任何组织或者个人对违反本法的行为都有权举报，县级以上人民政府劳动行政部门应当及时核实、处理，并对举报有功人员给予奖励。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1357,'中华人民共和国劳动合同法','第八十条',80,'劳动合同','第七章 法律责任','用人单位直接涉及劳动者切身利益的规章制度违反法律、法规规定的，由劳动行政部门责令改正，给予警告；给劳动者造成损害的，应当承担赔偿责任。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1358,'中华人民共和国劳动合同法','第八十一条',81,'劳动合同','第七章 法律责任','用人单位提供的劳动合同文本未载明本法规定的劳动合同必备条款或者用人单位未将劳动合同文本交付劳动者的，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1360,'中华人民共和国劳动合同法','第八十三条',83,'劳动合同','第七章 法律责任','用人单位违反本法规定与劳动者约定试用期的，由劳动行政部门责令改正；违法约定的试用期已经履行的，由用人单位以劳动者试用期满月工资为标准，按已经履行的超过法定试用期的期间向劳动者支付赔偿金。','第八十三条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1361,'中华人民共和国劳动合同法','第八十四条',84,'劳动合同','第七章 法律责任','用人单位违反本法规定，扣押劳动者居民身份证等证件的，由劳动行政部门责令限期退还劳动者本人，并依照有关法律规定给予处罚。\n用人单位违反本法规定，以担保或者其他名义向劳动者收取财物的，由劳动行政部门责令限期退还劳动者本人，并以每人五百元以上二千元以下的标准处以罚款；给劳动者造成损害的，应当承担赔偿责任。\n劳动者依法解除或者终止劳动合同，用人单位扣押劳动者档案或者其他物品的，依照前款规定处罚。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1362,'中华人民共和国劳动合同法','第八十五条',85,'劳动合同','第七章 法律责任','用人单位有下列情形之一的，由劳动行政部门责令限期支付劳动报酬、加班费或者经济补偿；劳动报酬低于当地最低工资标准的，应当支付其差额部分；逾期不支付的，责令用人单位按应付金额百分之五十以上百分之一百以下的标准向劳动者加付赔偿金：\n（一）未按照劳动合同的约定或者国家规定及时足额支付劳动者劳动报酬的；\n（二）低于当地最低工资标准支付劳动者工资的；\n（三）安排加班不支付加班费的；\n（四）解除或者终止劳动合同，未依照本法规定向劳动者支付经济补偿的。','第八十五条','2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1363,'中华人民共和国劳动合同法','第八十六条',86,'劳动合同','第七章 法律责任','劳动合同依照本法第二十六条规定被确认无效，给对方造成损害的，有过错的一方应当承担赔偿责任。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1365,'中华人民共和国劳动合同法','第八十八条',88,'劳动合同','第七章 法律责任','用人单位有下列情形之一的，依法给予行政处罚；构成犯罪的，依法追究刑事责任；给劳动者造成损害的，应当承担赔偿责任：\n（一）以暴力、威胁或者非法限制人身自由的手段强迫劳动的；\n（二）违章指挥或者强令冒险作业危及劳动者人身安全的；\n（三）侮辱、体罚、殴打、非法搜查或者拘禁劳动者的；\n（四）劳动条件恶劣、环境污染严重，给劳动者身心健康造成严重损害的。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1366,'中华人民共和国劳动合同法','第八十九条',89,'劳动合同','第七章 法律责任','用人单位违反本法规定未向劳动者出具解除或者终止劳动合同的书面证明，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1367,'中华人民共和国劳动合同法','第九十条',90,'劳动合同','第七章 法律责任','劳动者违反本法规定解除劳动合同，或者违反劳动合同中约定的保密义务或者竞业限制，给用人单位造成损失的，应当承担赔偿责任。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1368,'中华人民共和国劳动合同法','第九十一条',91,'劳动合同','第七章 法律责任','用人单位招用与其他用人单位尚未解除或者终止劳动合同的劳动者，给其他用人单位造成损失的，应当承担连带赔偿责任。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1369,'中华人民共和国劳动合同法','第九十二条',92,'劳动合同','第七章 法律责任','违反本法规定，未经许可，擅自经营劳务派遣业务的，由劳动行政部门责令停止违法行为，没收违法所得，并处违法所得一倍以上五倍以下的罚款；没有违法所得的，可以处五万元以下的罚款。\n劳务派遣单位、用工单位违反本法有关劳务派遣规定的，由劳动行政部门责令限期改正；逾期不改正的，以每人五千元以上一万元以下的标准处以罚款，对劳务派遣单位，吊销其劳务派遣业务经营许可证。用工单位给被派遣劳动者造成损害的，劳务派遣单位与用工单位承担连带赔偿责任。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1370,'中华人民共和国劳动合同法','第九十三条',93,'劳动合同','第七章 法律责任','对不具备合法经营资格的用人单位的违法犯罪行为，依法追究法律责任；劳动者已经付出劳动的，该单位或者其出资人应当依照本法有关规定向劳动者支付劳动报酬、经济补偿、赔偿金；给劳动者造成损害的，应当承担赔偿责任。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1371,'中华人民共和国劳动合同法','第九十四条',94,'劳动合同','第七章 法律责任','个人承包经营违反本法规定招用劳动者，给劳动者造成损害的，发包的组织与个人承包经营者承担连带赔偿责任。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1372,'中华人民共和国劳动合同法','第九十五条',95,'劳动合同','第七章 法律责任','劳动行政部门和其他有关主管部门及其工作人员玩忽职守、不履行法定职责，或者违法行使职权，给劳动者或者用人单位造成损害的，应当承担赔偿责任；对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1373,'中华人民共和国劳动合同法','第九十六条',96,'劳动合同','第八章 附 则','事业单位与实行聘用制的工作人员订立、履行、变更、解除或者终止劳动合同，法律、行政法规或者国务院另有规定的，依照其规定；未作规定的，依照本法有关规定执行。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1374,'中华人民共和国劳动合同法','第九十七条',97,'劳动合同','第八章 附 则','本法施行前已依法订立且在本法施行之日存续的劳动合同，继续履行；本法第十四条第二款第三项规定连续订立固定期限劳动合同的次数，自本法施行后续订固定期限劳动合同时开始计算。\n本法施行前已建立劳动关系，尚未订立书面劳动合同的，应当自本法施行之日起一个月内订立。\n本法施行之日存续的劳动合同在本法施行后解除或者终止，依照本法第四十六条规定应当支付经济补偿的，经济补偿年限自本法施行之日起计算；本法施行前按照当时有关规定，用人单位应当向劳动者支付经济补偿的，按照当时有关规定执行。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (1375,'中华人民共和国劳动合同法','第九十八条',98,'劳动合同','第八章 附 则','本法自2008年1月1日起施行。',NULL,'2013-07-01','flk_npc','2c909fdd678bf17901678bf74d7106b3','2026-09-16 20:45:27','2026-09-17 16:49:48');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2917,'中华人民共和国劳动合同法实施条例','第四条',4,'劳动合同','第二章 劳动合同的订立','劳动合同法规定的用人单位设立的分支机构，依法取得营业执照或者登记证书的，可以作为用人单位与劳动者订立劳动合同；未依法取得营业执照或者登记证书的，受用人单位委托可以与劳动者订立劳动合同。','第四条',NULL,'flk_npc','ff8080816f3cbb3c016f40927caf049c','2026-09-16 21:13:28','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2918,'中华人民共和国劳动合同法实施条例','第六条',6,'劳动合同','第二章 劳动合同的订立','用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并与劳动者补订书面劳动合同；劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，并依照劳动合同法第四十七条的规定支付经济补偿。\n前款规定的用人单位向劳动者每月支付两倍工资的起算时间为用工之日起满一个月的次日，截止时间为补订书面劳动合同的前一日。','第六条',NULL,'flk_npc','ff8080816f3cbb3c016f40927caf049c','2026-09-16 21:13:28','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2920,'中华人民共和国劳动合同法实施条例','第十三条',13,'劳动合同','第二章 劳动合同的订立','用人单位与劳动者不得在劳动合同法第四十四条规定的劳动合同终止情形之外约定其他的劳动合同终止条件。','第十三条',NULL,'flk_npc','ff8080816f3cbb3c016f40927caf049c','2026-09-16 21:13:28','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2922,'中华人民共和国劳动合同法实施条例','第十八条',18,'劳动合同','第三章 劳动合同的解除和终止','有下列情形之一的，依照劳动合同法规定的条件、程序，劳动者可以与用人单位解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同：\n(一)劳动者与用人单位协商一致的；\n(二)劳动者提前30日以书面形式通知用人单位的；\n(三)劳动者在试用期内提前3日通知用人单位的；\n(四)用人单位未按照劳动合同约定提供劳动保护或者劳动条件的；\n(五)用人单位未及时足额支付劳动报酬的；\n(六)用人单位未依法为劳动者缴纳社会保险费的；\n(七)用人单位的规章制度违反法律、法规的规定，损害劳动者权益的；\n(八)用人单位以欺诈、胁迫的手段或者乘人之危，使劳动者在违背真实意思的情况下订立或者变更劳动合同的；\n(九)用人单位在劳动合同中免除自己的法定责任、排除劳动者权利的；\n(十)用人单位违反法律、行政法规强制性规定的；\n(十一)用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的；\n(十二)用人单位违章指挥、强令冒险作业危及劳动者人身安全的；\n(十三)法律、行政法规规定劳动者可以解除劳动合同的其他情形。','第十八条',NULL,'flk_npc','ff8080816f3cbb3c016f40927caf049c','2026-09-16 21:13:28','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2923,'中华人民共和国劳动合同法实施条例','第二十四条',24,'劳动合同','第三章 劳动合同的解除和终止','用人单位出具的解除、终止劳动合同的证明，应当写明劳动合同期限、解除或者终止劳动合同的日期、工作岗位、在本单位的工作年限。','第二十四条',NULL,'flk_npc','ff8080816f3cbb3c016f40927caf049c','2026-09-16 21:13:28','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2924,'中华人民共和国劳动合同法实施条例','第三十一条',31,'劳动合同','第四章 劳务派遣特别规定','劳务派遣单位或者被派遣劳动者依法解除、终止劳动合同的经济补偿，依照劳动合同法第四十六条、第四十七条的规定执行。','第三十一条',NULL,'flk_npc','ff8080816f3cbb3c016f40927caf049c','2026-09-16 21:13:28','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2927,'中华人民共和国劳动合同法实施条例','第三十二条',32,'劳动合同','第四章 劳务派遣特别规定','劳务派遣单位违法解除或者终止被派遣劳动者的劳动合同的，依照劳动合同法第四十八条的规定执行。','第三十二条',NULL,'flk_npc','ff8080816f3cbb3c016f40927caf049c','2026-09-16 21:13:28','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2929,'中华人民共和国劳动合同法实施条例','第十四条',14,'劳动合同','第二章 劳动合同的订立','劳动合同履行地与用人单位注册地不一致的，有关劳动者的最低工资标准、劳动保护、劳动条件、职业危害防护和本地区上年度职工月平均工资标准等事项，按照劳动合同履行地的有关规定执行；用人单位注册地的有关标准高于劳动合同履行地的有关标准，且用人单位与劳动者约定按照用人单位注册地的有关规定执行的，从其约定。','第十四条',NULL,'flk_npc','ff8080816f3cbb3c016f40927caf049c','2026-09-16 21:13:28','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2930,'中华人民共和国劳动合同法实施条例','第十五条',15,'劳动合同','第二章 劳动合同的订立','劳动者在试用期的工资不得低于本单位相同岗位最低档工资的80%或者不得低于劳动合同约定工资的80%，并不得低于用人单位所在地的最低工资标准。','第十五条',NULL,'flk_npc','ff8080816f3cbb3c016f40927caf049c','2026-09-16 21:13:28','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2931,'中华人民共和国劳动合同法实施条例','第二十条',20,'劳动合同','第三章 劳动合同的解除和终止','用人单位依照劳动合同法第四十条的规定，选择额外支付劳动者一个月工资解除劳动合同的，其额外支付的工资应当按照该劳动者上一个月的工资标准确定。','第二十条',NULL,'flk_npc','ff8080816f3cbb3c016f40927caf049c','2026-09-16 21:13:28','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2933,'中华人民共和国劳动合同法实施条例','第二十七条',27,'劳动合同','第三章 劳动合同的解除和终止','劳动合同法第四十七条规定的经济补偿的月工资按照劳动者应得工资计算，包括计时工资或者计件工资以及奖金、津贴和补贴等货币性收入。劳动者在劳动合同解除或者终止前12个月的平均工资低于当地最低工资标准的，按照当地最低工资标准计算。劳动者工作不满12个月的，按照实际工作的月数计算平均工资。','第二十七条',NULL,'flk_npc','ff8080816f3cbb3c016f40927caf049c','2026-09-16 21:13:28','2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2944, '职工带薪年休假条例', '第三条', 3, '工作时间与休息休假', NULL, '职工累计工作已满1年不满10年的，年休假5天；已满10年不满20年的，年休假10天；已满20年的，年休假15天。\n国家法定休假日、休息日不计入年休假的假期。', '第三条', NULL, 'flk_npc', 'ff8080816f3e98bd016f420b9b460371', '2026-09-16 21:14:05', '2026-09-17 16:48:54');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2945, '职工带薪年休假条例', '第四条', 4, '工作时间与休息休假', NULL, '职工有下列情形之一的，不享受当年的年休假：\n(一)职工依法享受寒暑假，其休假天数多于年休假天数的；\n(二)职工请事假累计20天以上且单位按照规定不扣工资的；\n(三)累计工作满1年不满10年的职工，请病假累计2个月以上的；\n(四)累计工作满10年不满20年的职工，请病假累计3个月以上的；\n(五)累计工作满20年以上的职工，请病假累计4个月以上的。', '第四条', NULL, 'flk_npc', 'ff8080816f3e98bd016f420b9b460371', '2026-09-16 21:14:05', '2026-09-17 16:48:54');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2946, '职工带薪年休假条例', '第六条', 6, '工作时间与休息休假', NULL, '县级以上地方人民政府人事部门、劳动保障部门应当依据职权对单位执行本条例的情况主动进行监督检查。\n工会组织依法维护职工的年休假权利。', '第六条', NULL, 'flk_npc', 'ff8080816f3e98bd016f420b9b460371', '2026-09-16 21:14:05', '2026-09-17 16:48:54');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2947, '职工带薪年休假条例', '第七条', 7, '工作时间与休息休假', NULL, '单位不安排职工休年休假又不依照本条例规定给予年休假工资报酬的，由县级以上地方人民政府人事部门或者劳动保障部门依据职权责令限期改正；对逾期不改正的，除责令该单位支付年休假工资报酬外，单位还应当按照年休假工资报酬的数额向职工加付赔偿金；对拒不支付年休假工资报酬、赔偿金的，属于公务员和参照公务员法管理的人员所在单位的，对直接负责的主管人员以及其他直接责任人员依法给予处分；属于其他单位的，由劳动保障部门、人事部门或者职工申请人民法院强制执行。', '第七条', NULL, 'flk_npc', 'ff8080816f3e98bd016f420b9b460371', '2026-09-16 21:14:05', '2026-09-17 16:48:54');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2948, '保障农民工工资支付条例', '第二十八条', 28, '劳动报酬', '第四章 工程建设领域特别规定', '施工总承包单位或者分包单位应当依法与所招用的农民工订立劳动合同并进行用工实名登记，具备条件的行业应当通过相应的管理服务信息平台进行用工实名登记、管理。未与施工总承包单位或者分包单位订立劳动合同并进行用工实名登记的人员，不得进入项目现场施工。\n施工总承包单位应当在工程项目部配备劳资专管员，对分包单位劳动用工实施监督管理，掌握施工现场用工、考勤、工资支付等情况，审核分包单位编制的农民工工资支付表，分包单位应当予以配合。\n施工总承包单位、分包单位应当建立用工管理台账，并保存至工程完工且工资全部结清后至少3年。', '第二十八条', '2020-05-01', 'flk_npc', 'ff808081774c7a3d01776c41674315b2', '2026-09-16 21:14:18', '2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2949, '保障农民工工资支付条例', '第三十九条', 39, '劳动报酬', '第五章 监督检查', '人力资源社会保障行政部门、相关行业工程建设主管部门和其他有关部门应当按照职责，加强对用人单位与农民工签订劳动合同、工资支付以及工程建设项目实行农民工实名制管理、农民工工资专用账户管理、施工总承包单位代发工资、工资保证金存储、维权信息公示等情况的监督检查，预防和减少拖欠农民工工资行为的发生。', '第三十九条', '2020-05-01', 'flk_npc', 'ff808081774c7a3d01776c41674315b2', '2026-09-16 21:14:18', '2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2950, '保障农民工工资支付条例', '第五十条', 50, '劳动报酬', '第五章 监督检查', '农民工与用人单位就拖欠工资存在争议，用人单位应当提供依法由其保存的劳动合同、职工名册、工资支付台账和清单等材料；不提供的，依法承担不利后果。', '第五十条', '2020-05-01', 'flk_npc', 'ff808081774c7a3d01776c41674315b2', '2026-09-16 21:14:18', '2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2951, '保障农民工工资支付条例', '第一条', 1, '劳动报酬', '第一章 总则', '为了规范农民工工资支付行为，保障农民工按时足额获得工资，根据《中华人民共和国劳动法》及有关法律规定，制定本条例。', '第一条', '2020-05-01', 'flk_npc', 'ff808081774c7a3d01776c41674315b2', '2026-09-16 21:14:18', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2952, '保障农民工工资支付条例', '第十三条', 13, '劳动报酬', '第二章 工资支付形式与周期', '实行月、周、日、小时工资制的，按照月、周、日、小时为周期支付工资；实行计件工资制的，工资支付周期由双方依法约定。', '第十三条', '2020-05-01', 'flk_npc', 'ff808081774c7a3d01776c41674315b2', '2026-09-16 21:14:18', '2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (2953, '保障农民工工资支付条例', '第十六条', 16, '劳动报酬', '第三章 工资清偿', '用人单位拖欠农民工工资的，应当依法予以清偿。', '第十六条', '2020-05-01', 'flk_npc', 'ff808081774c7a3d01776c41674315b2', '2026-09-16 21:14:18', '2026-09-17 16:48:53');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3627,'中华人民共和国劳动合同法实施条例','第一条',1,'劳动合同','第一章 总则','为了贯彻实施《中华人民共和国劳动合同法》(以下简称劳动合同法)，制定本条例。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3628,'中华人民共和国劳动合同法实施条例','第二条',2,'劳动合同','第一章 总则','各级人民政府和县级以上人民政府劳动行政等有关部门以及工会等组织，应当采取措施，推动劳动合同法的贯彻实施，促进劳动关系的和谐。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3629,'中华人民共和国劳动合同法实施条例','第三条',3,'劳动合同','第一章 总则','依法成立的会计师事务所、律师事务所等合伙组织和基金会，属于劳动合同法规定的用人单位。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3631,'中华人民共和国劳动合同法实施条例','第五条',5,'劳动合同','第二章 劳动合同的订立','自用工之日起一个月内，经用人单位书面通知后，劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，无需向劳动者支付经济补偿，但是应当依法向劳动者支付其实际工作时间的劳动报酬。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3633,'中华人民共和国劳动合同法实施条例','第七条',7,'劳动合同','第二章 劳动合同的订立','用人单位自用工之日起满一年未与劳动者订立书面劳动合同的，自用工之日起满一个月的次日至满一年的前一日应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并视为自用工之日起满一年的当日已经与劳动者订立无固定期限劳动合同，应当立即与劳动者补订书面劳动合同。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3634,'中华人民共和国劳动合同法实施条例','第八条',8,'劳动合同','第二章 劳动合同的订立','劳动合同法第七条规定的职工名册，应当包括劳动者姓名、性别、公民身份号码、户籍地址及现住址、联系方式、用工形式、用工起始时间、劳动合同期限等内容。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3635,'中华人民共和国劳动合同法实施条例','第九条',9,'劳动合同','第二章 劳动合同的订立','劳动合同法第十四条第二款规定的连续工作满10年的起始时间，应当自用人单位用工之日起计算，包括劳动合同法施行前的工作年限。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3636,'中华人民共和国劳动合同法实施条例','第十条',10,'劳动合同','第二章 劳动合同的订立','劳动者非因本人原因从原用人单位被安排到新用人单位工作的，劳动者在原用人单位的工作年限合并计算为新用人单位的工作年限。原用人单位已经向劳动者支付经济补偿的，新用人单位在依法解除、终止劳动合同计算支付经济补偿的工作年限时，不再计算劳动者在原用人单位的工作年限。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3637,'中华人民共和国劳动合同法实施条例','第十一条',11,'劳动合同','第二章 劳动合同的订立','除劳动者与用人单位协商一致的情形外，劳动者依照劳动合同法第十四条第二款的规定，提出订立无固定期限劳动合同的，用人单位应当与其订立无固定期限劳动合同。对劳动合同的内容，双方应当按照合法、公平、平等自愿、协商一致、诚实信用的原则协商确定；对协商不一致的内容，依照劳动合同法第十八条的规定执行。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3638,'中华人民共和国劳动合同法实施条例','第十二条',12,'劳动合同','第二章 劳动合同的订立','地方各级人民政府及县级以上地方人民政府有关部门为安置就业困难人员提供的给予岗位补贴和社会保险补贴的公益性岗位，其劳动合同不适用劳动合同法有关无固定期限劳动合同的规定以及支付经济补偿的规定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3642,'中华人民共和国劳动合同法实施条例','第十六条',16,'劳动合同','第二章 劳动合同的订立','劳动合同法第二十二条第二款规定的培训费用，包括用人单位为了对劳动者进行专业技术培训而支付的有凭证的培训费用、培训期间的差旅费用以及因培训产生的用于该劳动者的其他直接费用。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3643,'中华人民共和国劳动合同法实施条例','第十七条',17,'劳动合同','第二章 劳动合同的订立','劳动合同期满，但是用人单位与劳动者依照劳动合同法第二十二条的规定约定的服务期尚未到期的，劳动合同应当续延至服务期满；双方另有约定的，从其约定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3645,'中华人民共和国劳动合同法实施条例','第十九条',19,'劳动合同','第三章 劳动合同的解除和终止','有下列情形之一的，依照劳动合同法规定的条件、程序，用人单位可以与劳动者解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同：\n(一)用人单位与劳动者协商一致的；\n(二)劳动者在试用期间被证明不符合录用条件的；\n(三)劳动者严重违反用人单位的规章制度的；\n(四)劳动者严重失职，营私舞弊，给用人单位造成重大损害的；\n(五)劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的；\n(六)劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的；\n(七)劳动者被依法追究刑事责任的；\n(八)劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的；\n(九)劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的；\n(十)劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的；\n(十一)用人单位依照企业破产法规定进行重整的；\n(十二)用人单位生产经营发生严重困难的；\n(十三)企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的；\n(十四)其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3647,'中华人民共和国劳动合同法实施条例','第二十一条',21,'劳动合同','第三章 劳动合同的解除和终止','劳动者达到法定退休年龄的，劳动合同终止。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3648,'中华人民共和国劳动合同法实施条例','第二十二条',22,'劳动合同','第三章 劳动合同的解除和终止','以完成一定工作任务为期限的劳动合同因任务完成而终止的，用人单位应当依照劳动合同法第四十七条的规定向劳动者支付经济补偿。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3649,'中华人民共和国劳动合同法实施条例','第二十三条',23,'劳动合同','第三章 劳动合同的解除和终止','用人单位依法终止工伤职工的劳动合同的，除依照劳动合同法第四十七条的规定支付经济补偿外，还应当依照国家有关工伤保险的规定支付一次性工伤医疗补助金和伤残就业补助金。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3651,'中华人民共和国劳动合同法实施条例','第二十五条',25,'劳动合同','第三章 劳动合同的解除和终止','用人单位违反劳动合同法的规定解除或者终止劳动合同，依照劳动合同法第八十七条的规定支付了赔偿金的，不再支付经济补偿。赔偿金的计算年限自用工之日起计算。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3652,'中华人民共和国劳动合同法实施条例','第二十六条',26,'劳动合同','第三章 劳动合同的解除和终止','用人单位与劳动者约定了服务期，劳动者依照劳动合同法第三十八条的规定解除劳动合同的，不属于违反服务期的约定，用人单位不得要求劳动者支付违约金。\n有下列情形之一，用人单位与劳动者解除约定服务期的劳动合同的，劳动者应当按照劳动合同的约定向用人单位支付违约金：\n(一)劳动者严重违反用人单位的规章制度的；\n(二)劳动者严重失职，营私舞弊，给用人单位造成重大损害的；\n(三)劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的；\n(四)劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的；\n(五)劳动者被依法追究刑事责任的。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3654,'中华人民共和国劳动合同法实施条例','第二十八条',28,'劳动合同','第四章 劳务派遣特别规定','用人单位或者其所属单位出资或者合伙设立的劳务派遣单位，向本单位或者所属单位派遣劳动者的，属于劳动合同法第六十七条规定的不得设立的劳务派遣单位。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3655,'中华人民共和国劳动合同法实施条例','第二十九条',29,'劳动合同','第四章 劳务派遣特别规定','用工单位应当履行劳动合同法第六十二条规定的义务，维护被派遣劳动者的合法权益。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3656,'中华人民共和国劳动合同法实施条例','第三十条',30,'劳动合同','第四章 劳务派遣特别规定','劳务派遣单位不得以非全日制用工形式招用被派遣劳动者。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3659,'中华人民共和国劳动合同法实施条例','第三十三条',33,'劳动合同','第五章 法律责任','用人单位违反劳动合同法有关建立职工名册规定的，由劳动行政部门责令限期改正；逾期不改正的，由劳动行政部门处2000元以上2万元以下的罚款。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3660,'中华人民共和国劳动合同法实施条例','第三十四条',34,'劳动合同','第五章 法律责任','用人单位依照劳动合同法的规定应当向劳动者每月支付两倍的工资或者应当向劳动者支付赔偿金而未支付的，劳动行政部门应当责令用人单位支付。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3661,'中华人民共和国劳动合同法实施条例','第三十五条',35,'劳动合同','第五章 法律责任','用工单位违反劳动合同法和本条例有关劳务派遣规定的，由劳动行政部门和其他有关主管部门责令改正；情节严重的，以每位被派遣劳动者1000元以上5000元以下的标准处以罚款；给被派遣劳动者造成损害的，劳务派遣单位和用工单位承担连带赔偿责任。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3662,'中华人民共和国劳动合同法实施条例','第三十六条',36,'劳动合同','第六章 附则','对违反劳动合同法和本条例的行为的投诉、举报，县级以上地方人民政府劳动行政部门依照《劳动保障监察条例》的规定处理。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3663,'中华人民共和国劳动合同法实施条例','第三十七条',37,'劳动合同','第六章 附则','劳动者与用人单位因订立、履行、变更、解除或者终止劳动合同发生争议的，依照《中华人民共和国劳动争议调解仲裁法》的规定处理。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3664,'中华人民共和国劳动合同法实施条例','第三十八条',38,'劳动合同','第六章 附则','本条例自公布之日起施行。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:56','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3998, '保障农民工工资支付条例', '第二条', 2, '劳动报酬', '第一章 总则', '保障农民工工资支付，适用本条例。\n本条例所称农民工，是指为用人单位提供劳动的农村居民。\n本条例所称工资，是指农民工为用人单位提供劳动后应当获得的劳动报酬。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (3999, '保障农民工工资支付条例', '第三条', 3, '劳动报酬', '第一章 总则', '农民工有按时足额获得工资的权利。任何单位和个人不得拖欠农民工工资。\n农民工应当遵守劳动纪律和职业道德，执行劳动安全卫生规程，完成劳动任务。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4000, '保障农民工工资支付条例', '第四条', 4, '劳动报酬', '第一章 总则', '县级以上地方人民政府对本行政区域内保障农民工工资支付工作负责，建立保障农民工工资支付工作协调机制，加强监管能力建设，健全保障农民工工资支付工作目标责任制，并纳入对本级人民政府有关部门和下级人民政府进行考核和监督的内容。\n乡镇人民政府、街道办事处应当加强对拖欠农民工工资矛盾的排查和调处工作，防范和化解矛盾，及时调解纠纷。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4001, '保障农民工工资支付条例', '第五条', 5, '劳动报酬', '第一章 总则', '保障农民工工资支付，应当坚持市场主体负责、政府依法监管、社会协同监督，按照源头治理、预防为主、防治结合、标本兼治的要求，依法根治拖欠农民工工资问题。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4002, '保障农民工工资支付条例', '第六条', 6, '劳动报酬', '第一章 总则', '用人单位实行农民工劳动用工实名制管理，与招用的农民工书面约定或者通过依法制定的规章制度规定工资支付标准、支付时间、支付方式等内容。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4003, '保障农民工工资支付条例', '第七条', 7, '劳动报酬', '第一章 总则', '人力资源社会保障行政部门负责保障农民工工资支付工作的组织协调、管理指导和农民工工资支付情况的监督检查,查处有关拖欠农民工工资案件。\n住房城乡建设、交通运输、水利等相关行业工程建设主管部门按照职责履行行业监管责任，督办因违法发包、转包、违法分包、挂靠、拖欠工程款等导致的拖欠农民工工资案件。\n发展改革等部门按照职责负责政府投资项目的审批管理，依法审查政府投资项目的资金来源和筹措方式，按规定及时安排政府投资，加强社会信用体系建设，组织对拖欠农民工工资失信联合惩戒对象依法依规予以限制和惩戒。\n财政部门负责政府投资资金的预算管理，根据经批准的预算按规定及时足额拨付政府投资资金。\n公安机关负责及时受理、侦办涉嫌拒不支付劳动报酬刑事案件，依法处置因农民工工资拖欠引发的社会治安案件。\n司法行政、自然资源、人民银行、审计、国有资产管理、税务、市场监管、金融监管等部门，按照职责做好与保障农民工工资支付相关的工作。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4004, '保障农民工工资支付条例', '第八条', 8, '劳动报酬', '第一章 总则', '工会、共产主义青年团、妇女联合会、残疾人联合会等组织按照职责依法维护农民工获得工资的权利。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4005, '保障农民工工资支付条例', '第九条', 9, '劳动报酬', '第一章 总则', '新闻媒体应当开展保障农民工工资支付法律法规政策的公益宣传和先进典型的报道，依法加强对拖欠农民工工资违法行为的舆论监督，引导用人单位增强依法用工、按时足额支付工资的法律意识，引导农民工依法维权。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4006, '保障农民工工资支付条例', '第十条', 10, '劳动报酬', '第一章 总则', '被拖欠工资的农民工有权依法投诉，或者申请劳动争议调解仲裁和提起诉讼。\n任何单位和个人对拖欠农民工工资的行为，有权向人力资源社会保障行政部门或者其他有关部门举报。\n人力资源社会保障行政部门和其他有关部门应当公开举报投诉电话、网站等渠道，依法接受对拖欠农民工工资行为的举报、投诉。对于举报、投诉的处理实行首问负责制，属于本部门受理的，应当依法及时处理；不属于本部门受理的，应当及时转送相关部门，相关部门应当依法及时处理，并将处理结果告知举报、投诉人。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4007, '保障农民工工资支付条例', '第十一条', 11, '劳动报酬', '第二章 工资支付形式与周期', '农民工工资应当以货币形式，通过银行转账或者现金支付给农民工本人，不得以实物或者有价证券等其他形式替代。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4008, '保障农民工工资支付条例', '第十二条', 12, '劳动报酬', '第二章 工资支付形式与周期', '用人单位应当按照与农民工书面约定或者依法制定的规章制度规定的工资支付周期和具体支付日期足额支付工资。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4010, '保障农民工工资支付条例', '第十四条', 14, '劳动报酬', '第二章 工资支付形式与周期', '用人单位与农民工书面约定或者依法制定的规章制度规定的具体支付日期，可以在农民工提供劳动的当期或者次期。具体支付日期遇法定节假日或者休息日的，应当在法定节假日或者休息日前支付。\n用人单位因不可抗力未能在支付日期支付工资的，应当在不可抗力消除后及时支付。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4011, '保障农民工工资支付条例', '第十五条', 15, '劳动报酬', '第二章 工资支付形式与周期', '用人单位应当按照工资支付周期编制书面工资支付台账，并至少保存3年。\n书面工资支付台账应当包括用人单位名称，支付周期，支付日期，支付对象姓名、身份证号码、联系方式，工作时间，应发工资项目及数额，代扣、代缴、扣除项目和数额，实发工资数额，银行代发工资凭证或者农民工签字等内容。\n用人单位向农民工支付工资时，应当提供农民工本人的工资清单。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4013, '保障农民工工资支付条例', '第十七条', 17, '劳动报酬', '第三章 工资清偿', '不具备合法经营资格的单位招用农民工，农民工已经付出劳动而未获得工资的，依照有关法律规定执行。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4014, '保障农民工工资支付条例', '第十八条', 18, '劳动报酬', '第三章 工资清偿', '用工单位使用个人、不具备合法经营资格的单位或者未依法取得劳务派遣许可证的单位派遣的农民工，拖欠农民工工资的，由用工单位清偿，并可以依法进行追偿。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4015, '保障农民工工资支付条例', '第十九条', 19, '劳动报酬', '第三章 工资清偿', '用人单位将工作任务发包给个人或者不具备合法经营资格的单位，导致拖欠所招用农民工工资的，依照有关法律规定执行。\n用人单位允许个人、不具备合法经营资格或者未取得相应资质的单位以用人单位的名义对外经营，导致拖欠所招用农民工工资的，由用人单位清偿，并可以依法进行追偿。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4016, '保障农民工工资支付条例', '第二十条', 20, '劳动报酬', '第三章 工资清偿', '合伙企业、个人独资企业、个体经济组织等用人单位拖欠农民工工资的，应当依法予以清偿；不清偿的，由出资人依法清偿。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4017, '保障农民工工资支付条例', '第二十一条', 21, '劳动报酬', '第三章 工资清偿', '用人单位合并或者分立时，应当在实施合并或者分立前依法清偿拖欠的农民工工资；经与农民工书面协商一致的，可以由合并或者分立后承继其权利和义务的用人单位清偿。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4018, '保障农民工工资支付条例', '第二十二条', 22, '劳动报酬', '第三章 工资清偿', '用人单位被依法吊销营业执照或者登记证书、被责令关闭、被撤销或者依法解散的，应当在申请注销登记前依法清偿拖欠的农民工工资。\n未依据前款规定清偿农民工工资的用人单位主要出资人，应当在注册新用人单位前清偿拖欠的农民工工资。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4019, '保障农民工工资支付条例', '第二十三条', 23, '劳动报酬', '第四章 工程建设领域特别规定', '建设单位应当有满足施工所需要的资金安排。没有满足施工所需要的资金安排的，工程建设项目不得开工建设；依法需要办理施工许可证的，相关行业工程建设主管部门不予颁发施工许可证。\n政府投资项目所需资金，应当按照国家有关规定落实到位，不得由施工单位垫资建设。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4020, '保障农民工工资支付条例', '第二十四条', 24, '劳动报酬', '第四章 工程建设领域特别规定', '建设单位应当向施工单位提供工程款支付担保。\n建设单位与施工总承包单位依法订立书面工程施工合同，应当约定工程款计量周期、工程款进度结算办法以及人工费用拨付周期，并按照保障农民工工资按时足额支付的要求约定人工费用。人工费用拨付周期不得超过1个月。\n建设单位与施工总承包单位应当将工程施工合同保存备查。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4021, '保障农民工工资支付条例', '第二十五条', 25, '劳动报酬', '第四章 工程建设领域特别规定', '施工总承包单位与分包单位依法订立书面分包合同，应当约定工程款计量周期、工程款进度结算办法。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4022, '保障农民工工资支付条例', '第二十六条', 26, '劳动报酬', '第四章 工程建设领域特别规定', '施工总承包单位应当按照有关规定开设农民工工资专用账户，专项用于支付该工程建设项目农民工工资。\n开设、使用农民工工资专用账户有关资料应当由施工总承包单位妥善保存备查。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4023, '保障农民工工资支付条例', '第二十七条', 27, '劳动报酬', '第四章 工程建设领域特别规定', '金融机构应当优化农民工工资专用账户开设服务流程，做好农民工工资专用账户的日常管理工作；发现资金未按约定拨付等情况的，及时通知施工总承包单位，由施工总承包单位报告人力资源社会保障行政部门和相关行业工程建设主管部门，并纳入欠薪预警系统。\n工程完工且未拖欠农民工工资的，施工总承包单位公示30日后，可以申请注销农民工工资专用账户，账户内余额归施工总承包单位所有。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4025, '保障农民工工资支付条例', '第二十九条', 29, '劳动报酬', '第四章 工程建设领域特别规定', '建设单位应当按照合同约定及时拨付工程款，并将人工费用及时足额拨付至农民工工资专用账户，加强对施工总承包单位按时足额支付农民工工资的监督。\n因建设单位未按照合同约定及时拨付工程款导致农民工工资拖欠的，建设单位应当以未结清的工程款为限先行垫付被拖欠的农民工工资。\n建设单位应当以项目为单位建立保障农民工工资支付协调机制和工资拖欠预防机制，督促施工总承包单位加强劳动用工管理，妥善处理与农民工工资支付相关的矛盾纠纷。发生农民工集体讨薪事件的，建设单位应当会同施工总承包单位及时处理，并向项目所在地人力资源社会保障行政部门和相关行业工程建设主管部门报告有关情况。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4026, '保障农民工工资支付条例', '第三十条', 30, '劳动报酬', '第四章 工程建设领域特别规定', '分包单位对所招用农民工的实名制管理和工资支付负直接责任。\n施工总承包单位对分包单位劳动用工和工资发放等情况进行监督。\n分包单位拖欠农民工工资的，由施工总承包单位先行清偿，再依法进行追偿。\n工程建设项目转包，拖欠农民工工资的，由施工总承包单位先行清偿，再依法进行追偿。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4027, '保障农民工工资支付条例', '第三十一条', 31, '劳动报酬', '第四章 工程建设领域特别规定', '工程建设领域推行分包单位农民工工资委托施工总承包单位代发制度。\n分包单位应当按月考核农民工工作量并编制工资支付表，经农民工本人签字确认后，与当月工程进度等情况一并交施工总承包单位。\n施工总承包单位根据分包单位编制的工资支付表，通过农民工工资专用账户直接将工资支付到农民工本人的银行账户，并向分包单位提供代发工资凭证。\n用于支付农民工工资的银行账户所绑定的农民工本人社会保障卡或者银行卡，用人单位或者其他人员不得以任何理由扣押或者变相扣押。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4028, '保障农民工工资支付条例', '第三十二条', 32, '劳动报酬', '第四章 工程建设领域特别规定', '施工总承包单位应当按照有关规定存储工资保证金，专项用于支付为所承包工程提供劳动的农民工被拖欠的工资。\n工资保证金实行差异化存储办法，对一定时期内未发生工资拖欠的单位实行减免措施，对发生工资拖欠的单位适当提高存储比例。工资保证金可以用金融机构保函替代。\n工资保证金的存储比例、存储形式、减免措施等具体办法，由国务院人力资源社会保障行政部门会同有关部门制定。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4029, '保障农民工工资支付条例', '第三十三条', 33, '劳动报酬', '第四章 工程建设领域特别规定', '除法律另有规定外，农民工工资专用账户资金和工资保证金不得因支付为本项目提供劳动的农民工工资之外的原因被查封、冻结或者划拨。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4030, '保障农民工工资支付条例', '第三十四条', 34, '劳动报酬', '第四章 工程建设领域特别规定', '施工总承包单位应当在施工现场醒目位置设立维权信息告示牌，明示下列事项：\n（一）建设单位、施工总承包单位及所在项目部、分包单位、相关行业工程建设主管部门、劳资专管员等基本信息；\n（二）当地最低工资标准、工资支付日期等基本信息；\n（三）相关行业工程建设主管部门和劳动保障监察投诉举报电话、劳动争议调解仲裁申请渠道、法律援助申请渠道、公共法律服务热线等信息。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4031, '保障农民工工资支付条例', '第三十五条', 35, '劳动报酬', '第四章 工程建设领域特别规定', '建设单位与施工总承包单位或者承包单位与分包单位因工程数量、质量、造价等产生争议的，建设单位不得因争议不按照本条例第二十四条的规定拨付工程款中的人工费用，施工总承包单位也不得因争议不按照规定代发工资。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4032, '保障农民工工资支付条例', '第三十六条', 36, '劳动报酬', '第四章 工程建设领域特别规定', '建设单位或者施工总承包单位将建设工程发包或者分包给个人或者不具备合法经营资格的单位，导致拖欠农民工工资的，由建设单位或者施工总承包单位清偿。\n施工单位允许其他单位和个人以施工单位的名义对外承揽建设工程，导致拖欠农民工工资的，由施工单位清偿。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4033, '保障农民工工资支付条例', '第三十七条', 37, '劳动报酬', '第四章 工程建设领域特别规定', '工程建设项目违反国土空间规划、工程建设等法律法规，导致拖欠农民工工资的，由建设单位清偿。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4034, '保障农民工工资支付条例', '第三十八条', 38, '劳动报酬', '第五章 监督检查', '县级以上地方人民政府应当建立农民工工资支付监控预警平台,实现人力资源社会保障、发展改革、司法行政、财政、住房城乡建设、交通运输、水利等部门的工程项目审批、资金落实、施工许可、劳动用工、工资支付等信息及时共享。\n人力资源社会保障行政部门根据水电燃气供应、物业管理、信贷、税收等反映企业生产经营相关指标的变化情况，及时监控和预警工资支付隐患并做好防范工作，市场监管、金融监管、税务等部门应当予以配合。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4036, '保障农民工工资支付条例', '第四十条', 40, '劳动报酬', '第五章 监督检查', '人力资源社会保障行政部门在查处拖欠农民工工资案件时，需要依法查询相关单位金融账户和相关当事人拥有房产、车辆等情况的，应当经设区的市级以上地方人民政府人力资源社会保障行政部门负责人批准，有关金融机构和登记部门应当予以配合。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4037, '保障农民工工资支付条例', '第四十一条', 41, '劳动报酬', '第五章 监督检查', '人力资源社会保障行政部门在查处拖欠农民工工资案件时，发生用人单位拒不配合调查、清偿责任主体及相关当事人无法联系等情形的，可以请求公安机关和其他有关部门协助处理。\n人力资源社会保障行政部门发现拖欠农民工工资的违法行为涉嫌构成拒不支付劳动报酬罪的，应当按照有关规定及时移送公安机关审查并作出决定。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4038, '保障农民工工资支付条例', '第四十二条', 42, '劳动报酬', '第五章 监督检查', '人力资源社会保障行政部门作出责令支付被拖欠的农民工工资的决定，相关单位不支付的，可以依法申请人民法院强制执行。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4039, '保障农民工工资支付条例', '第四十三条', 43, '劳动报酬', '第五章 监督检查', '相关行业工程建设主管部门应当依法规范本领域建设市场秩序，对违法发包、转包、违法分包、挂靠等行为进行查处，并对导致拖欠农民工工资的违法行为及时予以制止、纠正。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4040, '保障农民工工资支付条例', '第四十四条', 44, '劳动报酬', '第五章 监督检查', '财政部门、审计机关和相关行业工程建设主管部门按照职责，依法对政府投资项目建设单位按照工程施工合同约定向农民工工资专用账户拨付资金情况进行监督。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4041, '保障农民工工资支付条例', '第四十五条', 45, '劳动报酬', '第五章 监督检查', '司法行政部门和法律援助机构应当将农民工列为法律援助的重点对象，并依法为请求支付工资的农民工提供便捷的法律援助。\n公共法律服务相关机构应当积极参与相关诉讼、咨询、调解等活动，帮助解决拖欠农民工工资问题。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4042, '保障农民工工资支付条例', '第四十六条', 46, '劳动报酬', '第五章 监督检查', '人力资源社会保障行政部门、相关行业工程建设主管部门和其他有关部门应当按照“谁执法谁普法”普法责任制的要求，通过以案释法等多种形式，加大对保障农民工工资支付相关法律法规的普及宣传。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4043, '保障农民工工资支付条例', '第四十七条', 47, '劳动报酬', '第五章 监督检查', '人力资源社会保障行政部门应当建立用人单位及相关责任人劳动保障守法诚信档案，对用人单位开展守法诚信等级评价。\n用人单位有严重拖欠农民工工资违法行为的，由人力资源社会保障行政部门向社会公布，必要时可以通过召开新闻发布会等形式向媒体公开曝光。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4044, '保障农民工工资支付条例', '第四十八条', 48, '劳动报酬', '第五章 监督检查', '用人单位拖欠农民工工资，情节严重或者造成严重不良社会影响的，有关部门应当将该用人单位及其法定代表人或者主要负责人、直接负责的主管人员和其他直接责任人员列入拖欠农民工工资失信联合惩戒对象名单，在政府资金支持、政府采购、招投标、融资贷款、市场准入、税收优惠、评优评先、交通出行等方面依法依规予以限制。\n拖欠农民工工资需要列入失信联合惩戒名单的具体情形，由国务院人力资源社会保障行政部门规定。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4045, '保障农民工工资支付条例', '第四十九条', 49, '劳动报酬', '第五章 监督检查', '建设单位未依法提供工程款支付担保或者政府投资项目拖欠工程款，导致拖欠农民工工资的，县级以上地方人民政府应当限制其新建项目，并记入信用记录，纳入国家信用信息系统进行公示。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4047, '保障农民工工资支付条例', '第五十一条', 51, '劳动报酬', '第五章 监督检查', '工会依法维护农民工工资权益，对用人单位工资支付情况进行监督；发现拖欠农民工工资的，可以要求用人单位改正，拒不改正的，可以请求人力资源社会保障行政部门和其他有关部门依法处理。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4048, '保障农民工工资支付条例', '第五十二条', 52, '劳动报酬', '第五章 监督检查', '单位或者个人编造虚假事实或者采取非法手段讨要农民工工资，或者以拖欠农民工工资为名讨要工程款的，依法予以处理。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4049, '保障农民工工资支付条例', '第五十三条', 53, '劳动报酬', '第六章 法律责任', '违反本条例规定拖欠农民工工资的，依照有关法律规定执行。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4050, '保障农民工工资支付条例', '第五十四条', 54, '劳动报酬', '第六章 法律责任', '有下列情形之一的，由人力资源社会保障行政部门责令限期改正；逾期不改正的，对单位处2万元以上5万元以下的罚款，对法定代表人或者主要负责人、直接负责的主管人员和其他直接责任人员处1万元以上3万元以下的罚款：\n（一）以实物、有价证券等形式代替货币支付农民工工资；\n（二）未编制工资支付台账并依法保存，或者未向农民工提供工资清单；\n（三）扣押或者变相扣押用于支付农民工工资的银行账户所绑定的农民工本人社会保障卡或者银行卡。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4051, '保障农民工工资支付条例', '第五十五条', 55, '劳动报酬', '第六章 法律责任', '有下列情形之一的，由人力资源社会保障行政部门、相关行业工程建设主管部门按照职责责令限期改正；逾期不改正的，责令项目停工，并处5万元以上10万元以下的罚款；情节严重的，给予施工单位限制承接新工程、降低资质等级、吊销资质证书等处罚：\n（一）施工总承包单位未按规定开设或者使用农民工工资专用账户；\n（二）施工总承包单位未按规定存储工资保证金或者未提供金融机构保函；\n（三）施工总承包单位、分包单位未实行劳动用工实名制管理。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4052, '保障农民工工资支付条例', '第五十六条', 56, '劳动报酬', '第六章 法律责任', '有下列情形之一的，由人力资源社会保障行政部门、相关行业工程建设主管部门按照职责责令限期改正；逾期不改正的，处5万元以上10万元以下的罚款：\n（一）分包单位未按月考核农民工工作量、编制工资支付表并经农民工本人签字确认；\n（二）施工总承包单位未对分包单位劳动用工实施监督管理；\n（三）分包单位未配合施工总承包单位对其劳动用工进行监督管理；\n（四）施工总承包单位未实行施工现场维权信息公示制度。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4053, '保障农民工工资支付条例', '第五十七条', 57, '劳动报酬', '第六章 法律责任', '有下列情形之一的，由人力资源社会保障行政部门、相关行业工程建设主管部门按照职责责令限期改正；逾期不改正的，责令项目停工，并处5万元以上10万元以下的罚款：\n（一）建设单位未依法提供工程款支付担保；\n（二）建设单位未按约定及时足额向农民工工资专用账户拨付工程款中的人工费用；\n（三）建设单位或者施工总承包单位拒不提供或者无法提供工程施工合同、农民工工资专用账户有关资料。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4054, '保障农民工工资支付条例', '第五十八条', 58, '劳动报酬', '第六章 法律责任', '不依法配合人力资源社会保障行政部门查询相关单位金融账户的，由金融监管部门责令改正；拒不改正的，处2万元以上5万元以下的罚款。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4055, '保障农民工工资支付条例', '第五十九条', 59, '劳动报酬', '第六章 法律责任', '政府投资项目政府投资资金不到位拖欠农民工工资的，由人力资源社会保障行政部门报本级人民政府批准，责令限期足额拨付所拖欠的资金；逾期不拨付的，由上一级人民政府人力资源社会保障行政部门约谈直接责任部门和相关监管部门负责人，必要时进行通报，约谈地方人民政府负责人。情节严重的，对地方人民政府及其有关部门负责人、直接负责的主管人员和其他直接责任人员依法依规给予处分。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4056, '保障农民工工资支付条例', '第六十条', 60, '劳动报酬', '第六章 法律责任', '政府投资项目建设单位未经批准立项建设、擅自扩大建设规模、擅自增加投资概算、未及时拨付工程款等导致拖欠农民工工资的，除依法承担责任外，由人力资源社会保障行政部门、其他有关部门按照职责约谈建设单位负责人，并作为其业绩考核、薪酬分配、评优评先、职务晋升等的重要依据。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4057, '保障农民工工资支付条例', '第六十一条', 61, '劳动报酬', '第六章 法律责任', '对于建设资金不到位、违法违规开工建设的社会投资工程建设项目拖欠农民工工资的，由人力资源社会保障行政部门、其他有关部门按照职责依法对建设单位进行处罚；对建设单位负责人依法依规给予处分。相关部门工作人员未依法履行职责的，由有关机关依法依规给予处分。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4058, '保障农民工工资支付条例', '第六十二条', 62, '劳动报酬', '第六章 法律责任', '县级以上地方人民政府人力资源社会保障、发展改革、财政、公安等部门和相关行业工程建设主管部门工作人员，在履行农民工工资支付监督管理职责过程中滥用职权、玩忽职守、徇私舞弊的，依法依规给予处分；构成犯罪的，依法追究刑事责任。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4059, '保障农民工工资支付条例', '第六十三条', 63, '劳动报酬', '第七章 附则', '用人单位一时难以支付拖欠的农民工工资或者拖欠农民工工资逃匿的，县级以上地方人民政府可以动用应急周转金，先行垫付用人单位拖欠的农民工部分工资或者基本生活费。对已经垫付的应急周转金，应当依法向拖欠农民工工资的用人单位进行追偿。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4060, '保障农民工工资支付条例', '第六十四条', 64, '劳动报酬', '第七章 附则', '本条例自2020年5月1日起施行。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4061,'失业保险条例','第一条',1,'社会保险','第一章 总则','为了保障失业人员失业期间的基本生活，促进其再就业，制定本条例。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4062,'失业保险条例','第二条',2,'社会保险','第一章 总则','城镇企业事业单位、城镇企业事业单位职工依照本条例的规定，缴纳失业保险费。\n城镇企业事业单位失业人员依照本条例的规定，享受失业保险待遇。\n本条所称城镇企业，是指国有企业、城镇集体企业、外商投资企业、城镇私营企业以及其他城镇企业。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4063,'失业保险条例','第三条',3,'社会保险','第一章 总则','国务院劳动保障行政部门主管全国的失业保险工作。县级以上地方各级人民政府劳动保障行政部门主管本行政区域内的失业保险工作。劳动保障行政部门按照国务院规定设立的经办失业保险业务的社会保险经办机构依照本条例的规定，具体承办失业保险工作。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4065,'失业保险条例','第五条',5,'社会保险','第二章 失业保险基金','失业保险基金由下列各项构成：\n(一)城镇企业事业单位、城镇企业事业单位职工缴纳的失业保险费；\n(二)失业保险基金的利息；\n(三)财政补贴；\n(四)依法纳入失业保险基金的其他资金。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4067,'失业保险条例','第七条',7,'社会保险','第二章 失业保险基金','失业保险基金在直辖市和设区的市实行全市统筹；其他地区的统筹层次由省、自治区人民政府规定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4068,'失业保险条例','第八条',8,'社会保险','第二章 失业保险基金','省、自治区可以建立失业保险调剂金。\n失业保险调剂金以统筹地区依法应当征收的失业保险费为基数，按照省、自治区人民政府规定的比例筹集。\n统筹地区的失业保险基金不敷使用时，由失业保险调剂金调剂、地方财政补贴。\n失业保险调剂金的筹集、调剂使用以及地方财政补贴的具体办法，由省、自治区人民政府规定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4069,'失业保险条例','第九条',9,'社会保险','第二章 失业保险基金','省、自治区、直辖市人民政府根据本行政区域失业人员数量和失业保险基金数额，报经国务院批准，可以适当调整本行政区域失业保险费的费率。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4070,'失业保险条例','第十条',10,'社会保险','第二章 失业保险基金','失业保险基金用于下列支出：\n(一)失业保险金；\n(二)领取失业保险金期间的医疗补助金；\n(三)领取失业保险金期间死亡的失业人员的丧葬补助金和其供养的配偶、直系亲属的抚恤金；\n(四)领取失业保险金期间接受职业培训、职业介绍的补贴，补贴的办法和标准由省、自治区、直辖市人民政府规定；\n(五)国务院规定或者批准的与失业保险有关的其他费用。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4071,'失业保险条例','第十一条',11,'社会保险','第二章 失业保险基金','失业保险基金必须存入财政部门在国有商业银行开设的社会保障基金财政专户，实行收支两条线管理，由财政部门依法进行监督。\n存入银行和按照国家规定购买国债的失业保险基金，分别按照城乡居民同期存款利率和国债利息计息。失业保险基金的利息并入失业保险基金。\n失业保险基金专款专用，不得挪作他用，不得用于平衡财政收支。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4073,'失业保险条例','第十三条',13,'社会保险','第二章 失业保险基金','失业保险基金的财务制度和会计制度按照国家有关规定执行。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4074,'失业保险条例','第十四条',14,'社会保险','第三章 失业保险待遇','具备下列条件的失业人员，可以领取失业保险金：\n(一)按照规定参加失业保险，所在单位和本人已按照规定履行缴费义务满1年的；\n(二)非因本人意愿中断就业的；\n(三)已办理失业登记，并有求职要求的。\n失业人员在领取失业保险金期间，按照规定同时享受其他失业保险待遇。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4075,'失业保险条例','第十五条',15,'社会保险','第三章 失业保险待遇','失业人员在领取失业保险金期间有下列情形之一的，停止领取失业保险金，并同时停止享受其他失业保险待遇：\n(一)重新就业的；\n(二)应征服兵役的；\n(三)移居境外的；\n(四)享受基本养老保险待遇的；\n(五)被判刑收监执行或者被劳动教养的；\n(六)无正当理由，拒不接受当地人民政府指定的部门或者机构介绍的工作的；\n(七)有法律、行政法规规定的其他情形的。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4077,'失业保险条例','第十七条',17,'社会保险','第三章 失业保险待遇','失业人员失业前所在单位和本人按照规定累计缴费时间满1年不足5年的，领取失业保险金的期限最长为12个月；累计缴费时间满5年不足10年的，领取失业保险金的期限最长为18个月；累计缴费时间10年以上的，领取失业保险金的期限最长为24个月。重新就业后，再次失业的，缴费时间重新计算，领取失业保险金的期限可以与前次失业应领取而尚未领取的失业保险金的期限合并计算，但是最长不得超过24个月。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4079,'失业保险条例','第十九条',19,'社会保险','第三章 失业保险待遇','失业人员在领取失业保险金期间患病就医的，可以按照规定向社会保险经办机构申请领取医疗补助金。医疗补助金的标准由省、自治区、直辖市人民政府规定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4080,'失业保险条例','第二十条',20,'社会保险','第三章 失业保险待遇','失业人员在领取失业保险金期间死亡的，参照当地对在职职工的规定，对其家属一次性发给丧葬补助金和抚恤金。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4082,'失业保险条例','第二十二条',22,'社会保险','第三章 失业保险待遇','城镇企业事业单位成建制跨统筹地区转移，失业人员跨统筹地区流动的，失业保险关系随之转迁。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4083,'失业保险条例','第二十三条',23,'社会保险','第三章 失业保险待遇','失业人员符合城市居民最低生活保障条件的，按照规定享受城市居民最低生活保障待遇。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4084,'失业保险条例','第二十四条',24,'社会保险','第四章 管理和监督','劳动保障行政部门管理失业保险工作，履行下列职责：\n(一)贯彻实施失业保险法律、法规；\n(二)指导社会保险经办机构的工作；\n(三)对失业保险费的征收和失业保险待遇的支付进行监督检查。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4085,'失业保险条例','第二十五条',25,'社会保险','第四章 管理和监督','社会保险经办机构具体承办失业保险工作，履行下列职责：\n(一)负责失业人员的登记、调查、统计；\n(二)按照规定负责失业保险基金的管理；\n(三)按照规定核定失业保险待遇，开具失业人员在指定银行领取失业保险金和其他补助金的单证；\n(四)拨付失业人员职业培训、职业介绍补贴费用；\n(五)为失业人员提供免费咨询服务；\n(六)国家规定由其履行的其他职责。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4086,'失业保险条例','第二十六条',26,'社会保险','第四章 管理和监督','财政部门和审计部门依法对失业保险基金的收支、管理情况进行监督。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4088,'失业保险条例','第二十八条',28,'社会保险','第五章 罚则','不符合享受失业保险待遇条件，骗取失业保险金和其他失业保险待遇的，由社会保险经办机构责令退还；情节严重的，由劳动保障行政部门处骗取金额1倍以上3倍以下的罚款。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4089,'失业保险条例','第二十九条',29,'社会保险','第五章 罚则','社会保险经办机构工作人员违反规定向失业人员开具领取失业保险金或者享受其他失业保险待遇单证，致使失业保险基金损失的，由劳动保障行政部门责令追回；情节严重的，依法给予行政处分。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4090,'失业保险条例','第三十条',30,'社会保险','第五章 罚则','劳动保障行政部门和社会保险经办机构的工作人员滥用职权、徇私舞弊、玩忽职守，造成失业保险基金损失的，由劳动保障行政部门追回损失的失业保险基金；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4091,'失业保险条例','第三十一条',31,'社会保险','第五章 罚则','任何单位、个人挪用失业保险基金的，追回挪用的失业保险基金；有违法所得的，没收违法所得，并入失业保险基金；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4092,'失业保险条例','第三十二条',32,'社会保险','第六章 附则','省、自治区、直辖市人民政府根据当地实际情况，可以决定本条例适用于本行政区域内的社会团体及其专职人员、民办非企业单位及其职工、有雇工的城镇个体工商户及其雇工。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4093,'失业保险条例','第三十三条',33,'社会保险','第六章 附则','本条例自发布之日起施行。1993年4月12日国务院发布的《国有企业职工待业保险规定》同时废止。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4094,'女职工劳动保护特别规定','第一条',1,'其他',NULL,'为了减少和解决女职工在劳动中因生理特点造成的特殊困难，保护女职工健康，制定本规定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4095,'女职工劳动保护特别规定','第二条',2,'其他',NULL,'中华人民共和国境内的国家机关、企业、事业单位、社会团体、个体经济组织以及其他社会组织等用人单位及其女职工，适用本规定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4096,'女职工劳动保护特别规定','第三条',3,'其他',NULL,'用人单位应当加强女职工劳动保护，采取措施改善女职工劳动安全卫生条件，对女职工进行劳动安全卫生知识培训。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4097,'女职工劳动保护特别规定','第四条',4,'其他',NULL,'用人单位应当遵守女职工禁忌从事的劳动范围的规定。用人单位应当将本单位属于女职工禁忌从事的劳动范围的岗位书面告知女职工。\n女职工禁忌从事的劳动范围由本规定附录列示。国务院安全生产监督管理部门会同国务院人力资源社会保障行政部门、国务院卫生行政部门根据经济社会发展情况，对女职工禁忌从事的劳动范围进行调整。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4099,'女职工劳动保护特别规定','第六条',6,'其他',NULL,'女职工在孕期不能适应原劳动的，用人单位应当根据医疗机构的证明，予以减轻劳动量或者安排其他能够适应的劳动。\n对怀孕7个月以上的女职工，用人单位不得延长劳动时间或者安排夜班劳动，并应当在劳动时间内安排一定的休息时间。\n怀孕女职工在劳动时间内进行产前检查，所需时间计入劳动时间。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4100,'女职工劳动保护特别规定','第七条',7,'其他',NULL,'女职工生育享受98天产假，其中产前可以休假15天；难产的，增加产假15天；生育多胞胎的，每多生育1个婴儿，增加产假15天。\n女职工怀孕未满4个月流产的，享受15天产假；怀孕满4个月流产的，享受42天产假。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4102,'女职工劳动保护特别规定','第九条',9,'其他',NULL,'对哺乳未满1周岁婴儿的女职工，用人单位不得延长劳动时间或者安排夜班劳动。\n用人单位应当在每天的劳动时间内为哺乳期女职工安排1小时哺乳时间；女职工生育多胞胎的，每多哺乳1个婴儿每天增加1小时哺乳时间。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4103,'女职工劳动保护特别规定','第十条',10,'其他',NULL,'女职工比较多的用人单位应当根据女职工的需要，建立女职工卫生室、孕妇休息室、哺乳室等设施，妥善解决女职工在生理卫生、哺乳方面的困难。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4104,'女职工劳动保护特别规定','第十一条',11,'其他',NULL,'在劳动场所，用人单位应当预防和制止对女职工的性骚扰。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4105,'女职工劳动保护特别规定','第十二条',12,'其他',NULL,'县级以上人民政府人力资源社会保障行政部门、安全生产监督管理部门按照各自职责负责对用人单位遵守本规定的情况进行监督检查。\n工会、妇女组织依法对用人单位遵守本规定的情况进行监督。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4106,'女职工劳动保护特别规定','第十三条',13,'其他',NULL,'用人单位违反本规定第六条第二款、第七条、第九条第一款规定的，由县级以上人民政府人力资源社会保障行政部门责令限期改正，按照受侵害女职工每人1000元以上5000元以下的标准计算，处以罚款。\n用人单位违反本规定附录第一条、第二条规定的，由县级以上人民政府安全生产监督管理部门责令限期改正，按照受侵害女职工每人1000元以上5000元以下的标准计算，处以罚款。用人单位违反本规定附录第三条、第四条规定的，由县级以上人民政府安全生产监督管理部门责令限期治理，处5万元以上30万元以下的罚款；情节严重的，责令停止有关作业，或者提请有关人民政府按照国务院规定的权限责令关闭。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4107,'女职工劳动保护特别规定','第十四条',14,'其他',NULL,'用人单位违反本规定，侵害女职工合法权益的，女职工可以依法投诉、举报、申诉，依法向劳动人事争议调解仲裁机构申请调解仲裁，对仲裁裁决不服的，依法向人民法院提起诉讼。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4108,'女职工劳动保护特别规定','第十五条',15,'其他',NULL,'用人单位违反本规定，侵害女职工合法权益，造成女职工损害的，依法给予赔偿；用人单位及其直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4109,'女职工劳动保护特别规定','第十六条',16,'其他',NULL,'本规定自公布之日起施行。1988年7月21日国务院发布的《女职工劳动保护规定》同时废止。\n附录：\n女职工禁忌从事的劳动范围\n一、女职工禁忌从事的劳动范围：\n(一)矿山井下作业；\n(二)体力劳动强度分级标准中规定的第四级体力劳动强度的作业；\n(三)每小时负重6次以上、每次负重超过20公斤的作业，或者间断负重、每次负重超过25公斤的作业。\n二、女职工在经期禁忌从事的劳动范围：\n(一)冷水作业分级标准中规定的第二级、第三级、第四级冷水作业；\n(二)低温作业分级标准中规定的第二级、第三级、第四级低温作业；\n(三)体力劳动强度分级标准中规定的第三级、第四级体力劳动强度的作业；\n(四)高处作业分级标准中规定的第三级、第四级高处作业。\n三、女职工在孕期禁忌从事的劳动范围：\n(一)作业场所空气中铅及其化合物、汞及其化合物、苯、镉、铍、砷、氰化物、氮氧化物、一氧化碳、二硫化碳、氯、己内酰胺、氯丁二烯、氯乙烯、环氧乙烷、苯胺、甲醛等有毒物质浓度超过国家职业卫生标准的作业；\n(二)从事抗癌药物、己烯雌酚生产，接触麻醉剂气体等的作业；\n(三)非密封源放射性物质的操作，核事故与放射事故的应急处置；\n(四)高处作业分级标准中规定的高处作业；\n(五)冷水作业分级标准中规定的冷水作业；\n(六)低温作业分级标准中规定的低温作业；\n(七)高温作业分级标准中规定的第三级、第四级的作业；\n(八)噪声作业分级标准中规定的第三级、第四级的作业；\n(九)体力劳动强度分级标准中规定的第三级、第四级体力劳动强度的作业；\n(十)在密闭空间、高压室作业或者潜水作业，伴有强烈振动的作业，或者需要频繁弯腰、攀高、下蹲的作业。\n四、女职工在哺乳期禁忌从事的劳动范围：\n(一)孕期禁忌从事的劳动范围的第一项、第三项、第九项；\n(二)作业场所空气中锰、氟、溴、甲醇、有机磷化合物、有机氯化合物等有毒物质浓度超过国家职业卫生标准的作业。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4110,'工伤保险条例','第一条',1,'社会保险','第一章 总则','为了保障因工作遭受事故伤害或者患职业病的职工获得医疗救治和经济补偿，促进工伤预防和职业康复，分散用人单位的工伤风险，制定本条例。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4111,'工伤保险条例','第二条',2,'社会保险','第一章 总则','中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织和有雇工的个体工商户(以下称用人单位)应当依照本条例规定参加工伤保险，为本单位全部职工或者雇工(以下称职工)缴纳工伤保险费。\n中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织的职工和个体工商户的雇工，均有依照本条例的规定享受工伤保险待遇的权利。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4112,'工伤保险条例','第三条',3,'社会保险','第一章 总则','工伤保险费的征缴按照《社会保险费征缴暂行条例》关于基本养老保险费、基本医疗保险费、失业保险费的征缴规定执行。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4113,'工伤保险条例','第四条',4,'社会保险','第一章 总则','用人单位应当将参加工伤保险的有关情况在本单位内公示。\n用人单位和职工应当遵守有关安全生产和职业病防治的法律法规，执行安全卫生规程和标准，预防工伤事故发生，避免和减少职业病危害。\n职工发生工伤时，用人单位应当采取措施使工伤职工得到及时救治。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4116,'工伤保险条例','第七条',7,'社会保险','第二章 工伤保险基金','工伤保险基金由用人单位缴纳的工伤保险费、工伤保险基金的利息和依法纳入工伤保险基金的其他资金构成。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4117,'工伤保险条例','第八条',8,'社会保险','第二章 工伤保险基金','工伤保险费根据以支定收、收支平衡的原则，确定费率。\n国家根据不同行业的工伤风险程度确定行业的差别费率，并根据工伤保险费使用、工伤发生率等情况在每个行业内确定若干费率档次。行业差别费率及行业内费率档次由国务院社会保险行政部门制定，报国务院批准后公布施行。\n统筹地区经办机构根据用人单位工伤保险费使用、工伤发生率等情况，适用所属行业内相应的费率档次确定单位缴费费率。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4118,'工伤保险条例','第九条',9,'社会保险','第二章 工伤保险基金','国务院社会保险行政部门应当定期了解全国各统筹地区工伤保险基金收支情况，及时提出调整行业差别费率及行业内费率档次的方案，报国务院批准后公布施行。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4119,'工伤保险条例','第十条',10,'社会保险','第二章 工伤保险基金','用人单位应当按时缴纳工伤保险费。职工个人不缴纳工伤保险费。\n用人单位缴纳工伤保险费的数额为本单位职工工资总额乘以单位缴费费率之积。\n对难以按照工资总额缴纳工伤保险费的行业，其缴纳工伤保险费的具体方式，由国务院社会保险行政部门规定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4120,'工伤保险条例','第十一条',11,'社会保险','第二章 工伤保险基金','工伤保险基金逐步实行省级统筹。\n跨地区、生产流动性较大的行业，可以采取相对集中的方式异地参加统筹地区的工伤保险。具体办法由国务院社会保险行政部门会同有关行业的主管部门制定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4121,'工伤保险条例','第十二条',12,'社会保险','第二章 工伤保险基金','工伤保险基金存入社会保障基金财政专户，用于本条例规定的工伤保险待遇，劳动能力鉴定，工伤预防的宣传、培训等费用，以及法律、法规规定的用于工伤保险的其他费用的支付。\n工伤预防费用的提取比例、使用和管理的具体办法，由国务院社会保险行政部门会同国务院财政、卫生行政、安全生产监督管理等部门规定。\n任何单位或者个人不得将工伤保险基金用于投资运营、兴建或者改建办公场所、发放奖金，或者挪作其他用途。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4122,'工伤保险条例','第十三条',13,'社会保险','第二章 工伤保险基金','工伤保险基金应当留有一定比例的储备金，用于统筹地区重大事故的工伤保险待遇支付；储备金不足支付的，由统筹地区的人民政府垫付。储备金占基金总额的具体比例和储备金的使用办法，由省、自治区、直辖市人民政府规定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4123,'工伤保险条例','第十四条',14,'社会保险','第三章 工伤认定','职工有下列情形之一的，应当认定为工伤：\n(一)在工作时间和工作场所内，因工作原因受到事故伤害的；\n(二)工作时间前后在工作场所内，从事与工作有关的预备性或者收尾性工作受到事故伤害的；\n(三)在工作时间和工作场所内，因履行工作职责受到暴力等意外伤害的；\n(四)患职业病的；\n(五)因工外出期间，由于工作原因受到伤害或者发生事故下落不明的；\n(六)在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的；\n(七)法律、行政法规规定应当认定为工伤的其他情形。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4124,'工伤保险条例','第十五条',15,'社会保险','第三章 工伤认定','职工有下列情形之一的，视同工伤：\n(一)在工作时间和工作岗位，突发疾病死亡或者在48小时之内经抢救无效死亡的；\n(二)在抢险救灾等维护国家利益、公共利益活动中受到伤害的；\n(三)职工原在军队服役，因战、因公负伤致残，已取得革命伤残军人证，到用人单位后旧伤复发的。\n职工有前款第(一)项、第(二)项情形的，按照本条例的有关规定享受工伤保险待遇；职工有前款第(三)项情形的，按照本条例的有关规定享受除一次性伤残补助金以外的工伤保险待遇。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4125,'工伤保险条例','第十六条',16,'社会保险','第三章 工伤认定','职工符合本条例第十四条、第十五条的规定，但是有下列情形之一的，不得认定为工伤或者视同工伤：\n(一)故意犯罪的；\n(二)醉酒或者吸毒的；\n(三)自残或者自杀的。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4126,'工伤保险条例','第十七条',17,'社会保险','第三章 工伤认定','职工发生事故伤害或者按照职业病防治法规定被诊断、鉴定为职业病，所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请。遇有特殊情况，经报社会保险行政部门同意，申请时限可以适当延长。\n用人单位未按前款规定提出工伤认定申请的，工伤职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接向用人单位所在地统筹地区社会保险行政部门提出工伤认定申请。\n按照本条第一款规定应当由省级社会保险行政部门进行工伤认定的事项，根据属地原则由用人单位所在地的设区的市级社会保险行政部门办理。\n用人单位未在本条第一款规定的时限内提交工伤认定申请，在此期间发生符合本条例规定的工伤待遇等有关费用由该用人单位负担。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4127,'工伤保险条例','第十八条',18,'社会保险','第三章 工伤认定','提出工伤认定申请应当提交下列材料：\n(一)工伤认定申请表；\n(二)与用人单位存在劳动关系(包括事实劳动关系)的证明材料；\n(三)医疗诊断证明或者职业病诊断证明书(或者职业病诊断鉴定书)。\n工伤认定申请表应当包括事故发生的时间、地点、原因以及职工伤害程度等基本情况。\n工伤认定申请人提供材料不完整的，社会保险行政部门应当一次性书面告知工伤认定申请人需要补正的全部材料。申请人按照书面告知要求补正材料后，社会保险行政部门应当受理。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4128,'工伤保险条例','第十九条',19,'社会保险','第三章 工伤认定','社会保险行政部门受理工伤认定申请后，根据审核需要可以对事故伤害进行调查核实，用人单位、职工、工会组织、医疗机构以及有关部门应当予以协助。职业病诊断和诊断争议的鉴定，依照职业病防治法的有关规定执行。对依法取得职业病诊断证明书或者职业病诊断鉴定书的，社会保险行政部门不再进行调查核实。\n职工或者其近亲属认为是工伤，用人单位不认为是工伤的，由用人单位承担举证责任。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4129,'工伤保险条例','第二十条',20,'社会保险','第三章 工伤认定','社会保险行政部门应当自受理工伤认定申请之日起60日内作出工伤认定的决定，并书面通知申请工伤认定的职工或者其近亲属和该职工所在单位。\n社会保险行政部门对受理的事实清楚、权利义务明确的工伤认定申请，应当在15日内作出工伤认定的决定。\n作出工伤认定决定需要以司法机关或者有关行政主管部门的结论为依据的，在司法机关或者有关行政主管部门尚未作出结论期间，作出工伤认定决定的时限中止。\n社会保险行政部门工作人员与工伤认定申请人有利害关系的，应当回避。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4130,'工伤保险条例','第二十一条',21,'社会保险','第四章 劳动能力鉴定','职工发生工伤，经治疗伤情相对稳定后存在残疾、影响劳动能力的，应当进行劳动能力鉴定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4131,'工伤保险条例','第二十二条',22,'社会保险','第四章 劳动能力鉴定','劳动能力鉴定是指劳动功能障碍程度和生活自理障碍程度的等级鉴定。\n劳动功能障碍分为十个伤残等级，最重的为一级，最轻的为十级。\n生活自理障碍分为三个等级：生活完全不能自理、生活大部分不能自理和生活部分不能自理。\n劳动能力鉴定标准由国务院社会保险行政部门会同国务院卫生行政部门等部门制定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4132,'工伤保险条例','第二十三条',23,'社会保险','第四章 劳动能力鉴定','劳动能力鉴定由用人单位、工伤职工或者其近亲属向设区的市级劳动能力鉴定委员会提出申请，并提供工伤认定决定和职工工伤医疗的有关资料。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4133,'工伤保险条例','第二十四条',24,'社会保险','第四章 劳动能力鉴定','省、自治区、直辖市劳动能力鉴定委员会和设区的市级劳动能力鉴定委员会分别由省、自治区、直辖市和设区的市级社会保险行政部门、卫生行政部门、工会组织、经办机构代表以及用人单位代表组成。\n劳动能力鉴定委员会建立医疗卫生专家库。列入专家库的医疗卫生专业技术人员应当具备下列条件：\n(一)具有医疗卫生高级专业技术职务任职资格；\n(二)掌握劳动能力鉴定的相关知识；\n(三)具有良好的职业品德。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4134,'工伤保险条例','第二十五条',25,'社会保险','第四章 劳动能力鉴定','设区的市级劳动能力鉴定委员会收到劳动能力鉴定申请后，应当从其建立的医疗卫生专家库中随机抽取3名或者5名相关专家组成专家组，由专家组提出鉴定意见。设区的市级劳动能力鉴定委员会根据专家组的鉴定意见作出工伤职工劳动能力鉴定结论；必要时，可以委托具备资格的医疗机构协助进行有关的诊断。\n设区的市级劳动能力鉴定委员会应当自收到劳动能力鉴定申请之日起60日内作出劳动能力鉴定结论，必要时，作出劳动能力鉴定结论的期限可以延长30日。劳动能力鉴定结论应当及时送达申请鉴定的单位和个人。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4135,'工伤保险条例','第二十六条',26,'社会保险','第四章 劳动能力鉴定','申请鉴定的单位或者个人对设区的市级劳动能力鉴定委员会作出的鉴定结论不服的，可以在收到该鉴定结论之日起15日内向省、自治区、直辖市劳动能力鉴定委员会提出再次鉴定申请。省、自治区、直辖市劳动能力鉴定委员会作出的劳动能力鉴定结论为最终结论。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4136,'工伤保险条例','第二十七条',27,'社会保险','第四章 劳动能力鉴定','劳动能力鉴定工作应当客观、公正。劳动能力鉴定委员会组成人员或者参加鉴定的专家与当事人有利害关系的，应当回避。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4137,'工伤保险条例','第二十八条',28,'社会保险','第四章 劳动能力鉴定','自劳动能力鉴定结论作出之日起1年后，工伤职工或者其近亲属、所在单位或者经办机构认为伤残情况发生变化的，可以申请劳动能力复查鉴定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4138,'工伤保险条例','第二十九条',29,'社会保险','第四章 劳动能力鉴定','劳动能力鉴定委员会依照本条例第二十六条和第二十八条的规定进行再次鉴定和复查鉴定的期限，依照本条例第二十五条第二款的规定执行。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4139,'工伤保险条例','第三十条',30,'社会保险','第五章 工伤保险待遇','职工因工作遭受事故伤害或者患职业病进行治疗，享受工伤医疗待遇。\n职工治疗工伤应当在签订服务协议的医疗机构就医，情况紧急时可以先到就近的医疗机构急救。\n治疗工伤所需费用符合工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准的，从工伤保险基金支付。工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准，由国务院社会保险行政部门会同国务院卫生行政部门、食品药品监督管理部门等部门规定。\n职工住院治疗工伤的伙食补助费，以及经医疗机构出具证明，报经办机构同意，工伤职工到统筹地区以外就医所需的交通、食宿费用从工伤保险基金支付，基金支付的具体标准由统筹地区人民政府规定。\n工伤职工治疗非工伤引发的疾病，不享受工伤医疗待遇，按照基本医疗保险办法处理。\n工伤职工到签订服务协议的医疗机构进行工伤康复的费用，符合规定的，从工伤保险基金支付。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4140,'工伤保险条例','第三十一条',31,'社会保险','第五章 工伤保险待遇','社会保险行政部门作出认定为工伤的决定后发生行政复议、行政诉讼的，行政复议和行政诉讼期间不停止支付工伤职工治疗工伤的医疗费用。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4141,'工伤保险条例','第三十二条',32,'社会保险','第五章 工伤保险待遇','工伤职工因日常生活或者就业需要，经劳动能力鉴定委员会确认，可以安装假肢、矫形器、假眼、假牙和配置轮椅等辅助器具，所需费用按照国家规定的标准从工伤保险基金支付。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4142,'工伤保险条例','第三十三条',33,'社会保险','第五章 工伤保险待遇','职工因工作遭受事故伤害或者患职业病需要暂停工作接受工伤医疗的，在停工留薪期内，原工资福利待遇不变，由所在单位按月支付。\n停工留薪期一般不超过12个月。伤情严重或者情况特殊，经设区的市级劳动能力鉴定委员会确认，可以适当延长，但延长不得超过12个月。工伤职工评定伤残等级后，停发原待遇，按照本章的有关规定享受伤残待遇。工伤职工在停工留薪期满后仍需治疗的，继续享受工伤医疗待遇。\n生活不能自理的工伤职工在停工留薪期需要护理的，由所在单位负责。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4143,'工伤保险条例','第三十四条',34,'社会保险','第五章 工伤保险待遇','工伤职工已经评定伤残等级并经劳动能力鉴定委员会确认需要生活护理的，从工伤保险基金按月支付生活护理费。\n生活护理费按照生活完全不能自理、生活大部分不能自理或者生活部分不能自理3个不同等级支付，其标准分别为统筹地区上年度职工月平均工资的50%、40%或者30%。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4144,'工伤保险条例','第三十五条',35,'社会保险','第五章 工伤保险待遇','职工因工致残被鉴定为一级至四级伤残的，保留劳动关系，退出工作岗位，享受以下待遇：\n(一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：一级伤残为27个月的本人工资，二级伤残为25个月的本人工资，三级伤残为23个月的本人工资，四级伤残为21个月的本人工资；\n(二)从工伤保险基金按月支付伤残津贴，标准为：一级伤残为本人工资的90%，二级伤残为本人工资的85%，三级伤残为本人工资的80%，四级伤残为本人工资的75%。伤残津贴实际金额低于当地最低工资标准的，由工伤保险基金补足差额；\n(三)工伤职工达到退休年龄并办理退休手续后，停发伤残津贴，按照国家有关规定享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，由工伤保险基金补足差额。\n职工因工致残被鉴定为一级至四级伤残的，由用人单位和职工个人以伤残津贴为基数，缴纳基本医疗保险费。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4145,'工伤保险条例','第三十六条',36,'社会保险','第五章 工伤保险待遇','职工因工致残被鉴定为五级、六级伤残的，享受以下待遇：\n(一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：五级伤残为18个月的本人工资，六级伤残为16个月的本人工资；\n(二)保留与用人单位的劳动关系，由用人单位安排适当工作。难以安排工作的，由用人单位按月发给伤残津贴，标准为：五级伤残为本人工资的70%，六级伤残为本人工资的60%，并由用人单位按照规定为其缴纳应缴纳的各项社会保险费。伤残津贴实际金额低于当地最低工资标准的，由用人单位补足差额。\n经工伤职工本人提出，该职工可以与用人单位解除或者终止劳动关系，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4147,'工伤保险条例','第三十八条',38,'社会保险','第五章 工伤保险待遇','工伤职工工伤复发，确认需要治疗的，享受本条例第三十条、第三十二条和第三十三条规定的工伤待遇。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4148,'工伤保险条例','第三十九条',39,'社会保险','第五章 工伤保险待遇','职工因工死亡，其近亲属按照下列规定从工伤保险基金领取丧葬补助金、供养亲属抚恤金和一次性工亡补助金：\n(一)丧葬补助金为6个月的统筹地区上年度职工月平均工资；\n(二)供养亲属抚恤金按照职工本人工资的一定比例发给由因工死亡职工生前提供主要生活来源、无劳动能力的亲属。标准为：配偶每月40%，其他亲属每人每月30%，孤寡老人或者孤儿每人每月在上述标准的基础上增加10%。核定的各供养亲属的抚恤金之和不应高于因工死亡职工生前的工资。供养亲属的具体范围由国务院社会保险行政部门规定；\n(三)一次性工亡补助金标准为上一年度全国城镇居民人均可支配收入的20倍。\n伤残职工在停工留薪期内因工伤导致死亡的，其近亲属享受本条第一款规定的待遇。\n一级至四级伤残职工在停工留薪期满后死亡的，其近亲属可以享受本条第一款第(一)项、第(二)项规定的待遇。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4149,'工伤保险条例','第四十条',40,'社会保险','第五章 工伤保险待遇','伤残津贴、供养亲属抚恤金、生活护理费由统筹地区社会保险行政部门根据职工平均工资和生活费用变化等情况适时调整。调整办法由省、自治区、直辖市人民政府规定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4150,'工伤保险条例','第四十一条',41,'社会保险','第五章 工伤保险待遇','职工因工外出期间发生事故或者在抢险救灾中下落不明的，从事故发生当月起3个月内照发工资，从第4个月起停发工资，由工伤保险基金向其供养亲属按月支付供养亲属抚恤金。生活有困难的，可以预支一次性工亡补助金的50%。职工被人民法院宣告死亡的，按照本条例第三十九条职工因工死亡的规定处理。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4151,'工伤保险条例','第四十二条',42,'社会保险','第五章 工伤保险待遇','工伤职工有下列情形之一的，停止享受工伤保险待遇：\n(一)丧失享受待遇条件的；\n(二)拒不接受劳动能力鉴定的；\n(三)拒绝治疗的。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4152,'工伤保险条例','第四十三条',43,'社会保险','第五章 工伤保险待遇','用人单位分立、合并、转让的，承继单位应当承担原用人单位的工伤保险责任；原用人单位已经参加工伤保险的，承继单位应当到当地经办机构办理工伤保险变更登记。\n用人单位实行承包经营的，工伤保险责任由职工劳动关系所在单位承担。\n职工被借调期间受到工伤事故伤害的，由原用人单位承担工伤保险责任，但原用人单位与借调单位可以约定补偿办法。\n企业破产的，在破产清算时依法拨付应当由单位支付的工伤保险待遇费用。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4153,'工伤保险条例','第四十四条',44,'社会保险','第五章 工伤保险待遇','职工被派遣出境工作，依据前往国家或者地区的法律应当参加当地工伤保险的，参加当地工伤保险，其国内工伤保险关系中止；不能参加当地工伤保险的，其国内工伤保险关系不中止。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4154,'工伤保险条例','第四十五条',45,'社会保险','第五章 工伤保险待遇','职工再次发生工伤，根据规定应当享受伤残津贴的，按照新认定的伤残等级享受伤残津贴待遇。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4155,'工伤保险条例','第四十六条',46,'社会保险','第六章 监督管理','经办机构具体承办工伤保险事务，履行下列职责：\n(一)根据省、自治区、直辖市人民政府规定，征收工伤保险费；\n(二)核查用人单位的工资总额和职工人数，办理工伤保险登记，并负责保存用人单位缴费和职工享受工伤保险待遇情况的记录；\n(三)进行工伤保险的调查、统计；\n(四)按照规定管理工伤保险基金的支出；\n(五)按照规定核定工伤保险待遇；\n(六)为工伤职工或者其近亲属免费提供咨询服务。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4156,'工伤保险条例','第四十七条',47,'社会保险','第六章 监督管理','经办机构与医疗机构、辅助器具配置机构在平等协商的基础上签订服务协议，并公布签订服务协议的医疗机构、辅助器具配置机构的名单。具体办法由国务院社会保险行政部门分别会同国务院卫生行政部门、民政部门等部门制定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4157,'工伤保险条例','第四十八条',48,'社会保险','第六章 监督管理','经办机构按照协议和国家有关目录、标准对工伤职工医疗费用、康复费用、辅助器具费用的使用情况进行核查，并按时足额结算费用。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4158,'工伤保险条例','第四十九条',49,'社会保险','第六章 监督管理','经办机构应当定期公布工伤保险基金的收支情况，及时向社会保险行政部门提出调整费率的建议。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4159,'工伤保险条例','第五十条',50,'社会保险','第六章 监督管理','社会保险行政部门、经办机构应当定期听取工伤职工、医疗机构、辅助器具配置机构以及社会各界对改进工伤保险工作的意见。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4160,'工伤保险条例','第五十一条',51,'社会保险','第六章 监督管理','社会保险行政部门依法对工伤保险费的征缴和工伤保险基金的支付情况进行监督检查。\n财政部门和审计机关依法对工伤保险基金的收支、管理情况进行监督。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4161,'工伤保险条例','第五十二条',52,'社会保险','第六章 监督管理','任何组织和个人对有关工伤保险的违法行为，有权举报。社会保险行政部门对举报应当及时调查，按照规定处理，并为举报人保密。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4162,'工伤保险条例','第五十三条',53,'社会保险','第六章 监督管理','工会组织依法维护工伤职工的合法权益，对用人单位的工伤保险工作实行监督。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4163,'工伤保险条例','第五十四条',54,'社会保险','第六章 监督管理','职工与用人单位发生工伤待遇方面的争议，按照处理劳动争议的有关规定处理。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4164,'工伤保险条例','第五十五条',55,'社会保险','第六章 监督管理','有下列情形之一的，有关单位或者个人可以依法申请行政复议，也可以依法向人民法院提起行政诉讼：\n(一)申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定申请不予受理的决定不服的；\n(二)申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定结论不服的；\n(三)用人单位对经办机构确定的单位缴费费率不服的；\n(四)签订服务协议的医疗机构、辅助器具配置机构认为经办机构未履行有关协议或者规定的；\n(五)工伤职工或者其近亲属对经办机构核定的工伤保险待遇有异议的。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4165,'工伤保险条例','第五十六条',56,'社会保险','第七章 法律责任','单位或者个人违反本条例第十二条规定挪用工伤保险基金，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分或者纪律处分。被挪用的基金由社会保险行政部门追回，并入工伤保险基金；没收的违法所得依法上缴国库。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4166,'工伤保险条例','第五十七条',57,'社会保险','第七章 法律责任','社会保险行政部门工作人员有下列情形之一的，依法给予处分；情节严重，构成犯罪的，依法追究刑事责任：\n(一)无正当理由不受理工伤认定申请，或者弄虚作假将不符合工伤条件的人员认定为工伤职工的；\n(二)未妥善保管申请工伤认定的证据材料，致使有关证据灭失的；\n(三)收受当事人财物的。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4167,'工伤保险条例','第五十八条',58,'社会保险','第七章 法律责任','经办机构有下列行为之一的，由社会保险行政部门责令改正，对直接负责的主管人员和其他责任人员依法给予纪律处分；情节严重，构成犯罪的，依法追究刑事责任；造成当事人经济损失的，由经办机构依法承担赔偿责任：\n(一)未按规定保存用人单位缴费和职工享受工伤保险待遇情况记录的；\n(二)不按规定核定工伤保险待遇的；\n(三)收受当事人财物的。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4169,'工伤保险条例','第六十条',60,'社会保险','第七章 法律责任','用人单位、工伤职工或者其近亲属骗取工伤保险待遇，医疗机构、辅助器具配置机构骗取工伤保险基金支出的，由社会保险行政部门责令退还，处骗取金额2倍以上5倍以下的罚款；情节严重，构成犯罪的，依法追究刑事责任。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4170,'工伤保险条例','第六十一条',61,'社会保险','第七章 法律责任','从事劳动能力鉴定的组织或者个人有下列情形之一的，由社会保险行政部门责令改正，处2000元以上1万元以下的罚款；情节严重，构成犯罪的，依法追究刑事责任：\n(一)提供虚假鉴定意见的；\n(二)提供虚假诊断证明的；\n(三)收受当事人财物的。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4171,'工伤保险条例','第六十二条',62,'社会保险','第七章 法律责任','用人单位依照本条例规定应当参加工伤保险而未参加的，由社会保险行政部门责令限期参加，补缴应当缴纳的工伤保险费，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，处欠缴数额1倍以上3倍以下的罚款。\n依照本条例规定应当参加工伤保险而未参加工伤保险的用人单位职工发生工伤的，由该用人单位按照本条例规定的工伤保险待遇项目和标准支付费用。\n用人单位参加工伤保险并补缴应当缴纳的工伤保险费、滞纳金后，由工伤保险基金和用人单位依照本条例的规定支付新发生的费用。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4172,'工伤保险条例','第六十三条',63,'社会保险','第七章 法律责任','用人单位违反本条例第十九条的规定，拒不协助社会保险行政部门对事故进行调查核实的，由社会保险行政部门责令改正，处2000元以上2万元以下的罚款。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4174,'工伤保险条例','第六十五条',65,'社会保险','第八章 附则','公务员和参照公务员法管理的事业单位、社会团体的工作人员因工作遭受事故伤害或者患职业病的，由所在单位支付费用。具体办法由国务院社会保险行政部门会同国务院财政部门规定。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4175,'工伤保险条例','第六十六条',66,'社会保险','第八章 附则','无营业执照或者未经依法登记、备案的单位以及被依法吊销营业执照或者撤销登记、备案的单位的职工受到事故伤害或者患职业病的，由该单位向伤残职工或者死亡职工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇；用人单位不得使用童工，用人单位使用童工造成童工伤残、死亡的，由该单位向童工或者童工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇。具体办法由国务院社会保险行政部门规定。\n前款规定的伤残职工或者死亡职工的近亲属就赔偿数额与单位发生争议的，以及前款规定的童工或者童工的近亲属就赔偿数额与单位发生争议的，按照处理劳动争议的有关规定处理。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4176,'工伤保险条例','第六十七条',67,'社会保险','第八章 附则','本条例自2004年1月1日起施行。本条例施行前已受到事故伤害或者患职业病的职工尚未完成工伤认定的，按照本条例的规定执行。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4177,'社会保险费征缴暂行条例','第一条',1,'社会保险','第一章 总则','为了加强和规范社会保险费征缴工作，保障社会保险金的发放，制定本条例。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4178,'社会保险费征缴暂行条例','第二条',2,'社会保险','第一章 总则','基本养老保险费、基本医疗保险费、失业保险费(以下统称社会保险费)的征收、缴纳，适用本条例。\n本条例所称缴费单位、缴费个人，是指依照有关法律、行政法规和国务院的规定，应当缴纳社会保险费的单位和个人。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4179,'社会保险费征缴暂行条例','第三条',3,'社会保险','第一章 总则','基本养老保险费的征缴范围：国有企业、城镇集体企业、外商投资企业、城镇私营企业和其他城镇企业及其职工，实行企业化管理的事业单位及其职工。\n基本医疗保险费的征缴范围：国有企业、城镇集体企业、外商投资企业、城镇私营企业和其他城镇企业及其职工，国家机关及其工作人员，事业单位及其职工，民办非企业单位及其职工，社会团体及其专职人员。\n失业保险费的征缴范围：国有企业、城镇集体企业、外商投资企业、城镇私营企业和其他城镇企业及其职工，事业单位及其职工。\n省、自治区、直辖市人民政府根据当地实际情况，可以规定将城镇个体工商户纳入基本养老保险、基本医疗保险的范围，并可以规定将社会团体及其专职人员、民办非企业单位及其职工以及有雇工的城镇个体工商户及其雇工纳入失业保险的范围。\n社会保险费的费基、费率依照有关法律、行政法规和国务院的规定执行。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4181,'社会保险费征缴暂行条例','第五条',5,'社会保险','第一章 总则','国务院劳动保障行政部门负责全国的社会保险费征缴管理和监督检查工作。县级以上地方各级人民政府劳动保障行政部门负责本行政区域内的社会保险费征缴管理和监督检查工作。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4184,'社会保险费征缴暂行条例','第八条',8,'社会保险','第二章 征缴管理','企业在办理登记注册时，同步办理社会保险登记。\n前款规定以外的缴费单位应当自成立之日起30日内，向当地社会保险经办机构申请办理社会保险登记。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4185,'社会保险费征缴暂行条例','第九条',9,'社会保险','第二章 征缴管理','缴费单位的社会保险登记事项发生变更或者缴费单位依法终止的，应当自变更或者终止之日起30日内，到社会保险经办机构办理变更或者注销社会保险登记手续。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4187,'社会保险费征缴暂行条例','第十一条',11,'社会保险','第二章 征缴管理','省、自治区、直辖市人民政府规定由税务机关征收社会保险费的，社会保险经办机构应当及时向税务机关提供缴费单位社会保险登记、变更登记、注销登记以及缴费申报的情况。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4188,'社会保险费征缴暂行条例','第十二条',12,'社会保险','第二章 征缴管理','缴费单位和缴费个人应当以货币形式全额缴纳社会保险费。\n缴费个人应当缴纳的社会保险费，由所在单位从其本人工资中代扣代缴。\n社会保险费不得减免。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4189,'社会保险费征缴暂行条例','第十三条',13,'社会保险','第二章 征缴管理','缴费单位未按规定缴纳和代扣代缴社会保险费的，由劳动保障行政部门或者税务机关责令限期缴纳；逾期仍不缴纳的，除补缴欠缴数额外，从欠缴之日起，按日加收2‰的滞纳金。滞纳金并入社会保险基金。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4190,'社会保险费征缴暂行条例','第十四条',14,'社会保险','第二章 征缴管理','征收的社会保险费存入财政部门在国有商业银行开设的社会保障基金财政专户。\n社会保险基金按照不同险种的统筹范围，分别建立基本养老保险基金、基本医疗保险基金、失业保险基金。各项社会保险基金分别单独核算。\n社会保险基金不计征税、费。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4191,'社会保险费征缴暂行条例','第十五条',15,'社会保险','第二章 征缴管理','省、自治区、直辖市人民政府规定由税务机关征收社会保险费的，税务机关应当及时向社会保险经办机构提供缴费单位和缴费个人的缴费情况；社会保险经办机构应当将有关情况汇总，报劳动保障行政部门。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4192,'社会保险费征缴暂行条例','第十六条',16,'社会保险','第二章 征缴管理','社会保险经办机构应当建立缴费记录，其中基本养老保险、基本医疗保险并应当按照规定记录个人账户。社会保险经办机构负责保存缴费记录，并保证其完整、安全。社会保险经办机构应当至少每年向缴费个人发送一次基本养老保险、基本医疗保险个人账户通知单。\n缴费单位、缴费个人有权按照规定查询缴费记录。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4193,'社会保险费征缴暂行条例','第十七条',17,'社会保险','第三章 监督检查','缴费单位应当每年向本单位职工公布本单位全年社会保险费缴纳情况，接受职工监督。\n社会保险经办机构应当定期向社会公告社会保险费征收情况，接受社会监督。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4195,'社会保险费征缴暂行条例','第十九条',19,'社会保险','第三章 监督检查','劳动保障行政部门或者税务机关调查社会保险费征缴违法案件时，有关部门、单位应当给予支持、协助。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4196,'社会保险费征缴暂行条例','第二十条',20,'社会保险','第三章 监督检查','社会保险经办机构受劳动保障行政部门的委托，可以进行与社会保险费征缴有关的检查、调查工作。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4197,'社会保险费征缴暂行条例','第二十一条',21,'社会保险','第三章 监督检查','任何组织和个人对有关社会保险费征缴的违法行为，有权举报。劳动保障行政部门或者税务机关对举报应当及时调查，按照规定处理，并为举报人保密。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4198,'社会保险费征缴暂行条例','第二十二条',22,'社会保险','第三章 监督检查','社会保险基金实行收支两条线管理，由财政部门依法进行监督。\n审计部门依法对社会保险基金的收支情况进行监督。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4199,'社会保险费征缴暂行条例','第二十三条',23,'社会保险','第四章 罚则','缴费单位未按照规定办理社会保险登记、变更登记或者注销登记，或者未按照规定申报应缴纳的社会保险费数额的，由劳动保障行政部门责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员可以处1000元以上5000元以下的罚款；情节特别严重的，对直接负责的主管人员和其他直接责任人员可以处5000元以上10000元以下的罚款。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4200,'社会保险费征缴暂行条例','第二十四条',24,'社会保险','第四章 罚则','缴费单位违反有关财务、会计、统计的法律、行政法规和国家有关规定，伪造、变造、故意毁灭有关账册、材料，或者不设账册，致使社会保险费缴费基数无法确定的，除依照有关法律、行政法规的规定给予行政处罚、纪律处分、刑事处罚外，依照本条例第十条的规定征缴；迟延缴纳的，由劳动保障行政部门或者税务机关依照本条例第十三条的规定决定加收滞纳金，并对直接负责的主管人员和其他直接责任人员处5000元以上20000元以下的罚款。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4201,'社会保险费征缴暂行条例','第二十五条',25,'社会保险','第四章 罚则','缴费单位和缴费个人对劳动保障行政部门或者税务机关的处罚决定不服的，可以依法申请复议；对复议决定不服的，可以依法提起诉讼。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4202,'社会保险费征缴暂行条例','第二十六条',26,'社会保险','第四章 罚则','缴费单位逾期拒不缴纳社会保险费、滞纳金的，由劳动保障行政部门或者税务机关申请人民法院依法强制征缴。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4203,'社会保险费征缴暂行条例','第二十七条',27,'社会保险','第四章 罚则','劳动保障行政部门、社会保险经办机构或者税务机关的工作人员滥用职权、徇私舞弊、玩忽职守，致使社会保险费流失的，由劳动保障行政部门或者税务机关追回流失的社会保险费；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4204,'社会保险费征缴暂行条例','第二十八条',28,'社会保险','第四章 罚则','任何单位、个人挪用社会保险基金的，追回被挪用的社会保险基金；有违法所得的，没收违法所得，并入社会保险基金；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4205,'社会保险费征缴暂行条例','第二十九条',29,'社会保险','第五章 附则','省、自治区、直辖市人民政府根据本地实际情况，可以决定本条例适用于本行政区域内工伤保险费和生育保险费的征收、缴纳。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4206,'社会保险费征缴暂行条例','第三十条',30,'社会保险','第五章 附则','税务机关、社会保险经办机构征收社会保险费，不得从社会保险基金中提取任何费用，所需经费列入预算，由财政拨付。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4207,'社会保险费征缴暂行条例','第三十一条',31,'社会保险','第五章 附则','本条例自发布之日起施行。',NULL,NULL,'doc_import',NULL,'2026-09-17 16:32:57','2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4208, '职工带薪年休假条例', '第一条', 1, '工作时间与休息休假', NULL, '为了维护职工休息休假权利，调动职工工作积极性，根据劳动法和公务员法，制定本条例。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4209, '职工带薪年休假条例', '第二条', 2, '工作时间与休息休假', NULL, '机关、团体、企业、事业单位、民办非企业单位、有雇工的个体工商户等单位的职工连续工作1年以上的，享受带薪年休假(以下简称年休假)。单位应当保证职工享受年休假。\n职工在年休假期间享受与正常工作期间相同的工资收入。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4212, '职工带薪年休假条例', '第五条', 5, '工作时间与休息休假', NULL, '单位根据生产、工作的具体情况，并考虑职工本人意愿，统筹安排职工年休假。\n年休假在1个年度内可以集中安排，也可以分段安排，一般不跨年度安排。单位因生产、工作特点确有必要跨年度安排职工年休假的，可以跨1个年度安排。\n单位确因工作需要不能安排职工休年休假的，经职工本人同意，可以不安排职工休年休假。对职工应休未休的年休假天数，单位应当按照该职工日工资收入的300%支付年休假工资报酬。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:31');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4215, '职工带薪年休假条例', '第八条', 8, '工作时间与休息休假', NULL, '职工与单位因年休假发生的争议，依照国家有关法律、行政法规的规定处理。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:32');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4216, '职工带薪年休假条例', '第九条', 9, '工作时间与休息休假', NULL, '国务院人事部门、国务院劳动保障部门依据职权，分别制定本条例的实施办法。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:32');
INSERT INTO `law_article` (`id`, `law_name`, `article_no`, `seq`, `category`, `title`, `content`, `keywords`, `effective_date`, `source`, `source_id`, `created_at`, `updated_at`) VALUES (4217, '职工带薪年休假条例', '第十条', 10, '工作时间与休息休假', NULL, '本条例自2008年1月1日起施行。', NULL, NULL, 'doc_import', NULL, '2026-09-17 16:32:57', '2026-09-17 16:48:32');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (1, 1, '老板拖欠我3万工资2个月了怎么办？', '拖欠用人单位拖欠工资属于违法行为。您可以：1) 与公司协商并保留书面催告记录；2) 向当地劳动保障监察大队投诉；3) 直接申请劳动仲裁，无需先投诉。依据《劳动合同法》第三十八条，用人单位未及时足额支付劳动报酬的，劳动者可以解除劳动合同并要求经济补偿。', '劳动报酬', 1, 42, '2026-08-01 14:04:00', '2026-09-14 20:41:08');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (2, 2, '试用期被辞退有补偿吗？', '要看辞退理由。若公司不能证明您“不符合录用条件”，属于违法解除，应支付 2N 赔偿金；若确实不符合录用条件且有证据，则无补偿。试用期不是“随意期”，用人单位仍需举证。', '解除与终止', 1, 38, '2026-08-22 17:49:00', '2026-09-14 20:41:08');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (3,3,'没签劳动合同怎么证明劳动关系？','可凭以下证据形成证据链：工资银行流水、工牌工服照片、考勤打卡截图、工作群聊天记录、同事证言、社保缴纳记录、盖有公章的文件。依据《劳动合同法》第八十二条，超过一个月未签合同的，可主张二倍工资。','劳动合同',1,51,'2026-08-18 08:44:00','2026-09-14 20:41:08');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (4, 4, '公司要求加班但不给加班费合法吗？', '不合法。《劳动法》第四十四条规定，延长工作时间应支付不低于 150% 的工资，休息日不能补休的支付 200%，法定节假日支付 300%。若公司长期不支付，可申请仲裁并主张解除劳动合同的经济补偿。', '劳动报酬', 1, 33, '2026-08-30 12:50:00', '2026-09-14 20:41:08');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (5,5,'试用期最长能约定多久？','按《劳动合同法》第十九条：合同期3个月以上不满1年的，试用期不超过1个月；1年以上不满3年的，不超过2个月；3年以上及无固定期限的，不超过6个月。同一单位与同一劳动者只能约定一次试用期。','劳动合同',1,47,'2026-08-16 12:23:00','2026-09-14 20:41:08');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (7, 7, '竞业限制有补偿吗？', '有。依据《劳动合同法》第二十三条，约定竞业限制的，须在竞业限制期限内按月给予经济补偿。用人单位三个月未支付补偿的，劳动者可请求解除竞业限制约定。补偿标准一般不低于离职前十二个月平均工资的30%。', '保密与竞业限制', 1, 26, '2026-08-18 20:49:00', '2026-09-14 20:41:08');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (8,8,'公司不缴社保怎么维权？','《社会保险法》第五十八条要求用人单位自用工之日起30日内办理社保登记。公司不缴的，可向社保征收机构投诉要求补缴，也可依据《劳动合同法》第三十八条以此为由解除劳动合同并主张经济补偿。','社会保险',1,35,'2026-08-09 19:09:00','2026-09-14 20:41:08');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (9,9,'入职公司收了我500元押金合法吗？','不合法。《劳动合同法》第九条明确规定，用人单位招用劳动者不得收取财物。您有权要求返还，并可向劳动行政部门举报，由行政部门责令限期退还并按每人500元以上2000元以下标准处以罚款。','其他',1,22,'2026-08-18 13:09:00','2026-09-14 20:41:08');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (10,10,'申请劳动仲裁的时效是多久？','一般为一年，从知道或应当知道权利被侵害之日起算。但拖欠劳动报酬的争议，在劳动关系存续期间不受一年限制；劳动关系终止的，应自终止之日起一年内提出。','其他',1,18,'2026-08-21 08:23:00','2026-09-14 20:41:08');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (11,11,'公司单方面调岗降薪我能拒绝吗？','劳动合同的变更需双方协商一致并采用书面形式。公司未经协商单方调岗降薪，属于违约。您可以书面拒绝，若公司据此解除合同，属于违法解除，可主张 2N 赔偿金。','劳动合同',1,31,'2026-08-28 11:16:00','2026-09-14 20:41:08');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (12, 12, '经济补偿N、N+1、2N分别是什么？', 'N 是法定经济补偿，按工作年限每满一年一个月工资（《劳动合同法》第四十七条）；N+1 是未提前30日书面通知时额外支付一个月工资的代通知金；2N 是用人单位违法解除时的赔偿金（第八十七条）。', '解除与终止', 1, 56, '2026-08-14 14:47:00', '2026-09-14 20:41:08');
INSERT INTO `qa_record` (`id`, `user_id`, `question`, `answer`, `category`, `status`, `like_count`, `created_at`, `updated_at`) VALUES (13, 13, '公司拖欠我三个月工资，还没签劳动合同，我该怎么办？', '根据您描述的情况，初步分析如下：\n\n【初步结论】您的情况在现行劳动法律法规中有明确依据，建议优先通过书面方式主张权利，并注意保存证据。\n\n【法律依据】\n1. 《中华人民共和国劳动合同法》第十条（订立书面劳动合同）：建立劳动关系，应当订立书面劳动合同。已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。\n2. 《中华人民共和国劳动合同法》第十九条（试用期期限）：劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。同一用人单位与同一劳动者只能约定一次试用期。\n3. 《中华人民共和国劳动合同法》第二十条（试用期工资）：劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。\n\n【建议步骤】\n1. 固定证据：保留劳动合同、工资流水、考勤记录、聊天记录等；\n2. 书面沟通：以邮件或微信向用人单位提出明确诉求，留痕；\n3. 行政投诉：向用工所在地劳动保障监察大队投诉；\n4. 申请仲裁：向劳动合同履行地或用人单位所在地的劳动人事争议仲裁委员会申请仲裁，一般时效为一年。\n\n提示：以上内容由系统依据法规库自动生成，仅供参考，具体案件建议咨询专业律师。', '劳动报酬', 1, 1, '2026-09-14 21:00:11', '2026-09-14 21:00:10');
