INSERT INTO `quiz_question` (`id`, `category`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `created_at`) VALUES (8, '保密与竞业限制', '竞业限制期限最长不得超过？', '1年', '2年', '3年', '5年', 'B', '《劳动合同法》第二十四条规定的二年。', 1, '2026-09-14 20:41:08');
INSERT INTO `quiz_question` (`id`, `category`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `created_at`) VALUES (9,'其他','劳动争议申请仲裁的一般时效期间是？','6个月','1年','2年','3年','B','《劳动争议调解仲裁法》第二十七条。',1,'2026-09-14 20:41:08');
INSERT INTO `quiz_question` (`id`, `category`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `created_at`) VALUES (10,'劳动合同','同一用人单位与同一劳动者可以约定几次试用期？','1次','2次','3次','不限次数','A','《劳动合同法》第十九条：只能约定一次试用期。',1,'2026-09-14 20:41:08');
INSERT INTO `quiz_question` (`id`, `category`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `created_at`) VALUES (11, '劳动报酬', '试用期工资不得低于劳动合同约定工资的？', '50%', '60%', '70%', '80%', 'D', '《劳动合同法》第二十条：不得低于约定工资的80%。', 2, '2026-09-14 20:41:08');
INSERT INTO `quiz_question` (`id`, `category`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `created_at`) VALUES (12, '解除与终止', '用人单位未及时足额支付劳动报酬的，劳动者可以？', '只能等待', '解除劳动合同并主张经济补偿', '必须先申请仲裁才能离职', '无权解除', 'B', '《劳动合同法》第三十八条规定的即时解除权。', 3, '2026-09-14 20:41:08');
